@Component({
  selector: 'ngx-biplot',
  standalone: true,
  imports: [CommonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="ngx-biplot" (mouseleave)="onMouseLeave()">
      <!-- Toolbar with Export option -->
      <div class="chart-header" (mousemove)="$event.stopPropagation()" (mouseleave)="onMouseLeave()">
        <div class="chart-title-space"></div>
        @if (showExport()) {
          <div class="chart-export-menu">
            <button class="export-trigger" (click)="toggleExportMenu($event)" aria-label="Export Menu">📤 Export</button>
            @if (exportMenuOpen()) {
              <div class="export-dropdown">
                <button (click)="onExport('json')">📊 Export JSON</button>
                <button (click)="onExport('csv')">📄 Export CSV</button>
                <button (click)="onExport('svg')">🖼️ Export SVG</button>
                <button (click)="onExport('pdf')">📕 Export PDF</button>
              </div>
            }
          </div>
        }
      </div>

      <svg
        #svgEl
        class="biplot-svg"
        [attr.width]="'100%'"
        [attr.height]="svgHeight()"
      >
        <!-- Arrowhead Marker Definition -->
        <defs>
          <marker
            id="vector-arrow"
            viewBox="0 0 10 10"
            refX="6"
            refY="5"
            markerWidth="6"
            markerHeight="6"
            orient="auto-start-reverse"
          >
            <path d="M 0 1.5 L 10 5 L 0 8.5 z" fill="#ef4444" />
          </marker>
        </defs>

        <g [attr.transform]="'translate(' + margin().left + ',' + margin().top + ')'">

          <!-- Axis Lines (Passing through Origin 0,0) -->
          <line
            [attr.x1]="0"
            [attr.x2]="innerW()"
            [attr.y1]="originY()"
            [attr.y2]="originY()"
            class="axis-line origin-axis"
          />
          <line
            [attr.x1]="originX()"
            [attr.x2]="originX()"
            [attr.y1]="0"
            [attr.y2]="innerH()"
            class="axis-line origin-axis"
          />

          <!-- Tick Marks on X Axis -->
          @for (tick of xTicks(); track tick) {
            <g [attr.transform]="'translate(' + xPos(tick) + ', 0)'">
              <line
                [attr.y1]="originY() - 3"
                [attr.y2]="originY() + 3"
                class="tick-line"
              />
              @if (tick !== 0) {
                <text
                  [attr.y]="originY() + 14"
                  text-anchor="middle"
                  class="tick-label"
                >
                  {{ formatNumber(tick) }}
                </text>
              }
            </g>
          }

          <!-- Tick Marks on Y Axis -->
          @for (tick of yTicks(); track tick) {
            <g [attr.transform]="'translate(0, ' + yPos(tick) + ')'">
              <line
                [attr.x1]="originX() - 3"
                [attr.x2]="originX() + 3"
                class="tick-line"
              />
              @if (tick !== 0) {
                <text
                  [attr.x]="originX() - 8"
                  text-anchor="end"
                  dominant-baseline="middle"
                  class="tick-label"
                >
                  {{ formatNumber(tick) }}
                </text>
              }
            </g>
          }

          <!-- Zero Label at Origin -->
          <text
            [attr.x]="originX() - 8"
            [attr.y]="originY() + 12"
            text-anchor="end"
            class="tick-label origin-label"
          >
            0
          </text>

          <!-- Vector Loadings (Variables) -->
          @for (vec of computedVectors(); track vec.label) {
            <g class="vector-group">
              <line
                [attr.x1]="originX()"
                [attr.y1]="originY()"
                [attr.x2]="vec.x2"
                [attr.y2]="vec.y2"
                class="vector-line"
                marker-end="url(#vector-arrow)"
              />
              <text
                [attr.x]="vec.x2 + (vec.x2 > originX() ? 6 : -6)"
                [attr.y]="vec.y2 + (vec.y2 > originY() ? 6 : -6)"
                [attr.text-anchor]="vec.x2 > originX() ? 'start' : 'end'"
                dominant-baseline="middle"
                class="vector-label"
              >
                {{ vec.label }}
              </text>
            </g>
          }

          <!-- Scatter Points (Observations) -->
          @for (pt of computedPoints(); track pt.label; let i = $index) {
            <g
              class="point-group"
              [class.dimmed]="hoveredPointIndex() !== null && hoveredPointIndex() !== i"
              (mouseenter)="onPointHover(i, $event)"
              (mousemove)="onMouseMove($event)"
            >
              <circle
                [attr.cx]="pt.cx"
                [attr.cy]="pt.cy"
                [attr.r]="hoveredPointIndex() === i ? 7 : 5"
                [attr.fill]="pt.color"
                [attr.stroke]="'#ffffff'"
                [attr.stroke-width]="hoveredPointIndex() === i ? 2 : 1"
                class="biplot-point"
              />
              @if (showLabels() || hoveredPointIndex() === i) {
                <text
                  [attr.x]="pt.cx + 8"
                  [attr.y]="pt.cy - 6"
                  class="point-label"
                >
                  {{ pt.label }}
                </text>
              }
            </g>
          }
        </g>
      </svg>

      <!-- Glassmorphic Tooltip -->
      @if (tooltip(); as t) {
        <div class="chart-tooltip" [style.left.px]="tooltipX()" [style.top.px]="tooltipY()">
          <div class="tt-cat">{{ t.label }}</div>
          @if (t.group) {
            <div class="tt-row">
              <span class="tt-name">Group</span>
              <span class="tt-val">{{ t.group }}</span>
            </div>
          }
          <div class="tt-row">
            <span class="tt-name">PC1 (X)</span>
            <span class="tt-val">{{ formatNumber(t.x) }}</span>
          </div>
          <div class="tt-row">
            <span class="tt-name">PC2 (Y)</span>
            <span class="tt-val">{{ formatNumber(t.y) }}</span>
          </div>
        </div>
      }
    </div>
  `,
  styles: [`
    :host {
      display: block;
    }
    .ngx-biplot {
      background: var(--ngx-chart-bg, #ffffff);
      border-radius: 16px;
      padding: 16px;
      box-sizing: border-box;
      font-family: var(--ngx-font-family, system-ui, sans-serif);
      position: relative;
      width: 100%;
    }
    .biplot-svg {
      display: block;
