    .axis-line {
      stroke: var(--ngx-chart-axis, #cbd5e1);
      stroke-width: 1;
    }
    .origin-axis {
      stroke: var(--ngx-chart-axis-strong, #94a3b8);
      stroke-width: 1.5;
      stroke-dasharray: 3,3;
    }
    .tick-line {
      stroke: var(--ngx-chart-axis, #cbd5e1);
      stroke-width: 1.5;
    }
    .tick-label, .point-label {
      font-size: 11px;
      fill: var(--ngx-chart-axis-text, #64748b);
      font-weight: 550;
