              @if (item.icon) { <span class="breadcrumb-icon">{{ item.icon }}</span> }
              {{ item.label }}
            </button>
          }
          @if (!last) { <span class="breadcrumb-separator" aria-hidden="true">{{ separator() }}</span> }
        }
      }
    </nav>
  `,
  styles: [`
