    }
    .breadcrumb-item.active {
      color: var(--ngx-breadcrumb-active, #495057);
      background-color: var(--ngx-breadcrumb-active-bg, rgba(73, 80, 87, 0.08));
      cursor: default;
      font-weight: 600;
    }
    .breadcrumb-btn {
      background: none;
      border: none;
      cursor: pointer;
      font-family: inherit;
      font-size: inherit;
      padding: 2px 8px;
    }
    .breadcrumb-ellipsis {
      font-weight: 700;
      letter-spacing: 1px;
      min-width: 28px;
      justify-content: center;
    }
    .breadcrumb-icon { font-size: 14px; }
