export interface CalendarEvent {
  id?: string;
  title: string;
  date: Date | string;
  color?: string;
  description?: string;
}

export interface CalendarCell {
  date: Date;
  dayNumber: number;
  isCurrentMonth: boolean;
  isToday: boolean;
  isSelected: boolean;
  isFocused: boolean;
  events: CalendarEvent[];
  isRangeStart?: boolean;
  isRangeEnd?: boolean;
  isInRange?: boolean;
  isDisabled?: boolean;
}

@Component({
