export interface CandlestickItem {
  date: string | Date;
  open: number;
  high: number;
  low: number;
  close: number;
}

interface HeikinAshiCalculatedItem {
  date: string | Date;
  open: number;
  high: number;
  low: number;
  close: number;
  original: CandlestickItem;
}

