          <div class="tt-row detail-row range-row">
            <span class="tt-sub-label">Range Depth:</span>
            <span class="tt-val highlight">{{ fmtNum(t.high - t.low) }}</span>
          </div>
        </div>
      }
    </div>
  `,
  styles: [`
