export class ErrorBarComponent {
  data = input<{ label: string; value: number; errorPlus: number; errorMinus: number; color?: string }[]>([]);
  chartType = input<'line' | 'bar'>('line');
  height = input<number>(300);
  showGrid = input<boolean>(true);
  colors = input<string[]>(CHART_COLORS);
  showExport = input<boolean>(false);
  labelFormatter = input<((v: number) => string) | undefined>(undefined);
  tooltipTemplate = input<TemplateRef<any> | null>(null);

  containerWidth = signal<number>(500);
  hoveredIndex = signal<number | null>(null);
  tooltip = signal<any | null>(null);
  tooltipX = signal<number>(0);
  tooltipY = signal<number>(0);
  exportMenuOpen = signal(false);

  svgEl = viewChild<ElementRef<SVGElement>>('svgEl');

  margin = computed(() => ({
    top: 25,
    right: 25,
    bottom: 35,
    left: 45
  }));

  svgHeight = computed(() => this.height());
  innerW = computed(() => Math.max(10, this.containerWidth() - this.margin().left - this.margin().right));
  innerH = computed(() => Math.max(10, this.svgHeight() - this.margin().top - this.margin().bottom));

  capWidth = computed(() => Math.max(6, Math.min(14, this.innerW() / (this.data().length || 1) * 0.15)));
  barWidth = computed(() => Math.max(10, (this.innerW() / (this.data().length || 1)) * 0.6));

  yDomain = computed(() => {
    const raw = this.data();
    if (raw.length === 0) return { min: 0, max: 100 };

    const mins = raw.map(d => d.value - d.errorMinus);
    const maxs = raw.map(d => d.value + d.errorPlus);

    const minVal = Math.min(0, ...mins);
    const maxVal = Math.max(10, ...maxs);
    const range = maxVal - minVal;

    return {
      min: minVal - range * 0.05,
      max: maxVal + range * 0.05
    };
  });

  yTicks = computed(() => {
    const domain = this.yDomain();
    return niceTicks(domain.min, domain.max, 5);
  });

  yDomainMin = computed(() => this.yTicks()[0] || 0);
  yDomainMax = computed(() => this.yTicks()[this.yTicks().length - 1] || 100);

  computedPoints = computed<ErrorBarPoint[]>(() => {
    const raw = this.data();
    const count = raw.length;
    if (count === 0) return [];

    const w = this.innerW();
    const h = this.innerH();
    const yMin = this.yDomainMin();
    const yMax = this.yDomainMax();

    return raw.map((d, i) => {
      // Scale X evenly
      const x = count <= 1 ? w / 2 : scale(i, 0, count - 1, w * 0.08, w * 0.92);
      const y = scale(d.value, yMin, yMax, h, 0);
      const yTop = scale(d.value + d.errorPlus, yMin, yMax, h, 0);
      const yBottom = scale(d.value - d.errorMinus, yMin, yMax, h, 0);

      return {
        ...d,
        x,
        y,
        yTop,
        yBottom
      };
    });
  });

  linePath = computed<string>(() => {
    const pts = this.computedPoints();
    if (pts.length < 2) return '';
    return pts.reduce((acc, pt, idx) => {
      return idx === 0 ? `M ${pt.x} ${pt.y}` : `${acc} L ${pt.x} ${pt.y}`;
    }, '');
  });

  constructor() {
    const hostEl = inject(ElementRef).nativeElement;
    if (typeof ResizeObserver !== 'undefined') {
      const resizeObserver = new ResizeObserver(entries => {
        if (!entries || entries.length === 0) return;
        const width = entries[0].contentRect.width;
        if (width > 0) {
          this.containerWidth.set(width);
        }
      });
      resizeObserver.observe(hostEl);
      inject(DestroyRef).onDestroy(() => resizeObserver.disconnect());
    }
  }

  yPos(val: number): number {
    return scale(val, this.yDomainMin(), this.yDomainMax(), this.innerH(), 0);
  }

  barY(val: number): number {
    const yVal = this.yPos(val);
    const yZero = this.yPos(0);
    return Math.min(yVal, yZero);
  }

  barHeight(val: number): number {
    const yVal = this.yPos(val);
    const yZero = this.yPos(0);
    return Math.abs(yVal - yZero);
  }

  pointColor(pt: ErrorBarPoint, i: number): string {
    if (pt.color) return pt.color;
    const colorsList = this.colors();
    return colorsList[i % colorsList.length];
  }

  lineColor(): string {
    return this.colors()[0] || '#4a90d9';
  }

  whiskerColor(): string {
    return '#64748b';
  }

  onPointHover(idx: number) {
    this.hoveredIndex.set(idx);
    const pt = this.computedPoints()[idx];
    if (pt) {
      this.tooltip.set(pt);
    }
  }

  onMouseMove(event: MouseEvent) {
    const el = event.currentTarget as SVGElement;
    const container = el.closest('.ngx-error-bar');
    if (container) {
      const rect = container.getBoundingClientRect();
      this.tooltipX.set(event.clientX - rect.left);
      this.tooltipY.set(event.clientY - rect.top);
    }
  }

  onMouseLeave() {
    this.hoveredIndex.set(null);
    this.tooltip.set(null);
  }

  toggleExportMenu(event: MouseEvent): void {
    event.stopPropagation();
    this.exportMenuOpen.set(!this.exportMenuOpen());
  }

  @HostListener('document:click')
  closeExportMenu(): void {
    this.exportMenuOpen.set(false);
  }

  onExport(type: 'json' | 'csv' | 'svg' | 'pdf'): void {
    this.exportMenuOpen.set(false);
    if (type === 'json') this.exportToJson();
    else if (type === 'csv') this.exportToCsv();
    else if (type === 'svg') this.exportToSvg();
    else if (type === 'pdf') this.exportToPdf();
  }

  exportToCsv(): void {
    const pts = this.computedPoints();
    if (!pts.length) return;

    let csv = 'Label,Value,Error Plus,Error Minus\n';
    pts.forEach(p => {
      csv += `"${p.label}",${p.value},${p.errorPlus},${p.errorMinus}\n`;
    });

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'error-bar-data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToJson(): void {
    const pts = this.computedPoints();
    if (!pts.length) return;

    const data = pts.map(p => ({
      label: p.label,
      value: p.value,
      errorPlus: p.errorPlus,
      errorMinus: p.errorMinus
    }));

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'error-bar-data.json');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToSvg(): void {
    const svg = this.svgEl()?.nativeElement;
    if (!svg) return;
    const serializer = new XMLSerializer();
    let source = serializer.serializeToString(svg);
    if (!source.match(/^<svg[^>]+xmlns="http\:\/\/www\.w3\.org\/2000\/svg"/)) {
      source = source.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
    }
    if (!source.match(/^<svg[^>]+xmlns\:xlink="http\:\/\/www\.w3\.org\/1999\/xlink"/)) {
      source = source.replace(/^<svg/, '<svg xmlns:xlink="http://www.w3.org/1999/xlink"');
    }
    source = '<?xml version="1.0" encoding="utf-8"?>\n' + source;
    const blob = new Blob([source], { type: 'image/svg+xml;charset=utf-8' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'error-bar.svg');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToPdf(): void {
    const svg = this.svgEl()?.nativeElement;
    if (!svg || typeof window === 'undefined' || typeof document === 'undefined') return;

    const printWindow = window.open('', '_blank');
    if (!printWindow) {
      alert('Pop-up blocker prevented printing. Please allow pop-ups for this site.');
      return;
    }

    const svgHtml = svg.outerHTML;
    const printTemplate = `
      <html>
      <head>
        <title>Error Bar Export</title>
        <style>
          body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; padding: 24px; color: #0f172a; text-align: center; }
          .header { display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #e2e8f0; padding-bottom: 12px; margin-bottom: 24px; text-align: left; }
          .title { font-size: 20px; font-weight: bold; }
          .date { font-size: 12px; color: #64748b; }
          .chart-container { display: inline-block; margin-top: 24px; border: 1px solid #cbd5e1; border-radius: 12px; padding: 20px; background: #ffffff; width: 90%; }
          svg { width: 100%; height: auto; }
          .tick-label { font-size: 10px; fill: #64748b; font-weight: 550; }
          @media print {
            body { padding: 0; }
            .chart-container { border: none; padding: 0; width: 100%; }
          }
        </style>
      </head>
      <body>
        <div class="header">
          <div class="title">Error Bar Uncertainty Analysis</div>
          <div class="date">${new Date().toLocaleString()}</div>
        </div>
        <div class="chart-container">
          ${svgHtml}
        </div>
        <script>
          window.onload = function() {
            window.print();
            setTimeout(function() { window.close(); }, 500);
          };
        </script>
      </body>
      </html>
    `;

    printWindow.document.write(printTemplate);
    printWindow.document.close();
  }

  formatNumber(v: number): string {
    return fmtNum(v);
  }
}

import { Injectable } from '@angular/core';
import { GanttTask } from '../models/gantt-task.model';
import { GanttGroup } from '../models/gantt-group.model';

export interface FlatRow {
  task: GanttTask;
  /** Additional tasks that share this row (same rowId). */
  extraTasks: GanttTask[];
  depth: number;
  rowIndex: number;
  hasChildren: boolean;
  isVisible: boolean;
  /** Set when this row is a group header. */
  group?: GanttGroup;
  /** Whether this is a group header row. */
  isGroupHeader: boolean;
}

interface RowGroup {
  primary: GanttTask;
  extra: GanttTask[];
}

@Injectable()
export class GanttLayoutService {
  flattenTasks(tasks: GanttTask[], groups?: GanttGroup[]): FlatRow[] {
    if (groups && groups.length > 0) {
      return this.flattenWithGroups(tasks, groups);
    }
    return this.flattenTree(tasks);
  }

  private flattenTree(tasks: GanttTask[]): FlatRow[] {
    const childrenMap = new Map<string | null, GanttTask[]>();
    for (const task of tasks) {
      const parentId = task.parentId;
      if (!childrenMap.has(parentId)) {
        childrenMap.set(parentId, []);
      }
      childrenMap.get(parentId)!.push(task);
    }

    const rows: FlatRow[] = [];
    let rowIndex = 0;

    const traverse = (parentId: string | null, depth: number, parentVisible: boolean): void => {
      const children = childrenMap.get(parentId) || [];

      // Group children by rowId, preserving original order for primary tasks.
      const rowGroups: RowGroup[] = [];
      const rowIdToGroup = new Map<string, RowGroup>();

      for (const task of children) {
        if (task.rowId) {
          const existing = rowIdToGroup.get(task.rowId);
          if (existing) {
            existing.extra.push(task);
          } else {
            const group = { primary: task, extra: [] as GanttTask[] };
            rowGroups.push(group);
            rowIdToGroup.set(task.rowId, group);
          }
        } else {
          rowGroups.push({ primary: task, extra: [] });
        }
      }

      for (const { primary: task, extra: extraTasks } of rowGroups) {
        const hasChildren = childrenMap.has(task.id) && childrenMap.get(task.id)!.length > 0;
        const isVisible = parentVisible;
        rows.push({ task, extraTasks, depth, rowIndex: isVisible ? rowIndex : -1, hasChildren, isVisible, isGroupHeader: false });
        if (isVisible) rowIndex++;
        const childVisible = isVisible && !task.collapsed;
        traverse(task.id, depth + 1, childVisible);
      }
    };

    traverse(null, 0, true);
    return rows;
  }

  private flattenWithGroups(tasks: GanttTask[], groups: GanttGroup[]): FlatRow[] {
    const rows: FlatRow[] = [];
    let rowIndex = 0;

    // Build a map of tasks by group_id
    const tasksByGroup = new Map<string, GanttTask[]>();
    const ungroupedTasks: GanttTask[] = [];
    for (const task of tasks) {
      if (task.group_id) {
        if (!tasksByGroup.has(task.group_id)) {
          tasksByGroup.set(task.group_id, []);
        }
        tasksByGroup.get(task.group_id)!.push(task);
      } else {
        ungroupedTasks.push(task);
      }
    }

    for (const group of groups) {
      // Create a pseudo-task for the group header
      const groupTask: GanttTask = {
        id: `__group__${group.id}`,
        name: group.title,
        start: new Date(),
        end: new Date(),
        progress: 0,
        parentId: null,
        collapsed: group.expanded === false,
        isMilestone: false,
        cssClass: group.class,
      };

      const groupTasks = tasksByGroup.get(group.id) || [];

      // Calculate group date range
      if (groupTasks.length > 0) {
        let minStart = groupTasks[0].start.getTime();
        let maxEnd = groupTasks[0].end.getTime();
        let totalProgress = 0;
        for (const t of groupTasks) {
          if (t.start.getTime() < minStart) minStart = t.start.getTime();
          if (t.end.getTime() > maxEnd) maxEnd = t.end.getTime();
          totalProgress += t.progress;
        }
        groupTask.start = new Date(minStart);
        groupTask.end = new Date(maxEnd);
        groupTask.progress = Math.round(totalProgress / groupTasks.length);
      }

      const hasChildren = groupTasks.length > 0;
      rows.push({
        task: groupTask,
        extraTasks: [],
        depth: 0,
        rowIndex: rowIndex++,
        hasChildren,
        isVisible: true,
        group,
        isGroupHeader: true,
      });

      if (group.expanded !== false) {
        // Flatten group tasks using tree logic
        const groupRows = this.flattenTree(groupTasks);
        for (const r of groupRows) {
          if (r.isVisible) {
            r.rowIndex = rowIndex++;
            r.depth += 1; // indent within group
          }
          rows.push(r);
        }
      }
    }

    // Also flatten any ungrouped tasks
    if (ungroupedTasks.length > 0) {
      const ungroupedRows = this.flattenTree(ungroupedTasks);
      for (const r of ungroupedRows) {
        if (r.isVisible) {
          r.rowIndex = rowIndex++;
        }
        rows.push(r);
      }
    }

    return rows;
  }
}

import {
  Component, ChangeDetectionStrategy, input, computed, signal,
