} from '@angular/core';
import { CommonModule } from '@angular/common';
import { fmtNum, scale } from '../shared/chart-utils';
import { WORLD_MAP_DATA, getSvgPath, project } from '../shared/map-data';

export interface FlowNode {
  id: string;
  lat: number;
  lng: number;
  label?: string;
  size?: number;
