export class FlowmapComponent {
  title = input<string>('Global Logistics Flowmap');
  nodes = input<FlowNode[]>([]);
  flows = input<FlowConnection[]>([]);
  height = input<number>(400);
  theme = input<'light' | 'dark'>('light');
  showExport = input<boolean>(false);
  colors = input<string[]>(['#6366f1', '#3b82f6', '#10b981', '#f59e0b', '#ef4444']);

  containerWidth = signal<number>(600);
  hoveredNodeId = signal<string | null>(null);
  hoveredFlowIndex = signal<number | null>(null);
  tooltip = signal<any | null>(null);
  tooltipX = signal<number>(0);
  tooltipY = signal<number>(0);
  exportMenuOpen = signal(false);

  svgEl = viewChild<ElementRef<SVGElement>>('svgEl');
  private container = viewChild<ElementRef>('container');

  constructor() {
    const hostEl = inject(ElementRef).nativeElement;
    if (typeof ResizeObserver !== 'undefined') {
      const resizeObserver = new ResizeObserver(entries => {
        if (!entries || entries.length === 0) return;
        const width = entries[0].contentRect.width;
        if (width > 0) {
          this.containerWidth.set(width);
        }
      });
      resizeObserver.observe(hostEl);
      inject(DestroyRef).onDestroy(() => resizeObserver.disconnect());
    }
  }

  baseMapPaths = computed(() => {
    const w = this.containerWidth();
    const h = this.height();
    const padding = { top: 10, right: 10, bottom: 10, left: 10 };
    return WORLD_MAP_DATA.map(region => getSvgPath(region.polygons, w, h, padding));
  });

  computedNodes = computed(() => {
    const w = this.containerWidth();
    const h = this.height();
    const padding = { top: 10, right: 10, bottom: 10, left: 10 };

    return this.nodes().map(node => {
      const coord = project(node.lng, node.lat, w, h, padding);
      return {
        id: node.id,
        x: coord.x,
        y: coord.y,
        size: node.size || 8,
        color: node.color || '#4f46e5',
        raw: node
      };
    });
  });

  private flowValues = computed(() => this.flows().map(f => f.value));
  private maxFlowVal = computed(() => this.flowValues().length > 0 ? Math.max(...this.flowValues()) : 1);
  private minFlowVal = computed(() => this.flowValues().length > 0 ? Math.min(...this.flowValues()) : 0);

  computedFlows = computed(() => {
    const nodesMap = new Map<string, { x: number; y: number }>();
    this.computedNodes().forEach(n => nodesMap.set(n.id.toUpperCase(), { x: n.x, y: n.y }));

    const maxVal = this.maxFlowVal();
    const minVal = this.minFlowVal();

    return this.flows().map((flow, index) => {
      const p1 = nodesMap.get(flow.from.toUpperCase());
      const p2 = nodesMap.get(flow.to.toUpperCase());

      const x1 = p1 ? p1.x : 0;
      const y1 = p1 ? p1.y : 0;
      const x2 = p2 ? p2.x : 0;
      const y2 = p2 ? p2.y : 0;

      // Quadratic Bezier math
      // Midpoint:
      const mx = (x1 + x2) / 2;
      const my = (y1 + y2) / 2;

      // Delta
      const dx = x2 - x1;
      const dy = y2 - y1;
      const len = Math.sqrt(dx*dx + dy*dy) || 1;

      // Curvature offset (perpendicular to direction)
      const curOffset = len * 0.18;
      const cx = mx - (dy / len) * curOffset;
      const cy = my + (dx / len) * curOffset;

      const path = `M ${x1.toFixed(1)} ${y1.toFixed(1)} Q ${cx.toFixed(1)} ${cy.toFixed(1)} ${x2.toFixed(1)} ${y2.toFixed(1)}`;

      // Scaling line thickness: 1.5px to 6px
      const strokeWidth = scale(flow.value, minVal, maxVal, 1.5, 6);

      // Animation duration: higher value (faster flow) is shorter duration
      const duration = scale(flow.value, minVal, maxVal, 2.5, 0.8) + 's';

      const color = flow.color || this.colors()[index % this.colors().length];

      return {
        path,
        strokeWidth,
        duration,
        color,
        raw: flow
      };
    });
  });

  onNodeHover(node: FlowNode, event: MouseEvent) {
    this.hoveredNodeId.set(node.id);
    this.hoveredFlowIndex.set(null);
    this.tooltip.set({
      type: 'node',
      id: node.id,
      label: node.label,
      lat: node.lat,
      lng: node.lng
    });
  }

  onNodeMouseMove(event: MouseEvent) {
    const containerEl = this.container()?.nativeElement;
    if (containerEl) {
      const rect = containerEl.getBoundingClientRect();
      this.tooltipX.set(event.clientX - rect.left);
      this.tooltipY.set(event.clientY - rect.top);
    }
  }

  onFlowHover(flow: FlowConnection, idx: number, event: MouseEvent) {
    this.hoveredFlowIndex.set(idx);
    this.hoveredNodeId.set(null);
    this.tooltip.set({
      type: 'flow',
      from: flow.from,
      to: flow.to,
      value: flow.value,
      label: flow.label
    });
  }

  onFlowMouseMove(event: MouseEvent) {
    const containerEl = this.container()?.nativeElement;
    if (containerEl) {
      const rect = containerEl.getBoundingClientRect();
      this.tooltipX.set(event.clientX - rect.left);
      this.tooltipY.set(event.clientY - rect.top);
    }
  }

  onMouseLeave() {
    this.hoveredNodeId.set(null);
    this.hoveredFlowIndex.set(null);
    this.tooltip.set(null);
  }

  toggleExportMenu(event: MouseEvent): void {
    event.stopPropagation();
    this.exportMenuOpen.set(!this.exportMenuOpen());
  }

  @HostListener('document:click')
  closeExportMenu(): void {
    this.exportMenuOpen.set(false);
  }

  onExport(type: 'json' | 'csv' | 'svg' | 'pdf'): void {
    this.exportMenuOpen.set(false);
    if (type === 'json') this.exportToJson();
    else if (type === 'csv') this.exportToCsv();
    else if (type === 'svg') this.exportToSvg();
    else if (type === 'pdf') this.exportToPdf();
  }

  exportToJson(): void {
    const data = { nodes: this.nodes(), flows: this.flows() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'flowmap-data.json');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToCsv(): void {
    const data = this.flows();
    if (!data.length) return;
    let csv = 'FromNode,ToNode,Volume,Label\n';
    data.forEach(d => {
      csv += `"${d.from}","${d.to}",${d.value},"${d.label || ''}"\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'flowmap-data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToSvg(): void {
    const svg = this.svgEl()?.nativeElement;
    if (!svg) return;
    const serializer = new XMLSerializer();
    let source = serializer.serializeToString(svg);
    if (!source.match(/^<svg[^>]+xmlns="http\:\/\/www\.w3\.org\/2000\/svg"/)) {
      source = source.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
    }
    if (!source.match(/^<svg[^>]+xmlns\:xlink="http\:\/\/www\.w3\.org\/1999\/xlink"/)) {
      source = source.replace(/^<svg/, '<svg xmlns:xlink="http://www.w3.org/1999/xlink"');
    }
    source = '<?xml version="1.0" encoding="utf-8"?>\n' + source;
    const blob = new Blob([source], { type: 'image/svg+xml;charset=utf-8' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'flowmap.svg');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToPdf(): void {
    const svg = this.svgEl()?.nativeElement;
    if (!svg) return;
    const printWindow = window.open('', '_blank');
    if (!printWindow) return;
    const svgClone = svg.cloneNode(true) as SVGElement;
    svgClone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
    const svgString = new XMLSerializer().serializeToString(svgClone);

    printWindow.document.write(`
      <html>
        <head>
          <title>Export PDF</title>
          <style>
            body {
              margin: 0;
              display: flex;
              justify-content: center;
              align-items: center;
              height: 100vh;
              background-color: #ffffff;
              font-family: system-ui, sans-serif;
            }
            .print-container {
              text-align: center;
              width: 100%;
              max-width: 800px;
              padding: 20px;
            }
            svg {
              width: 100%;
              height: auto;
              max-height: 90vh;
            }
            @media print {
              body {
                background: none;
              }
              .print-container {
                max-width: 100%;
                padding: 0;
              }
              svg {
                page-break-inside: avoid;
              }
            }
          </style>
        </head>
        <body>
          <div class="print-container">
            ${svgString}
          </div>
          <script>
            window.onload = () => {
              window.print();
              window.close();
            };
          </script>
        </body>
      </html>
    `);
    printWindow.document.close();
  }

  readonly fmtNum = fmtNum;
}

import { CommonModule } from '@angular/common';
import { Component, computed, effect, input, output, signal } from '@angular/core';

export interface FormBuilderOption {
  label: string;
  value: string | number | boolean;
}

export interface FormBuilderField {
  key: string;
  label: string;
  type?: 'text' | 'email' | 'password' | 'number' | 'textarea' | 'select' | 'checkbox' | 'date';
  placeholder?: string;
  required?: boolean;
  disabled?: boolean;
  options?: FormBuilderOption[];
  value?: unknown;
  min?: number | string;
  max?: number | string;
  step?: number;
}

@Component({
  selector: 'ngx-form-builder',
  standalone: true,
  imports: [CommonModule],
  template: `
    <form class="ngx-form-builder" (submit)="submit($event)">
      @for (field of fields(); track field.key) {
        <label class="form-field" [class.checkbox-field]="field.type === 'checkbox'">
          @if (field.type !== 'checkbox') {
            <span class="field-label">{{ field.label }}@if (field.required) { <strong>*</strong> }</span>
          }

          @switch (field.type || 'text') {
            @case ('textarea') {
              <textarea
                [placeholder]="field.placeholder || ''"
                [required]="field.required || false"
                [disabled]="field.disabled || false"
                [value]="valueFor(field.key)"
                (input)="updateValue(field.key, $any($event.target).value)"
              ></textarea>
            }
            @case ('select') {
              <select
                [required]="field.required || false"
                [disabled]="field.disabled || false"
                [value]="valueFor(field.key)"
                (change)="updateValue(field.key, readOptionValue(field, $any($event.target).value))"
              >
                <option value="">Select...</option>
                @for (option of field.options || []; track option.value) {
                  <option [value]="option.value">{{ option.label }}</option>
                }
              </select>
            }
            @case ('checkbox') {
              <input
                type="checkbox"
                [checked]="!!valueFor(field.key)"
                [required]="field.required || false"
                [disabled]="field.disabled || false"
                (change)="updateValue(field.key, $any($event.target).checked)"
              />
              <span class="field-label">{{ field.label }}@if (field.required) { <strong>*</strong> }</span>
            }
            @default {
              <input
                [type]="field.type || 'text'"
                [placeholder]="field.placeholder || ''"
                [required]="field.required || false"
                [disabled]="field.disabled || false"
                [min]="field.min ?? null"
                [max]="field.max ?? null"
                [step]="field.step ?? null"
                [value]="valueFor(field.key)"
                (input)="updateValue(field.key, coerceInputValue(field, $any($event.target).value))"
              />
            }
          }
        </label>
      }

      @if (showSubmit()) {
        <div class="form-actions">
          <button type="submit">{{ submitLabel() }}</button>
        </div>
      }
    </form>
  `,
  styles: [`
    :host { display: block; }
    .ngx-form-builder { display: grid; gap: 14px; font-family: var(--ngx-font-family, inherit); color: var(--text-primary, #0f172a); }
    .form-field { display: grid; gap: 6px; }
    .checkbox-field { display: flex; align-items: center; gap: 8px; }
    .field-label { font-size: 12px; font-weight: 700; color: var(--ngx-input-label, #475569); }
    .field-label strong { color: var(--ngx-input-error, #dc2626); margin-left: 2px; }
    input:not([type="checkbox"]), textarea, select { width: 100%; border: 1px solid var(--ngx-input-border, #cbd5e1); border-radius: var(--ngx-input-radius, 8px); background: var(--ngx-input-bg, #ffffff); color: var(--ngx-input-text, #0f172a); font: inherit; font-size: 13px; padding: 9px 11px; outline: none; transition: all 0.15s; }
    textarea { min-height: 96px; resize: vertical; }
    input:focus, textarea:focus, select:focus { border-color: var(--primary-color, #4f46e5); box-shadow: 0 0 0 3px var(--primary-glow, rgba(79,70,229,0.12)); }
    input:disabled, textarea:disabled, select:disabled { background: var(--ngx-input-disabled-bg, #f8fafc); color: var(--text-secondary, #64748b); cursor: not-allowed; }
    input[type="checkbox"] { width: 16px; height: 16px; accent-color: var(--primary-color, #4f46e5); }
    .form-actions { display: flex; justify-content: flex-end; }
    .form-actions button { border: 0; border-radius: 7px; background: var(--primary-color, #4f46e5); color: #fff; cursor: pointer; font: inherit; font-size: 13px; font-weight: 750; padding: 9px 14px; }
    .form-actions button:hover, .form-actions button:focus-visible { background: var(--primary-hover, #4338ca); outline: none; }
  `]
})
export class FormBuilderComponent {
  /**
   * The schema definition list of form fields to render dynamically.
   */
  fields = input<FormBuilderField[]>([]);

  /**
   * The initial/controlled form value dictionary mapping field keys to values.
   */
  value = input<Record<string, unknown>>({});

  /**
   * Whether to render the default form submit button at the bottom.
   * @default true
   */
  showSubmit = input(true);

  /**
   * The text label to display on the default form submit button.
   * @default 'Submit'
   */
  submitLabel = input('Submit');

  /**
   * Emits when any field value in the form changes.
   */
  valueChange = output<Record<string, unknown>>();

  /**
   * Emits the entire form value dictionary when the form is submitted successfully.
   */
  formSubmit = output<Record<string, unknown>>();

  formValue = signal<Record<string, unknown>>({});

  private syncValue = effect(() => {
    const fromFields = this.fields().reduce<Record<string, unknown>>((acc, field) => {
      if (field.value !== undefined) acc[field.key] = field.value;
      return acc;
    }, {});
    this.formValue.set({ ...fromFields, ...this.value() });
  });

  filledValue = computed(() => this.formValue());

  valueFor(key: string): unknown {
    return this.filledValue()[key] ?? '';
  }

  updateValue(key: string, value: unknown): void {
    const next = { ...this.formValue(), [key]: value };
    this.formValue.set(next);
    this.valueChange.emit(next);
  }

  submit(event: SubmitEvent): void {
    event.preventDefault();
    this.formSubmit.emit(this.formValue());
  }

  coerceInputValue(field: FormBuilderField, value: string): unknown {
    return field.type === 'number' ? (value === '' ? null : Number(value)) : value;
  }

  readOptionValue(field: FormBuilderField, rawValue: string): unknown {
    return field.options?.find(option => String(option.value) === rawValue)?.value ?? rawValue;
  }
}

