          </defs>

          <!-- Base Map Outlines -->
          <g class="map-base">
            @for (pathStr of baseMapPaths(); track $index) {
              <path
                [attr.d]="pathStr"
                [attr.fill]="theme() === 'dark' ? '#1e293b' : '#f1f5f9'"
                [attr.stroke]="theme() === 'dark' ? '#0f172a' : '#e2e8f0'"
                stroke-width="1.2"
