		.menu-icon { font-size: 16px; flex-shrink: 0; display: inline-flex; align-items: center; }
		.menu-label { flex: 1; }
		.menu-arrow { margin-left: auto; padding-left: 10px; font-size: 11px; transition: transform 0.2s ease; }
