import { DependencyType, GanttLinkLineType } from '../models';

export interface Rect {
  x: number;
  y: number;
  width: number;
  height: number;
}

export function computeDependencyPath(
  from: Rect,
  to: Rect,
  type: DependencyType,
  offset = 12,
  lineType: GanttLinkLineType = GanttLinkLineType.Straight
): string {
  let startX: number;
  let startY: number;
  let endX: number;
  let endY: number;

  switch (type) {
    case DependencyType.FinishToStart:
      startX = from.x + from.width;
      startY = from.y + from.height / 2;
      endX = to.x;
      endY = to.y + to.height / 2;
      break;
    case DependencyType.StartToStart:
      startX = from.x;
      startY = from.y + from.height / 2;
      endX = to.x;
      endY = to.y + to.height / 2;
      break;
    case DependencyType.FinishToFinish:
      startX = from.x + from.width;
      startY = from.y + from.height / 2;
      endX = to.x + to.width;
      endY = to.y + to.height / 2;
      break;
    case DependencyType.StartToFinish:
      startX = from.x;
      startY = from.y + from.height / 2;
      endX = to.x + to.width;
      endY = to.y + to.height / 2;
      break;
  }

  if (lineType === GanttLinkLineType.Curve) {
    return computeCurvePath(startX, startY, endX, endY, type, offset);
  }

  return computeStraightPath(startX, startY, endX, endY, type, offset);
}

function computeStraightPath(
  startX: number, startY: number,
  endX: number, endY: number,
  type: DependencyType, offset: number
): string {
  const midX = startX + offset;

  if (type === DependencyType.FinishToStart && endX > startX + offset * 2) {
    const mx = (startX + endX) / 2;
    return `M ${startX} ${startY} H ${mx} V ${endY} H ${endX}`;
  }

  return `M ${startX} ${startY} H ${midX} V ${endY} H ${endX}`;
}

function computeCurvePath(
  startX: number, startY: number,
  endX: number, endY: number,
  type: DependencyType, offset: number
): string {
  const dx = endX - startX;
  const dy = endY - startY;
  const r = Math.min(Math.abs(dy) / 2, offset);

  if (type === DependencyType.FinishToStart && dx > offset * 2) {
    // Smooth S-curve
    const midX = (startX + endX) / 2;
    const cp1x = midX;
    const cp1y = startY;
    const cp2x = midX;
    const cp2y = endY;
    return `M ${startX} ${startY} C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${endX} ${endY}`;
  }

  // Route around: go right, down/up, then left/right to target
  const midX = startX + offset;
  const signY = dy >= 0 ? 1 : -1;

  if (Math.abs(dy) < r * 2) {
    // Very close vertically, simple curve
    return `M ${startX} ${startY} C ${midX} ${startY}, ${endX - offset} ${endY}, ${endX} ${endY}`;
  }

  return `M ${startX} ${startY} ` +
    `H ${midX - r} ` +
    `Q ${midX} ${startY}, ${midX} ${startY + signY * r} ` +
    `V ${endY - signY * r} ` +
    `Q ${midX} ${endY}, ${midX + r} ${endY} ` +
    `H ${endX}`;
}

import {
  Component, ChangeDetectionStrategy, input, computed, signal,
  ElementRef, inject, DestroyRef, TemplateRef, viewChild, HostListener
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { CHART_COLORS, fmtNum, niceTicks, scale } from '../shared/chart-utils';

export interface RenkoBrick {
  index: number;
  open: number;
  close: number;
  type: 'bullish' | 'bearish';
  color: string;
  x: number;
  y: number;
  w: number;
  h: number;
}

@Component({
  selector: 'ngx-renko-chart',
  standalone: true,
  imports: [CommonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="ngx-renko-chart" (mouseleave)="onMouseLeave()">
      <div class="chart-header" (mousemove)="$event.stopPropagation()" (mouseleave)="onMouseLeave()">
        <div class="header-info">
          <span class="header-title">Renko Chart</span>
          <span class="header-boxsize">Box Size: {{ boxSize() }}</span>
        </div>

        <!-- Export menu trigger -->
        @if (showExport()) {
          <div class="chart-export-menu">
            <button class="export-trigger" (click)="toggleExportMenu($event)" aria-label="Export Menu">📤 Export</button>
            @if (exportMenuOpen()) {
              <div class="export-dropdown">
                <button (click)="onExport('json')">📊 Export JSON</button>
                <button (click)="onExport('csv')">📄 Export CSV</button>
                <button (click)="onExport('svg')">🖼️ Export SVG</button>
              </div>
            }
          </div>
        }
      </div>

      <svg
        #svgEl
        class="renko-svg"
        [attr.width]="'100%'"
        [attr.height]="svgHeight()"
      >
        <g [attr.transform]="'translate(' + margin().left + ',' + margin().top + ')'">

          <!-- Grid Lines -->
          @if (showGrid()) {
            @for (tick of yTicks(); track tick) {
              <line
                [attr.x1]="0"
                [attr.x2]="innerW()"
                [attr.y1]="yPos(tick)"
                [attr.y2]="yPos(tick)"
                class="grid-line"
              />
            }
          }

          <!-- Bricks -->
          @for (brick of computedBricks(); track brick.index; let i = $index) {
            <rect
              [attr.x]="brick.x"
              [attr.y]="brick.y"
              [attr.width]="brick.w"
              [attr.height]="brick.h"
              [attr.fill]="brick.color"
              class="renko-brick"
              [class.dimmed]="hoveredIndex() !== null && hoveredIndex() !== i"
              [class.highlighted]="hoveredIndex() === i"
              (mouseenter)="onBrickHover(i, $event)"
              (mousemove)="onMouseMove($event)"
              stroke="#ffffff"
              stroke-width="0.5"
              [style.animation-delay]="(i * 0.03) + 's'"
            />
          }

          <!-- Y Axis (Left side) -->
          <g class="y-axis">
            <line [attr.x1]="0" [attr.x2]="0" [attr.y1]="0" [attr.y2]="innerH()" class="axis-line" />
            @for (tick of yTicks(); track tick) {
              <g [attr.transform]="'translate(0,' + yPos(tick) + ')'">
                <line [attr.x1]="-4" [attr.x2]="0" [attr.y1]="0" [attr.y2]="0" class="tick-line" />
                <text
                  [attr.x]="-8"
                  text-anchor="end"
                  dominant-baseline="middle"
                  class="tick-label"
                >
                  {{ labelFormatter() ? labelFormatter()!(tick) : formatNumber(tick) }}
                </text>
              </g>
            }
          </g>

          <!-- Bottom X Axis Line -->
          <g [attr.transform]="'translate(0,' + innerH() + ')'" class="x-axis">
            <line [attr.x1]="0" [attr.x2]="innerW()" [attr.y1]="0" [attr.y2]="0" class="axis-line" />
          </g>
        </g>
      </svg>

      <!-- Glassmorphic Tooltip -->
      @if (tooltip(); as t) {
        <div class="chart-tooltip" [style.left.px]="tooltipX()" [style.top.px]="tooltipY()">
          @if (tooltipTemplate()) {
            <ng-container
              *ngTemplateOutlet="tooltipTemplate()!; context: { $implicit: t }"
            ></ng-container>
          } @else {
            <div class="tt-cat" [style.color]="t.color">
              {{ t.type === 'bullish' ? 'Yang (Bullish)' : 'Yin (Bearish)' }}
            </div>
            <div class="tt-row">
              <span class="tt-name">Open</span>
              <span class="tt-val">{{ labelFormatter() ? labelFormatter()!(t.open) : formatNumber(t.open) }}</span>
            </div>
