export class RenkoChartComponent {
  data = input<number[]>([]);
  boxSize = input<number>(5);
  height = input<number>(350);
  showGrid = input<boolean>(true);
  bullishColor = input<string>('#10b981');
  bearishColor = input<string>('#ef4444');
  showExport = input<boolean>(false);
  labelFormatter = input<((v: number) => string) | undefined>(undefined);
  tooltipTemplate = input<TemplateRef<any> | null>(null);

  containerWidth = signal<number>(500);
  hoveredIndex = signal<number | null>(null);
  tooltip = signal<any | null>(null);
  tooltipX = signal<number>(0);
  tooltipY = signal<number>(0);
  exportMenuOpen = signal(false);

  svgEl = viewChild<ElementRef<SVGElement>>('svgEl');

  margin = computed(() => ({
    top: 20,
    right: 20,
    bottom: 20,
    left: 45
  }));

  svgHeight = computed(() => this.height());
  innerW = computed(() => Math.max(10, this.containerWidth() - this.margin().left - this.margin().right));
  innerH = computed(() => Math.max(10, this.svgHeight() - this.margin().top - this.margin().bottom));

  constructor() {
    const hostEl = inject(ElementRef).nativeElement;
    if (typeof ResizeObserver !== 'undefined') {
      const resizeObserver = new ResizeObserver(entries => {
        if (!entries || entries.length === 0) return;
        const width = entries[0].contentRect.width;
        if (width > 0) {
          this.containerWidth.set(width);
        }
      });
      resizeObserver.observe(hostEl);
      inject(DestroyRef).onDestroy(() => resizeObserver.disconnect());
    }
  }

  // Calculate Renko Bricks based on boxSize requirement
  computedBricks = computed<RenkoBrick[]>(() => {
    const prices = this.data();
    const size = this.boxSize() || 5;
    if (prices.length === 0) return [];

    const bricks: Omit<RenkoBrick, 'x' | 'y' | 'w' | 'h'>[] = [];
    let currentPrice = prices[0];
    let brickIndex = 0;

    for (let i = 1; i < prices.length; i++) {
      const price = prices[i];
      const diff = price - currentPrice;

      if (Math.abs(diff) >= size) {
        const numBricks = Math.floor(Math.abs(diff) / size);
        const direction = diff > 0 ? 1 : -1;

        for (let b = 0; b < numBricks; b++) {
          const nextPrice = currentPrice + direction * size;
          bricks.push({
            index: brickIndex++,
            open: currentPrice,
            close: nextPrice,
            type: direction > 0 ? 'bullish' : 'bearish',
            color: direction > 0 ? this.bullishColor() : this.bearishColor()
          });
          currentPrice = nextPrice;
        }
      }
    }

    // Now layout coordinates
    const count = bricks.length;
    if (count === 0) return [];

    const w = this.innerW();
    const h = this.innerH();

    // Find min and max close levels to scale Y Axis
    const allPrices = bricks.flatMap(b => [b.open, b.close]);
    const minVal = Math.min(...allPrices);
    const maxVal = Math.max(...allPrices);
    const span = maxVal - minVal || 10;
    const yMin = Math.max(0, minVal - span * 0.05);
    const yMax = maxVal + span * 0.05;

    // Distribute X columns horizontally
    const brickW = w / count;

    return bricks.map((b, idx) => {
      // Scale coordinates
      const yOpen = scale(b.open, yMin, yMax, h, 0);
      const yClose = scale(b.close, yMin, yMax, h, 0);

      const brickH = Math.abs(yClose - yOpen);
      const brickY = Math.min(yOpen, yClose);
      const brickX = idx * brickW;

      return {
        ...b,
        x: brickX,
        y: brickY,
        w: brickW * 0.9, // 10% gap spacing
        h: Math.max(2, brickH)
      } as RenkoBrick;
    });
  });

  yTicks = computed(() => {
    const bricks = this.computedBricks();
    if (bricks.length === 0) return [0, 50, 100];
    const allPrices = bricks.flatMap(b => [b.open, b.close]);
    const minVal = Math.min(...allPrices);
    const maxVal = Math.max(...allPrices);
    const span = maxVal - minVal || 10;
    return niceTicks(Math.max(0, minVal - span * 0.05), maxVal + span * 0.05, 5);
  });

  yDomainMax = computed(() => {
    const ticks = this.yTicks();
    return ticks[ticks.length - 1] || 100;
  });

  yDomainMin = computed(() => {
    const ticks = this.yTicks();
    return ticks[0] || 0;
  });

  yPos(val: number): number {
    return scale(val, this.yDomainMin(), this.yDomainMax(), this.innerH(), 0);
  }

  onBrickHover(idx: number, event: MouseEvent) {
    this.hoveredIndex.set(idx);
    const brick = this.computedBricks()[idx];
    if (brick) {
      this.tooltip.set(brick);
    }
  }

  onMouseMove(event: MouseEvent) {
    const el = event.currentTarget as SVGElement;
    const container = el.closest('.ngx-renko-chart');
    if (container) {
      const rect = container.getBoundingClientRect();
      this.tooltipX.set(event.clientX - rect.left);
      this.tooltipY.set(event.clientY - rect.top);
    }
  }

  onMouseLeave() {
    this.hoveredIndex.set(null);
    this.tooltip.set(null);
  }

  toggleExportMenu(event: MouseEvent): void {
    event.stopPropagation();
    this.exportMenuOpen.set(!this.exportMenuOpen());
  }

  @HostListener('document:click')
  closeExportMenu(): void {
    this.exportMenuOpen.set(false);
  }

  onExport(type: 'json' | 'csv' | 'svg'): void {
    this.exportMenuOpen.set(false);
    if (type === 'json') this.exportToJson();
    else if (type === 'csv') this.exportToCsv();
    else if (type === 'svg') this.exportToSvg();
  }

  exportToCsv(): void {
    const bricks = this.computedBricks();
    if (!bricks.length) return;

    let csv = 'Index,Type,Open,Close\n';
    bricks.forEach(b => {
      csv += `${b.index},"${b.type}",${b.open},${b.close}\n`;
    });

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'renko-chart-data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToJson(): void {
    const bricks = this.computedBricks();
    if (!bricks.length) return;

    const data = bricks.map(b => ({
      index: b.index,
      type: b.type,
      open: b.open,
      close: b.close
    }));

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'renko-chart-data.json');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToSvg(): void {
    const svg = this.svgEl()?.nativeElement;
    if (!svg) return;
    const serializer = new XMLSerializer();
    let source = serializer.serializeToString(svg);
    if (!source.match(/^<svg[^>]+xmlns="http\:\/\/www\.w3\.org\/2000\/svg"/)) {
      source = source.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
    }
    if (!source.match(/^<svg[^>]+xmlns\:xlink="http\:\/\/www\.w3\.org\/1999\/xlink"/)) {
      source = source.replace(/^<svg/, '<svg xmlns:xlink="http://www.w3.org/1999/xlink"');
    }
    source = '<?xml version="1.0" encoding="utf-8"?>\n' + source;
    const blob = new Blob([source], { type: 'image/svg+xml;charset=utf-8' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'renko-chart.svg');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  formatNumber(v: number): string {
    return fmtNum(v);
  }
}

import { CommonModule } from '@angular/common';
import { Component, HostListener, computed, effect, input, output, signal, OnInit, OnDestroy, Directive, TemplateRef, inject, contentChild } from '@angular/core';
import { SchedulerEvent, SchedulerEventChangeEvent, SchedulerSlotClickEvent, SchedulerResource, SchedulerSlotRangeSelectEvent } from './models';
import { NGX_CORE_I18N } from 'ngx-core-components/i18n';

@Directive({
  selector: '[ngxSchedulerEventTemplate]',
  standalone: true
})
export class NgxSchedulerEventTemplateDirective {
  templateRef = inject(TemplateRef);
}

interface TimeSlot {
  hour: number;
  minute: number;
  key: string;
}

interface ResolvedSchedulerEvent {
  id: string;
  event: SchedulerEvent;
  start: Date;
  end: Date;
}

interface SchedulerEventLayout extends ResolvedSchedulerEvent {
  top: number;
  height: number;
  left: number;
  width: number;
}

interface ResizeState {
  event: SchedulerEvent;
  edge: 'start' | 'end';
  start: Date;
  end: Date;
  originY: number;
}

@Component({
  selector: 'ngx-scheduler',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div class="ngx-scheduler-wrapper" [class.dark]="theme() === 'dark'">

      <!-- Scheduler Toolbar -->
      <div class="scheduler-toolbar">
        <div class="nav-controls">
          <div class="nav-buttons-group">
            <button class="tool-btn nav-arrow" type="button" (click)="navigate(-1)" aria-label="Previous period">
              <svg class="icon-svg" viewBox="0 0 24 24"><path fill="currentColor" d="M15.41 7.41L14 6l-6 6 6 6 1.41-1.41L10.83 12z"/></svg>
            </button>
            <button class="tool-btn today-btn" type="button" (click)="goToToday()">{{ i18n.scheduler.today }}</button>
            <button class="tool-btn nav-arrow" type="button" (click)="navigate(1)" aria-label="Next period">
              <svg class="icon-svg" viewBox="0 0 24 24"><path fill="currentColor" d="M10 6L8.59 7.41 13.17 12l-4.58 4.59L10 18l6-6z"/></svg>
            </button>
          </div>
          <h2 class="current-period-label">{{ periodLabel() }}</h2>
        </div>

        <div class="toolbar-actions">
          <!-- Keyword Search -->
          @if (showSearch()) {
            <div class="search-box-container">
              <svg class="search-icon" viewBox="0 0 24 24"><path fill="currentColor" d="M15.5 14h-.79l-.28-.27C15.41 12.59 16 11.11 16 9.5 16 5.91 13.09 3 9.5 3S3 5.91 3 9.5 5.91 16 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19l-4.99-5zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14z"/></svg>
              <input type="text" 
                     class="search-input" 
                     [placeholder]="i18n.common.search" 
                     [value]="searchQuery()" 
                     (input)="onSearchInput($event)" />
            </div>
          }

          <!-- Resource Select Filter (Week/Month View) -->
          @if (resources().length > 0 && activeMode() !== 'day') {
            <div class="resource-filter-container">
              <select class="resource-select" [value]="selectedResourceId() || ''" (change)="onResourceFilterChange($event)">
                <option value="">All Resources</option>
                @for (res of resources(); track res.id) {
                  <option [value]="res.id">{{ res.name }}</option>
                }
              </select>
            </div>
          }

          <!-- Export Dropdown -->
          <div class="export-dropdown-wrapper">
            <button class="tool-btn export-toggle-btn" type="button" (click)="showExportDropdown.set(!showExportDropdown())">
              <span>Export</span>
              <svg class="dropdown-arrow-svg" viewBox="0 0 24 24"><path fill="currentColor" d="M7 10l5 5 5-5z"/></svg>
            </button>

            @if (showExportDropdown()) {
