export class RidgelineChartComponent {
  data = input<RidgelineItem[]>([]);
  height = input<number>(400);
  showGrid = input<boolean>(true);
  showLabels = input<boolean>(true);
  useGradient = input<boolean>(false);
  colors = input<string[]>(CHART_COLORS);
  overlap = input<number>(1.6); // Stack overlap ratio multiplier
  showExport = input<boolean>(false);

  containerWidth = signal<number>(500);
  hoveredIndex = signal<number | null>(null);
  tooltip = signal<any | null>(null);
  tooltipX = signal<number>(0);
  tooltipY = signal<number>(0);
  exportMenuOpen = signal(false);

  svgEl = viewChild<ElementRef<SVGElement>>('svgEl');

  margin = computed(() => ({
    top: 40,
    right: 20,
    bottom: 30,
    left: this.showLabels() ? 90 : 20
  }));

  svgHeight = computed(() => this.height());
  innerW = computed(() => Math.max(10, this.containerWidth() - this.margin().left - this.margin().right));
  innerH = computed(() => Math.max(10, this.svgHeight() - this.margin().top - this.margin().bottom));

  constructor() {
    const hostEl = inject(ElementRef).nativeElement;
    if (typeof ResizeObserver !== 'undefined') {
      const resizeObserver = new ResizeObserver(entries => {
        if (!entries || entries.length === 0) return;
        const width = entries[0].contentRect.width;
        if (width > 0) {
          this.containerWidth.set(width);
        }
      });
      resizeObserver.observe(hostEl);
      inject(DestroyRef).onDestroy(() => resizeObserver.disconnect());
    }
  }

  // Bounds
  bounds = computed(() => {
    const raw = this.data();
    if (raw.length === 0) return { min: 0, max: 100 };
    const allValues = raw.flatMap(d => d.values);
    if (allValues.length === 0) return { min: 0, max: 100 };
    const min = Math.min(...allValues);
    const max = Math.max(...allValues);
    const span = max - min || 10;
    return {
      min: Math.max(0, min - span * 0.05),
      max: max + span * 0.05
    };
  });

  xTicks = computed(() => {
    const b = this.bounds();
    return niceTicks(b.min, b.max, 5);
  });

  xDomain = computed(() => {
    const ticks = this.xTicks();
    return {
      min: ticks[0] ?? 0,
      max: ticks[ticks.length - 1] ?? 100
    };
  });

  xPos(val: number): number {
    const domain = this.xDomain();
    return scale(val, domain.min, domain.max, 0, this.innerW());
  }

  computedItems = computed(() => {
    const raw = this.data();
    const count = raw.length;
    if (count === 0) return [];

    const domain = this.xDomain();
    const baseH = this.innerH();
    const overlapFactor = this.overlap();
    const palette = this.colors();

    // Row separation height calculation
    const rowStep = baseH / (count + overlapFactor - 1);
    const maxKdeHeight = rowStep * overlapFactor;

    return raw.map((item, idx) => {
      const color = item.color || palette[idx % palette.length];

      // baselineY calculation: stack bottom-to-top
      const baselineY = baseH - idx * rowStep;

      // Basic stats calculation for tooltip details
      const sorted = [...item.values].sort((a, b) => a - b);
      const valCount = sorted.length;
      const min = valCount > 0 ? sorted[0] : 0;
      const max = valCount > 0 ? sorted[valCount - 1] : 0;
      const median = valCount > 0 ? sorted[Math.floor(valCount / 2)] : 0;

      // Bandwidth estimation using Silverman's rule of thumb
      const q1 = sorted[Math.floor(valCount * 0.25)] || 0;
      const q3 = sorted[Math.floor(valCount * 0.75)] || 0;
      const stdDev = this.getStdDev(item.values, median);
      const bandwidth = 0.9 * Math.min(stdDev, (q3 - q1) / 1.34) * Math.pow(valCount, -0.2) || 1.0;

      // Sample density along horizontal X scale
      const sampleCount = 50;
      const densityPoints: { xCoord: number; yOffset: number }[] = [];

      for (let s = 0; s <= sampleCount; s++) {
        const v = domain.min + (s / sampleCount) * (domain.max - domain.min);
        const xCoord = this.xPos(v);
        const density = this.kernelDensityEstimator(item.values, v, bandwidth);
        densityPoints.push({ xCoord, yOffset: density });
      }

      const maxDensity = Math.max(...densityPoints.map(p => p.yOffset)) || 1.0;

      // Build path points
      const points: string[] = [];
      densityPoints.forEach(p => {
        const heightOffset = (p.yOffset / maxDensity) * maxKdeHeight;
        const yCoord = baselineY - heightOffset;
        points.push(`${p.xCoord},${yCoord}`);
      });

      // areaPath starts at bottom-left corner, sweeps across curve, and closes at bottom-right
      const areaPath = `M 0,${baselineY} L ` + points.join(' L ') + ` L ${this.innerW()},${baselineY} Z`;
      const linePath = `M ` + points.join(' L ');

      return {
        label: item.label,
        count: valCount,
        min,
        max,
        median,
        color,
        baselineY,
        areaPath,
        linePath
      };
    });
  });

  private kernelDensityEstimator(samples: number[], x: number, bandwidth: number): number {
    const n = samples.length;
    if (n === 0) return 0;
    let sum = 0;
    for (let i = 0; i < n; i++) {
      const u = (x - samples[i]) / bandwidth;
      const kernel = (1 / Math.sqrt(2 * Math.PI)) * Math.exp(-0.5 * u * u);
      sum += kernel;
    }
    return sum / (n * bandwidth);
  }

  private getStdDev(values: number[], mean: number): number {
    const n = values.length;
    if (n <= 1) return 1.0;
    const sqDiffs = values.map(v => Math.pow(v - mean, 2));
    const sum = sqDiffs.reduce((acc, curr) => acc + curr, 0);
    return Math.sqrt(sum / (n - 1));
  }

  onRowHover(idx: number, event: MouseEvent) {
    this.hoveredIndex.set(idx);
    const item = this.computedItems()[idx];
    if (item) {
      this.tooltip.set(item);
    }
  }

  onRowMouseMove(event: MouseEvent) {
    const el = event.currentTarget as SVGElement;
    const container = el.closest('.ngx-ridgeline-chart');
    if (container) {
      const rect = container.getBoundingClientRect();
      this.tooltipX.set(event.clientX - rect.left);
      this.tooltipY.set(event.clientY - rect.top);
    }
  }

  onMouseLeave() {
    this.hoveredIndex.set(null);
    this.tooltip.set(null);
  }

  toggleExportMenu(event: MouseEvent): void {
    event.stopPropagation();
    this.exportMenuOpen.set(!this.exportMenuOpen());
  }

  @HostListener('document:click')
  closeExportMenu(): void {
    this.exportMenuOpen.set(false);
  }

  onExport(type: 'json' | 'csv' | 'svg' | 'pdf'): void {
    this.exportMenuOpen.set(false);
    if (type === 'json') this.exportToJson();
    else if (type === 'csv') this.exportToCsv();
    else if (type === 'svg') this.exportToSvg();
    else if (type === 'pdf') this.exportToPdf();
  }

  exportToJson(): void {
    const data = this.data();
    if (!data.length) return;
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'ridgeline-chart.json');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToCsv(): void {
    const data = this.data();
    if (!data.length) return;
    let csv = 'Label,Value\n';
    data.forEach(d => {
      (d.values || []).forEach(val => {
        csv += `"${d.label || ''}",${val}\n`;
      });
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'ridgeline-chart.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToSvg(): void {
    const svg = this.svgEl()?.nativeElement;
    if (!svg) return;
    const serializer = new XMLSerializer();
    let source = serializer.serializeToString(svg);
    if (!source.match(/^<svg[^>]+xmlns="http\:\/\/www\.w3\.org\/2000\/svg"/)) {
      source = source.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
    }
    if (!source.match(/^<svg[^>]+xmlns\:xlink="http\:\/\/www\.w3\.org\/1999\/xlink"/)) {
      source = source.replace(/^<svg/, '<svg xmlns:xlink="http://www.w3.org/1999/xlink"');
    }
    source = '<?xml version="1.0" encoding="utf-8"?>\n' + source;
    const blob = new Blob([source], { type: 'image/svg+xml;charset=utf-8' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'ridgeline-chart.svg');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToPdf(): void {
    const svg = this.svgEl()?.nativeElement;
    if (!svg) return;
    const printWindow = window.open('', '_blank');
    if (!printWindow) return;
    const serializer = new XMLSerializer();
    let svgString = serializer.serializeToString(svg);
    if (!svgString.match(/^<svg[^>]+xmlns="http\:\/\/www\.w3\.org\/2000\/svg"/)) {
      svgString = svgString.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
    }
    printWindow.document.write(`
      <html>
        <head>
          <title>Chart Export</title>
          <style>
            body {
              margin: 20px;
              font-family: system-ui, sans-serif;
              text-align: center;
            }
            .print-container {
              display: inline-block;
              margin: 0 auto;
            }
            svg {
              width: 100%;
              height: auto;
            }
            @media print {
              body { margin: 0; }
              .no-print { display: none; }
            }
          </style>
        </head>
        <body>
          <div class="print-container">
            ${svgString}
          </div>
          <script>
            window.onload = () => {
              setTimeout(() => {
                window.print();
                window.close();
              }, 250);
            };
          </script>
        </body>
      </html>
    `);
    printWindow.document.close();
  }

  formatNumber(v: number): string {
    return fmtNum(v);
  }
}

import { Injectable } from '@angular/core';
import { GanttTask } from '../models/gantt-task.model';
import { GanttGroup } from '../models/gantt-group.model';

export interface FlatRow {
  task: GanttTask;
  /** Additional tasks that share this row (same rowId). */
  extraTasks: GanttTask[];
  depth: number;
  rowIndex: number;
  hasChildren: boolean;
  isVisible: boolean;
  /** Set when this row is a group header. */
  group?: GanttGroup;
  /** Whether this is a group header row. */
  isGroupHeader: boolean;
}

interface RowGroup {
  primary: GanttTask;
  extra: GanttTask[];
}

@Injectable()
export class GanttLayoutService {
  flattenTasks(tasks: GanttTask[], groups?: GanttGroup[]): FlatRow[] {
    if (groups && groups.length > 0) {
      return this.flattenWithGroups(tasks, groups);
    }
    return this.flattenTree(tasks);
  }

  private flattenTree(tasks: GanttTask[]): FlatRow[] {
    const childrenMap = new Map<string | null, GanttTask[]>();
    for (const task of tasks) {
      const parentId = task.parentId;
      if (!childrenMap.has(parentId)) {
        childrenMap.set(parentId, []);
      }
      childrenMap.get(parentId)!.push(task);
    }

    const rows: FlatRow[] = [];
    let rowIndex = 0;

    const traverse = (parentId: string | null, depth: number, parentVisible: boolean): void => {
      const children = childrenMap.get(parentId) || [];

      // Group children by rowId, preserving original order for primary tasks.
      const rowGroups: RowGroup[] = [];
      const rowIdToGroup = new Map<string, RowGroup>();

      for (const task of children) {
        if (task.rowId) {
          const existing = rowIdToGroup.get(task.rowId);
          if (existing) {
            existing.extra.push(task);
          } else {
            const group = { primary: task, extra: [] as GanttTask[] };
            rowGroups.push(group);
            rowIdToGroup.set(task.rowId, group);
          }
        } else {
          rowGroups.push({ primary: task, extra: [] });
        }
      }

      for (const { primary: task, extra: extraTasks } of rowGroups) {
        const hasChildren = childrenMap.has(task.id) && childrenMap.get(task.id)!.length > 0;
        const isVisible = parentVisible;
        rows.push({ task, extraTasks, depth, rowIndex: isVisible ? rowIndex : -1, hasChildren, isVisible, isGroupHeader: false });
        if (isVisible) rowIndex++;
        const childVisible = isVisible && !task.collapsed;
        traverse(task.id, depth + 1, childVisible);
      }
    };

    traverse(null, 0, true);
    return rows;
  }

  private flattenWithGroups(tasks: GanttTask[], groups: GanttGroup[]): FlatRow[] {
    const rows: FlatRow[] = [];
    let rowIndex = 0;

    // Build a map of tasks by group_id
    const tasksByGroup = new Map<string, GanttTask[]>();
    const ungroupedTasks: GanttTask[] = [];
    for (const task of tasks) {
      if (task.group_id) {
        if (!tasksByGroup.has(task.group_id)) {
          tasksByGroup.set(task.group_id, []);
        }
        tasksByGroup.get(task.group_id)!.push(task);
      } else {
        ungroupedTasks.push(task);
      }
    }

    for (const group of groups) {
      // Create a pseudo-task for the group header
      const groupTask: GanttTask = {
        id: `__group__${group.id}`,
        name: group.title,
        start: new Date(),
        end: new Date(),
        progress: 0,
        parentId: null,
        collapsed: group.expanded === false,
        isMilestone: false,
        cssClass: group.class,
      };

      const groupTasks = tasksByGroup.get(group.id) || [];

      // Calculate group date range
      if (groupTasks.length > 0) {
        let minStart = groupTasks[0].start.getTime();
        let maxEnd = groupTasks[0].end.getTime();
        let totalProgress = 0;
        for (const t of groupTasks) {
          if (t.start.getTime() < minStart) minStart = t.start.getTime();
          if (t.end.getTime() > maxEnd) maxEnd = t.end.getTime();
          totalProgress += t.progress;
        }
        groupTask.start = new Date(minStart);
        groupTask.end = new Date(maxEnd);
        groupTask.progress = Math.round(totalProgress / groupTasks.length);
      }

      const hasChildren = groupTasks.length > 0;
      rows.push({
        task: groupTask,
        extraTasks: [],
        depth: 0,
        rowIndex: rowIndex++,
        hasChildren,
        isVisible: true,
        group,
        isGroupHeader: true,
      });

      if (group.expanded !== false) {
        // Flatten group tasks using tree logic
        const groupRows = this.flattenTree(groupTasks);
        for (const r of groupRows) {
          if (r.isVisible) {
            r.rowIndex = rowIndex++;
            r.depth += 1; // indent within group
          }
          rows.push(r);
        }
      }
    }

    // Also flatten any ungrouped tasks
    if (ungroupedTasks.length > 0) {
      const ungroupedRows = this.flattenTree(ungroupedTasks);
      for (const r of ungroupedRows) {
        if (r.isVisible) {
          r.rowIndex = rowIndex++;
        }
        rows.push(r);
      }
    }

    return rows;
  }
}

import {
  Component, ChangeDetectionStrategy, input, computed, signal,
  ElementRef, inject, DestroyRef, viewChild, HostListener
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { CHART_COLORS, fmtNum } from '../shared/chart-utils';

export interface SankeyNode {
  id: string;
  label: string;
  color?: string;
}

export interface SankeyLink {
  source: string;
  target: string;
  value: number;
}

interface ProcessedNode {
  id: string;
  label: string;
  color: string;
  x: number;
  y: number;
  width: number;
  height: number;
  value: number;
  column: number;
  inSum: number;
  outSum: number;
}

interface ProcessedLink {
  sourceId: string;
  targetId: string;
  value: number;
  path: string;
  color: string;
  thickness: number;
  sourceNode: ProcessedNode;
  targetNode: ProcessedNode;
}

@Component({
  selector: 'ngx-sankey-chart',
  standalone: true,
  imports: [CommonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="ngx-sankey-chart" (mouseleave)="onMouseLeave()">
      <div class="chart-header" (mousemove)="$event.stopPropagation()" (mouseleave)="onMouseLeave()">
