    .node-group.dimmed {
      opacity: 0.3;
    }
    .node-label {
      fill: var(--ngx-chart-text, #1e293b);
      font-size: 11px;
      font-weight: 600;
      pointer-events: none;
      user-select: none;
    }
    .chart-legend {
      display: flex;
      flex-direction: column;
      gap: 6px;
      flex-shrink: 0;
      min-width: 130px;
    }
    .legend-item {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 12px;
    }
    .legend-dot {
      width: 10px;
      height: 10px;
      border-radius: 3px;
      flex-shrink: 0;
    }
    .legend-label {
      color: var(--ngx-chart-text, #1e293b);
      font-weight: 600;
