export interface BubbleNode {
  id: string;
  label: string;
  value: number;       // Determines size
  group?: string;      // Optional grouping for clustered packing
  color?: string;
}

interface SimulatedNode {
  id: string;
  label: string;
  value: number;
  group: string;
  r: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  color: string;
