                [class.focused]="focusedIndex() === i"
                role="menuitem"
                [attr.aria-disabled]="item.disabled"
                (click)="onItemClick(item)"
                (mouseenter)="focusedIndex.set(i)"
              >
                @if (item.icon) { <span class="item-icon">{{ item.icon }}</span> }
