export interface TopologyNode {
  id: string;
  label: string;
  status: 'idle' | 'thinking' | 'success' | 'error';
  type?: string;     // e.g. 'orchestrator' | 'agent' | 'tool' | 'critic'
  prompt?: string;
  response?: string;
  x?: number;
  y?: number;
}

export interface TopologyLink {
  source: string;
  target: string;
  active?: boolean;
}

interface ProcessedNode extends TopologyNode {
  x: number;
  y: number;
  depth: number;
}

