        @if (isExpanded(node.id) && node.children) {
          @for (child of node.children; track child.id) {
            <ng-container *ngTemplateOutlet="nodeTemplate; context: { node: child, depth: depth + 1 }"/>
          }
        }
      </ng-template>
    </div>
