  svgEl = viewChild<ElementRef<SVGElement>>('svgEl');

  margin = computed(() => ({
    top: 10,
    right: 10,
    bottom: 10,
    left: 10
  }));

  svgHeight = computed(() => this.height());
  innerW = computed(() => Math.max(10, this.containerWidth() - this.margin().left - this.margin().right));
  innerH = computed(() => Math.max(10, this.svgHeight() - this.margin().top - this.margin().bottom));

  isThreeSets = computed<boolean>(() => this.sets().length >= 3);

  // Geometry configuration of circles
  circles = computed(() => {
    const is3 = this.isThreeSets();
    const w = this.innerW();
    const h = this.innerH();
    const cols = this.colors();

    if (!is3) {
      // 2 circles
      const r = Math.min(w, h) * 0.32;
      const cxA = w / 2 - r * 0.45;
      const cxB = w / 2 + r * 0.45;
      const cy = h / 2;

      return [
        { id: 'A', cx: cxA, cy, r, color: cols[0] || '#4a90d9' },
        { id: 'B', cx: cxB, cy, r, color: cols[1] || '#ff6358' }
      ];
    } else {
      // 3 circles
      const r = Math.min(w, h) * 0.28;
      const cxA = w / 2;
      const cyA = h / 2 - r * 0.38;
      const cxB = w / 2 - r * 0.45;
      const cyB = h / 2 + r * 0.4;
      const cxC = w / 2 + r * 0.45;
      const cyC = h / 2 + r * 0.4;

      return [
        { id: 'A', cx: cxA, cy: cyA, r, color: cols[0] || '#4a90d9' },
        { id: 'B', cx: cxB, cy: cyB, r, color: cols[1] || '#ff6358' },
        { id: 'C', cx: cxC, cy: cyC, r, color: cols[2] || '#27ae60' }
      ];
    }
  });

  computedRegions = computed<VennRegion[]>(() => {
    const is3 = this.isThreeSets();
    const sizeMap = this.sizes();
    const circs = this.circles();
    const labels = this.sets();
    const cols = this.colors();

    const labelA = labels[0] || 'A';
    const labelB = labels[1] || 'B';

    if (!is3) {
      const cA = circs[0];
      const cB = circs[1];

      return [
        {
          key: 'A',
          label: `${labelA} only`,
          value: sizeMap['A'] ?? 100,
          color: cA.color,
          textX: cA.cx - cA.r * 0.4,
          textY: cA.cy - 5
        },
        {
          key: 'B',
          label: `${labelB} only`,
          value: sizeMap['B'] ?? 80,
          color: cB.color,
          textX: cB.cx + cB.r * 0.4,
          textY: cB.cy - 5
        },
        {
          key: 'A&B',
          label: 'Overlap',
          value: sizeMap['A&B'] ?? 30,
          color: cols[2] || '#f39c12',
          textX: (cA.cx + cB.cx) / 2,
          textY: cA.cy - 5
        }
      ];
    } else {
      const labelC = labels[2] || 'C';
      const cA = circs[0];
      const cB = circs[1];
      const cC = circs[2];

      return [
        {
          key: 'A',
          label: `${labelA} only`,
          value: sizeMap['A'] ?? 120,
          color: cA.color,
          textX: cA.cx,
          textY: cA.cy - cA.r * 0.45
        },
        {
          key: 'B',
          label: `${labelB} only`,
          value: sizeMap['B'] ?? 100,
          color: cB.color,
          textX: cB.cx - cB.r * 0.4,
          textY: cB.cy + cB.r * 0.25
        },
        {
          key: 'C',
          label: `${labelC} only`,
          value: sizeMap['C'] ?? 90,
          color: cC.color,
          textX: cC.cx + cC.r * 0.4,
          textY: cC.cy + cC.r * 0.25
        },
        {
          key: 'A&B',
          label: `${labelA} ∩ ${labelB}`,
          value: sizeMap['A&B'] ?? 40,
          color: cols[3] || '#f39c12',
          textX: (cA.cx + cB.cx) / 2 - 10,
          textY: (cA.cy + cB.cy) / 2 - 10
        },
        {
          key: 'B&C',
          label: `${labelB} ∩ ${labelC}`,
          value: sizeMap['B&C'] ?? 30,
          color: cols[4] || '#8e44ad',
          textX: (cB.cx + cC.cx) / 2,
          textY: (cB.cy + cC.cy) / 2 + 15
        },
        {
          key: 'A&C',
          label: `${labelA} ∩ ${labelC}`,
          value: sizeMap['A&C'] ?? 25,
          color: cols[5] || '#1abc9c',
          textX: (cA.cx + cC.cx) / 2 + 10,
          textY: (cA.cy + cC.cy) / 2 - 10
        },
        {
          key: 'A&B&C',
          label: 'Intersection',
          value: sizeMap['A&B&C'] ?? 15,
          color: '#34495e',
          textX: cA.cx,
          textY: (cA.cy + cB.cy) / 2 + 5
        }
      ];
    }
  });

  isCircleActive(cId: string): boolean {
    const rKey = this.hoveredRegionKey();
    if (!rKey) return false;
    return rKey.includes(cId);
  }

  constructor() {
    const hostEl = inject(ElementRef).nativeElement;
    if (typeof ResizeObserver !== 'undefined') {
      const resizeObserver = new ResizeObserver(entries => {
        if (!entries || entries.length === 0) return;
        const width = entries[0].contentRect.width;
        if (width > 0) {
          this.containerWidth.set(width);
        }
      });
      resizeObserver.observe(hostEl);
      inject(DestroyRef).onDestroy(() => resizeObserver.disconnect());
    }
  }

  onSvgMouseMove(event: MouseEvent) {
    const svg = this.svgEl()?.nativeElement;
    if (!svg) return;

    const rect = svg.getBoundingClientRect();
    const mx = event.clientX - rect.left - this.margin().left;
    const my = event.clientY - rect.top - this.margin().top;

    const circs = this.circles();
    const is3 = this.isThreeSets();

    // Calculate containment in circles A, B (and C)
    const inA = this.inCircle(mx, my, circs[0]);
    const inB = this.inCircle(mx, my, circs[1]);
    const inC = is3 ? this.inCircle(mx, my, circs[2]) : false;

    let regionKey = '';
    if (is3) {
      if (inA && inB && inC) regionKey = 'A&B&C';
      else if (inA && inB) regionKey = 'A&B';
      else if (inB && inC) regionKey = 'B&C';
      else if (inA && inC) regionKey = 'A&C';
      else if (inA) regionKey = 'A';
      else if (inB) regionKey = 'B';
      else if (inC) regionKey = 'C';
    } else {
      if (inA && inB) regionKey = 'A&B';
      else if (inA) regionKey = 'A';
      else if (inB) regionKey = 'B';
    }

    if (regionKey) {
      this.hoveredRegionKey.set(regionKey);
      const region = this.computedRegions().find(r => r.key === regionKey);
      if (region) {
        this.tooltip.set(region);
        const parentRect = svg.parentElement?.getBoundingClientRect();
        if (parentRect) {
          this.tooltipX.set(event.clientX - parentRect.left);
          this.tooltipY.set(event.clientY - parentRect.top);
        }
      }
    } else {
      this.hoveredRegionKey.set(null);
      this.tooltip.set(null);
    }
  }

  private inCircle(x: number, y: number, circle: { cx: number; cy: number; r: number }): boolean {
    const dx = x - circle.cx;
    const dy = y - circle.cy;
    return dx * dx + dy * dy <= circle.r * circle.r;
  }

  onMouseLeave() {
    this.hoveredRegionKey.set(null);
    this.tooltip.set(null);
  }

  toggleExportMenu(event: MouseEvent): void {
    event.stopPropagation();
    this.exportMenuOpen.set(!this.exportMenuOpen());
  }

  @HostListener('document:click')
  closeExportMenu(): void {
    this.exportMenuOpen.set(false);
  }

  onExport(type: 'json' | 'csv' | 'svg' | 'pdf'): void {
    this.exportMenuOpen.set(false);
    if (type === 'json') this.exportToJson();
    else if (type === 'csv') this.exportToCsv();
    else if (type === 'svg') this.exportToSvg();
    else if (type === 'pdf') this.exportToPdf();
  }

  exportToCsv(): void {
    const regions = this.computedRegions();
    if (!regions.length) return;

    let csv = 'Region Key,Region Label,Overlap Value\n';
    regions.forEach(r => {
      csv += `"${r.key}","${r.label}",${r.value}\n`;
    });

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'venn-diagram-data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToJson(): void {
    const regions = this.computedRegions();
    if (!regions.length) return;

    const data = regions.map(r => ({
      regionKey: r.key,
      label: r.label,
      value: r.value
    }));

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'venn-diagram-data.json');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToSvg(): void {
    const svg = this.svgEl()?.nativeElement;
    if (!svg) return;
    const serializer = new XMLSerializer();
    let source = serializer.serializeToString(svg);
    if (!source.match(/^<svg[^>]+xmlns="http\:\/\/www\.w3\.org\/2000\/svg"/)) {
      source = source.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
    }
    if (!source.match(/^<svg[^>]+xmlns\:xlink="http\:\/\/www\.w3\.org\/1999\/xlink"/)) {
      source = source.replace(/^<svg/, '<svg xmlns:xlink="http://www.w3.org/1999/xlink"');
    }
    source = '<?xml version="1.0" encoding="utf-8"?>\n' + source;
    const blob = new Blob([source], { type: 'image/svg+xml;charset=utf-8' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'venn-diagram.svg');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToPdf(): void {
    const svg = this.svgEl()?.nativeElement;
    if (!svg || typeof window === 'undefined' || typeof document === 'undefined') return;

    const printWindow = window.open('', '_blank');
    if (!printWindow) {
      alert('Pop-up blocker prevented printing. Please allow pop-ups for this site.');
      return;
    }

    const svgHtml = svg.outerHTML;
    const printTemplate = `
      <html>
      <head>
        <title>Venn Diagram Export</title>
        <style>
          body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; padding: 24px; color: #0f172a; text-align: center; }
          .header { display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #e2e8f0; padding-bottom: 12px; margin-bottom: 24px; text-align: left; }
          .title { font-size: 20px; font-weight: bold; }
          .date { font-size: 12px; color: #64748b; }
          .chart-container { display: inline-block; margin-top: 24px; border: 1px solid #cbd5e1; border-radius: 12px; padding: 20px; background: #ffffff; width: 90%; }
          svg { width: 100%; height: auto; }
          .region-label { font-size: 10.5px; font-weight: bold; fill: #1e293b; }
          .region-val { font-size: 9px; fill: #475569; }
          @media print {
            body { padding: 0; }
            .chart-container { border: none; padding: 0; width: 100%; }
          }
        </style>
      </head>
      <body>
        <div class="header">
          <div class="title">Venn Intersection Overlap Analysis</div>
          <div class="date">${new Date().toLocaleString()}</div>
        </div>
        <div class="chart-container">
          ${svgHtml}
        </div>
        <script>
          window.onload = function() {
            window.print();
            setTimeout(function() { window.close(); }, 500);
          };
        </script>
      </body>
      </html>
    `;

    printWindow.document.write(printTemplate);
    printWindow.document.close();
  }

  formatNumber(v: number): string {
    return fmtNum(v);
  }
}

import {
  Component, ChangeDetectionStrategy, input, computed, signal,
  ElementRef, inject, DestroyRef, viewChild, HostListener
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { CHART_COLORS, fmtNum, niceTicks, scale } from '../shared/chart-utils';

export interface ViolinItem {
  label: string;
  values: number[];
  color?: string;
}

@Component({
  selector: 'ngx-violin-plot',
  standalone: true,
  imports: [CommonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="ngx-violin-plot" (mouseleave)="onMouseLeave()">
      <div class="chart-header" (mousemove)="$event.stopPropagation()" (mouseleave)="onMouseLeave()">
        <div class="chart-title-space"></div>
        @if (showExport()) {
          <div class="chart-export-menu">
            <button class="export-trigger" (click)="toggleExportMenu($event)" aria-label="Export Menu">📤 Export</button>
            @if (exportMenuOpen()) {
              <div class="export-dropdown">
                <button (click)="onExport('json')">📊 Export JSON</button>
                <button (click)="onExport('csv')">📄 Export CSV</button>
                <button (click)="onExport('svg')">🖼️ Export SVG</button>
                <button (click)="onExport('pdf')">📕 Export PDF</button>
              </div>
            }
          </div>
        }
      </div>

      <svg
        #svgEl
        class="violin-svg"
        [attr.width]="'100%'"
        [attr.height]="svgHeight()"
      >
        <g [attr.transform]="'translate(' + margin().left + ',' + margin().top + ')'">
          <!-- Grid Lines (Horizontal reference grid) -->
          @if (showGrid()) {
            @for (tick of yTicks(); track tick) {
              <line
                [attr.x1]="0"
                [attr.x2]="innerW()"
                [attr.y1]="yPos(tick)"
                [attr.y2]="yPos(tick)"
                class="grid-line"
              />
            }
          }

          <!-- Violins -->
          @for (item of computedItems(); track item.label; let i = $index) {
            <g
              class="violin-group"
              [class.dimmed]="hoveredIndex() !== null && hoveredIndex() !== i"
              [class.highlighted]="hoveredIndex() === i"
              (mouseenter)="onItemHover(i, $event)"
              (mousemove)="onItemMouseMove($event)"
            >
              <!-- Row/column hover trigger zone -->
              <rect
                [attr.x]="item.centerX - colWidth() / 2"
                [attr.y]="-margin().top"
                [attr.width]="colWidth()"
                [attr.height]="svgHeight()"
                fill="transparent"
                style="cursor: pointer;"
              />

              <!-- Symmetrical Violin Path -->
              <path
                [attr.d]="item.path"
                [attr.fill]="item.color"
                fill-opacity="0.3"
                [attr.stroke]="item.color"
                stroke-width="1.5"
                class="violin-path"
              />

              <!-- Overlay Jittered Points -->
              @if (showPoints()) {
                @for (val of item.values; track val; let sIdx = $index) {
                  <circle
                    [attr.cx]="item.centerX + getJitterOffset(val, sIdx, item.centerX)"
                    [attr.cy]="yPos(val)"
                    [attr.r]="3"
                    [attr.fill]="item.color"
                    fill-opacity="0.65"
                    class="jitter-point"
                  />
                }
              }

              <!-- Whisker line (min to max) -->
              <line
                [attr.x1]="item.centerX"
                [attr.x2]="item.centerX"
                [attr.y1]="yPos(item.box.min)"
                [attr.y2]="yPos(item.box.max)"
                [attr.stroke]="item.color"
                stroke-width="1"
                class="whisker-line"
              />

              <!-- Q1-Q3 Box -->
              <rect
                [attr.x]="item.centerX - 4"
                [attr.y]="yPos(item.box.q3)"
                [attr.width]="8"
                [attr.height]="Math.max(2, yPos(item.box.q1) - yPos(item.box.q3))"
                [attr.fill]="'#1e293b'"
                [attr.stroke]="item.color"
                stroke-width="1"
                class="box-rect"
              />

              <!-- Median Dot marker -->
              <circle
                [attr.cx]="item.centerX"
                [attr.cy]="yPos(item.box.median)"
                [attr.r]="3"
                fill="#ffffff"
                class="median-dot"
              />

              <!-- Column Category Labels at bottom -->
              @if (showLabels()) {
                <text
                  [attr.x]="item.centerX"
                  [attr.y]="innerH() + 18"
                  text-anchor="middle"
                  class="x-axis-label"
                >
                  {{ item.label }}
                </text>
              }
            </g>
          }

          <!-- Y Axis (Left side) -->
          <g class="y-axis">
            <line [attr.x1]="0" [attr.x2]="0" [attr.y1]="0" [attr.y2]="innerH()" class="axis-line" />
            @for (tick of yTicks(); track tick) {
              <g [attr.transform]="'translate(0,' + yPos(tick) + ')'">
                <line [attr.x1]="-4" [attr.x2]="0" [attr.y1]="0" [attr.y2]="0" class="tick-line" />
                <text
                  [attr.x]="-8"
                  text-anchor="end"
                  dominant-baseline="middle"
                  class="tick-label"
                >
                  {{ formatNumber(tick) }}
                </text>
              </g>
            }
          </g>

          <!-- Bottom X Axis Line -->
          <g [attr.transform]="'translate(0,' + innerH() + ')'" class="x-axis">
            <line [attr.x1]="0" [attr.x2]="innerW()" [attr.y1]="0" [attr.y2]="0" class="axis-line" />
          </g>
        </g>
      </svg>

      <!-- Glassmorphic Tooltip -->
      @if (tooltip(); as t) {
        <div class="chart-tooltip" [style.left.px]="tooltipX()" [style.top.px]="tooltipY()">
          <div class="tt-cat">{{ t.label }}</div>
          <div class="tt-row">
            <span class="tt-name">Samples</span>
            <span class="tt-val">{{ t.count }}</span>
          </div>
          <div class="tt-row">
            <span class="tt-dot" style="background: var(--ngx-chart-axis, #94a3b8);"></span>
            <span class="tt-name">Max</span>
            <span class="tt-val">{{ formatNumber(t.box.max) }}</span>
          </div>
          <div class="tt-row">
            <span class="tt-dot" style="background: var(--ngx-chart-axis, #94a3b8);"></span>
            <span class="tt-name">Q3</span>
            <span class="tt-val">{{ formatNumber(t.box.q3) }}</span>
          </div>
          <div class="tt-row">
            <span class="tt-dot" style="background: #ffffff; border: 1.5px solid var(--ngx-chart-axis, #94a3b8);"></span>
            <span class="tt-name">Median</span>
            <span class="tt-val">{{ formatNumber(t.box.median) }}</span>
          </div>
          <div class="tt-row">
            <span class="tt-dot" style="background: var(--ngx-chart-axis, #94a3b8);"></span>
            <span class="tt-name">Q1</span>
            <span class="tt-val">{{ formatNumber(t.box.q1) }}</span>
          </div>
          <div class="tt-row">
            <span class="tt-dot" style="background: var(--ngx-chart-axis, #94a3b8);"></span>
            <span class="tt-name">Min</span>
            <span class="tt-val">{{ formatNumber(t.box.min) }}</span>
          </div>
        </div>
      }
    </div>
  `,
  styles: [`
    :host {
