export class WaterfallChartComponent {
  PAD_LEFT = 52;
  PAD_TOP = 20;
  PAD_RIGHT = 24;
  PAD_BOTTOM = 36;

  data = input<WaterfallItem[]>([]);
  height = input<number>(300);
  showGrid = input<boolean>(true);
  showLabels = input<boolean>(true);

  // Styling properties
  positiveColor = input<string>('#10b981'); // Emerald
  negativeColor = input<string>('#ef4444'); // Rose/Red
  totalColor = input<string>('#64748b');    // Slate
  showExport = input<boolean>(false);

  hoveredIndex = signal<number | null>(null);
  exportMenuOpen = signal(false);
  tooltip = signal<{
    x: number;
    y: number;
    label: string;
    value: number;
    balance: number;
    color: string;
  } | null>(null);

  svgEl = viewChild<ElementRef<SVGElement>>('svgEl');
  private container = viewChild<ElementRef>('container');

  innerW = computed(() => {
    const el = this.container()?.nativeElement;
    const totalW = el ? el.getBoundingClientRect().width : 600;
    return Math.max(200, totalW - this.PAD_LEFT - this.PAD_RIGHT);
  });

  innerH = computed(() => this.height() - this.PAD_TOP - this.PAD_BOTTOM);

  // Compute intermediate running balances and waterfall metrics
  processedData = computed(() => {
    const raw = this.data();
    let balance = 0;
    return raw.map(item => {
      const start = balance;
      if (item.isTotal) {
        // If it's explicitly designated as a Total, the column represents the current total
        // but wait: does it reset or just display the accumulated balance? It displays the balance!
        const val = balance;
        return {
          label: item.label,
          value: val,
          start: 0,
          end: val,
          isTotal: true,
          runningBalance: val
        };
      } else {
        balance += item.value;
        return {
          label: item.label,
          value: item.value,
          start: start,
          end: balance,
          isTotal: false,
          runningBalance: balance
        };
      }
    });
  });

  // Bounds
  yMin = computed(() => {
    const vals = [0, ...this.processedData().map(d => d.end), ...this.processedData().map(d => d.start)];
    return Math.min(...vals) < 0 ? Math.min(...vals) * 1.1 : 0;
  });

  yMax = computed(() => {
    const vals = [0, ...this.processedData().map(d => d.end), ...this.processedData().map(d => d.start)];
    return Math.max(...vals) * 1.1;
  });

  yTicks = computed(() => niceTicks(this.yMin(), this.yMax(), 5));

  // Scale functions
  xPos(index: number, count: number): number {
    const step = this.innerW() / count;
    return index * step + step * 0.15; // 15% margin
  }

  yPos(y: number): number {
    return scale(y, this.yMin(), this.yMax(), this.innerH(), 0);
  }

  barWidth(count: number): number {
    return (this.innerW() / count) * 0.7; // 70% width
  }

  computedBars = computed(() => {
    const items = this.processedData();
    const count = items.length;
    if (count === 0) return [];
    const width = this.barWidth(count);

    return items.map((item, idx) => {
      const x = this.xPos(idx, count);
      const yStart = this.yPos(item.start);
      const yEnd = this.yPos(item.end);

      const y = Math.min(yStart, yEnd);
      const rectH = Math.max(2, Math.abs(yStart - yEnd));

      let fill = 'url(#waterfall-tot)';
      let color = this.totalColor();
      if (!item.isTotal) {
        fill = item.value >= 0 ? 'url(#waterfall-pos)' : 'url(#waterfall-neg)';
        color = item.value >= 0 ? this.positiveColor() : this.negativeColor();
      }

      // Connect line is drawn from the end value of this item
      const connectY = yEnd;

      return {
        x,
        y,
        rectH,
        width,
        color,
        fill,
        connectY,
        label: item.label,
        value: item.value,
        balance: item.runningBalance,
        isTotal: item.isTotal
      };
    });
  });

  onBarHover(event: MouseEvent, bar: any, index: number) {
    this.hoveredIndex.set(index);
    const containerEl = this.container()?.nativeElement;
    if (!containerEl) return;
    const rect = containerEl.getBoundingClientRect();
    const tooltipX = event.clientX - rect.left;
    const tooltipY = event.clientY - rect.top;

    this.tooltip.set({
      x: tooltipX,
      y: tooltipY,
      label: bar.label,
      value: bar.value,
      balance: bar.balance,
      color: bar.color
    });
  }

  toggleExportMenu(event: MouseEvent): void {
    event.stopPropagation();
    this.exportMenuOpen.set(!this.exportMenuOpen());
  }

  @HostListener('document:click')
  closeExportMenu(): void {
    this.exportMenuOpen.set(false);
  }

  onExport(type: 'json' | 'csv' | 'svg' | 'pdf'): void {
    this.exportMenuOpen.set(false);
    if (type === 'json') this.exportToJson();
    else if (type === 'csv') this.exportToCsv();
    else if (type === 'svg') this.exportToSvg();
    else if (type === 'pdf') this.exportToPdf();
  }

  exportToJson(): void {
    const data = this.data();
    if (!data.length) return;
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'waterfall-chart.json');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToCsv(): void {
    const data = this.data();
    if (!data.length) return;
    let csv = 'Label,Value,Is Total\n';
    data.forEach(d => {
      csv += `"${d.label || ''}",${d.value},${d.isTotal ? 'true' : 'false'}\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'waterfall-chart.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToSvg(): void {
    const svg = this.svgEl()?.nativeElement;
    if (!svg) return;
    const serializer = new XMLSerializer();
    let source = serializer.serializeToString(svg);
    if (!source.match(/^<svg[^>]+xmlns="http\:\/\/www\.w3\.org\/2000\/svg"/)) {
      source = source.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
    }
    if (!source.match(/^<svg[^>]+xmlns\:xlink="http\:\/\/www\.w3\.org\/1999\/xlink"/)) {
      source = source.replace(/^<svg/, '<svg xmlns:xlink="http://www.w3.org/1999/xlink"');
    }
    source = '<?xml version="1.0" encoding="utf-8"?>\n' + source;
    const blob = new Blob([source], { type: 'image/svg+xml;charset=utf-8' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'waterfall-chart.svg');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToPdf(): void {
    const svg = this.svgEl()?.nativeElement;
    if (!svg) return;
    const printWindow = window.open('', '_blank');
    if (!printWindow) return;
    const serializer = new XMLSerializer();
    let svgString = serializer.serializeToString(svg);
    if (!svgString.match(/^<svg[^>]+xmlns="http\:\/\/www\.w3\.org\/2000\/svg"/)) {
      svgString = svgString.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
    }
    printWindow.document.write(`
      <html>
        <head>
          <title>Chart Export</title>
          <style>
            body {
              margin: 20px;
              font-family: system-ui, sans-serif;
              text-align: center;
            }
            .print-container {
              display: inline-block;
              margin: 0 auto;
            }
            svg {
              width: 100%;
              height: auto;
            }
            @media print {
              body { margin: 0; }
              .no-print { display: none; }
            }
          </style>
        </head>
        <body>
          <div class="print-container">
            ${svgString}
          </div>
          <script>
            window.onload = () => {
              setTimeout(() => {
                window.print();
                window.close();
              }, 250);
            };
          </script>
        </body>
      </html>
    `);
    printWindow.document.close();
  }

  readonly fmtNum = fmtNum;
}

import { Injectable, signal, computed } from '@angular/core';

export interface WebLlmMessage {
  role: 'user' | 'assistant' | 'system';
  content: string;
}

@Injectable({
  providedIn: 'root'
})
export class NgxWebLlmService {
  private engine: any = null;

  status = signal<string>('idle');
  progress = signal<number>(0);
  isReady = signal<boolean>(false);
  error = signal<string | null>(null);

  isGpuSupported(): boolean {
    return typeof navigator !== 'undefined' && 'gpu' in navigator && !!(navigator as any).gpu;
  }

  async init(
    modelId: string = 'Qwen2.5-0.5B-Instruct',
    onProgress?: (val: number, msg: string) => void
  ): Promise<void> {
    if (this.isReady()) return;

    this.status.set('loading_scripts');
    this.error.set(null);

    // If GPU is not supported, simulate model loading (useful for testing or fallback dev setups)
    if (!this.isGpuSupported()) {
      console.warn('WebGPU is not supported in this browser environment. Simulating fallback WebLLM Engine.');
      await this.simulateLoading(onProgress);
      return;
    }

    try {
      // Dynamic import of web-llm from CDN. Using type casting to bypass TS compilation lookup checks
      const webLlmModule = await (Function('return import("https://cdn.jsdelivr.net/npm/@mlc-ai/web-llm@0.2.46/+esm")')() as Promise<any>);

      this.status.set('downloading_model');
      this.progress.set(0);

      const engine = await webLlmModule.CreateWebGPUEngine(
        modelId,
        {
          initProgressCallback: (report: any) => {
            const val = report.progress;
            this.progress.set(Math.round(val * 100));
            this.status.set(`loading_model: ${report.text}`);
            if (onProgress) {
              onProgress(val, report.text);
            }
          }
        }
      );

      this.engine = engine;
      this.isReady.set(true);
      this.status.set('ready');
    } catch (err: any) {
      const errMsg = err.message || String(err);
      this.status.set('error');
      this.error.set(errMsg);
      throw new Error(`WebLLM Initialization failed: ${errMsg}`);
    }
  }

  private async simulateLoading(onProgress?: (val: number, msg: string) => void): Promise<void> {
    const steps = [
      { progress: 0.1, text: 'Fetching model config...' },
      { progress: 0.3, text: 'Loading WebGPU device adapter...' },
      { progress: 0.6, text: 'Downloading model weights (simulated)...' },
      { progress: 0.9, text: 'Warming up runtime execution pipeline...' },
      { progress: 1.0, text: 'Finished warming up' }
    ];

    for (const step of steps) {
      await new Promise(resolve => setTimeout(resolve, 100));
      this.progress.set(Math.round(step.progress * 100));
      this.status.set(`loading_model: ${step.text}`);
      if (onProgress) {
        onProgress(step.progress, step.text);
      }
    }

    this.engine = {
      chat: {
        completions: {
          create: async (params: any) => {
            // Return an async iterable stream simulator
            const responseText = `[Simulated WebLLM response to: "${params.messages[params.messages.length - 1]?.content}"] This is a locally generated streaming response using simulated model weights, as WebGPU is not supported on this device.`;
            const tokens = responseText.split(' ');
            return (async function* () {
              for (const token of tokens) {
                await new Promise(resolve => setTimeout(resolve, 40));
                yield {
                  choices: [
                    {
                      delta: {
                        content: token + ' '
                      }
                    }
                  ]
                };
              }
            })();
          }
        }
      }
    };
    this.isReady.set(true);
    this.status.set('ready');
  }

  async generate(
    messages: WebLlmMessage[],
    onToken?: (text: string) => void,
    options?: { max_tokens?: number; temperature?: number }
  ): Promise<string> {
    if (!this.engine) {
      throw new Error('WebLLM Engine is not initialized. Call init() first.');
    }

    this.status.set('generating');
    try {
      let fullText = '';
      const reply = await this.engine.chat.completions.create({
        messages,
        stream: true,
        max_tokens: options?.max_tokens ?? 1024,
        temperature: options?.temperature ?? 0.7
      });

      for await (const chunk of reply) {
        const delta = chunk.choices[0]?.delta?.content || '';
        if (delta) {
          fullText += delta;
          if (onToken) {
            onToken(fullText);
          }
        }
      }
      this.status.set('ready');
      return fullText;
    } catch (err: any) {
      this.status.set('error');
      this.error.set(err.message || String(err));
      throw err;
    }
  }

  reset(): void {
    this.engine = null;
    this.isReady.set(false);
    this.status.set('idle');
    this.progress.set(0);
    this.error.set(null);
  }
}

