        const color = palette[bIdx % palette.length];

        const x1 = startRad * Math.cos(startAngle);
        const y1 = startRad * Math.sin(startAngle);
        const x2 = startRad * Math.cos(endAngle);
        const y2 = startRad * Math.sin(endAngle);

        const x3 = endRad * Math.cos(endAngle);
        const y3 = endRad * Math.sin(endAngle);
        const x4 = endRad * Math.cos(startAngle);
        const y4 = endRad * Math.sin(startAngle);

        const path = `M ${x4} ${y4} L ${x3} ${y3} A ${endRad} ${endRad} 0 0 0 ${x2} ${y2} L ${x1} ${y1} A ${startRad} ${startRad} 0 0 1 ${x4} ${y4} Z`;

        return {
          direction: item.direction,
          binLabel: bin.label,
          value,
          cumValue: runningSum,
          color,
          path
        };
      });

      return {
        direction: item.direction,
        angle,
        bins
      };
    });
  });

  legendItems = computed(() => {
    const raw = this.data();
    if (raw.length === 0) return [];

    const firstWedge = raw[0];
    const palette = this.colors();

    return firstWedge.speedBins.map((bin, idx) => ({
      label: bin.label,
      color: palette[idx % palette.length]
    }));
  });

  onWedgeHover(wIdx: number, bIdx: number, event: MouseEvent) {
    this.hoveredBin.set({ wIdx, bIdx });
    const wedge = this.computedWedges()[wIdx];
    if (wedge) {
      const bin = wedge.bins[bIdx];
      if (bin) {
        this.tooltip.set(bin);
      }
    }
  }

  onMouseMove(event: MouseEvent) {
    const el = event.currentTarget as SVGElement;
    const container = el.closest('.ngx-wind-rose');
    if (container) {
      const rect = container.getBoundingClientRect();
      this.tooltipX.set(event.clientX - rect.left);
      this.tooltipY.set(event.clientY - rect.top);
    }
  }

  onMouseLeave() {
    this.hoveredBin.set(null);
    this.tooltip.set(null);
  }

  toggleExportMenu(event: MouseEvent): void {
    event.stopPropagation();
    this.exportMenuOpen.set(!this.exportMenuOpen());
  }

  @HostListener('document:click')
  closeExportMenu(): void {
    this.exportMenuOpen.set(false);
  }

  onExport(type: 'json' | 'csv' | 'svg'): void {
    this.exportMenuOpen.set(false);
    if (type === 'json') this.exportToJson();
    else if (type === 'csv') this.exportToCsv();
    else if (type === 'svg') this.exportToSvg();
  }

  exportToCsv(): void {
    const raw = this.data();
    if (!raw.length) return;

    let csv = 'Direction,SpeedBin,Frequency\n';
    raw.forEach(item => {
      item.speedBins.forEach(bin => {
        csv += `"${item.direction}","${bin.label}",${bin.value}\n`;
      });
    });

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'wind-rose-data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToJson(): void {
    const raw = this.data();
    if (!raw.length) return;

    const data = raw.flatMap(item =>
      item.speedBins.map(bin => ({
        direction: item.direction,
        binLabel: bin.label,
        value: bin.value
      }))
    );

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'wind-rose-data.json');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToSvg(): void {
    const svg = this.svgEl()?.nativeElement;
    if (!svg) return;
    const serializer = new XMLSerializer();
    let source = serializer.serializeToString(svg);
    if (!source.match(/^<svg[^>]+xmlns="http\:\/\/www\.w3\.org\/2000\/svg"/)) {
      source = source.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
    }
    if (!source.match(/^<svg[^>]+xmlns\:xlink="http\:\/\/www\.w3\.org\/1999\/xlink"/)) {
      source = source.replace(/^<svg/, '<svg xmlns:xlink="http://www.w3.org/1999/xlink"');
    }
    source = '<?xml version="1.0" encoding="utf-8"?>\n' + source;
    const blob = new Blob([source], { type: 'image/svg+xml;charset=utf-8' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'wind-rose.svg');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }
}

import {
  Component, ChangeDetectionStrategy, input, computed, signal,
  ElementRef, inject, DestroyRef, TemplateRef, viewChild, HostListener
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { CHART_COLORS, fmtNum, scale } from '../shared/chart-utils';

export interface WordItem {
  text: string;
  value: number;
  color?: string;
}

export interface PlacedWord {
  raw: WordItem;
  index: number;
  text: string;
  fontSize: number;
  x: number;
  y: number;
  width: number;
  height: number;
  color: string;
}

interface BoundingBox {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
}

@Component({
  selector: 'ngx-word-cloud',
  standalone: true,
  imports: [CommonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="ngx-word-cloud" (mouseleave)="onMouseLeave()">
      <div class="chart-header" (mousemove)="$event.stopPropagation()" (mouseleave)="onMouseLeave()">
        <div class="header-info">
          <span class="header-title">Word Cloud Frequency</span>
          <span class="header-subtitle">Key terms analysis</span>
        </div>

        @if (showExport()) {
          <div class="chart-export-menu">
            <button class="export-trigger" (click)="toggleExportMenu($event)" aria-label="Export Menu">📤 Export</button>
            @if (exportMenuOpen()) {
              <div class="export-dropdown">
                <button (click)="onExport('json')">📊 Export JSON</button>
                <button (click)="onExport('csv')">📄 Export CSV</button>
                <button (click)="onExport('svg')">🖼️ Export SVG</button>
                <button (click)="onExport('pdf')">📕 Export PDF</button>
              </div>
            }
          </div>
        }
      </div>

      <svg
        #svgEl
        class="word-cloud-svg"
        [attr.width]="'100%'"
        [attr.height]="svgHeight()"
      >
        <g [attr.transform]="'translate(' + margin().left + ',' + margin().top + ')'">
          @for (word of placedWords(); track word.index; let i = $index) {
            <g
              class="word-group"
              [class.dimmed]="hoveredIndex() !== null && hoveredIndex() !== i"
              [class.highlighted]="hoveredIndex() === i"
              [attr.transform]="'translate(' + word.x + ',' + word.y + ')'"
              (mouseenter)="onWordHover(i)"
              (mousemove)="onMouseMove($event)"
            >
              <text
                text-anchor="middle"
                dominant-baseline="central"
                [attr.font-size]="word.fontSize + 'px'"
                [attr.fill]="word.color"
                [style.font-weight]="'700'"
                class="cloud-word-text"
              >
                {{ word.text }}
              </text>
            </g>
          }
        </g>
      </svg>

      <!-- Glassmorphic Tooltip -->
      @if (tooltip(); as t) {
        <div class="chart-tooltip" [style.left.px]="tooltipX()" [style.top.px]="tooltipY()">
          @if (tooltipTemplate()) {
            <ng-container
              *ngTemplateOutlet="tooltipTemplate()!; context: { $implicit: t }"
            ></ng-container>
          } @else {
            <div class="tt-cat">{{ t.text }}</div>
            <div class="tt-row">
              <span class="tt-name">Weight/Count</span>
              <span class="tt-val">{{ formatNumber(t.value) }}</span>
            </div>
          }
        </div>
      }
    </div>
  `,
  styles: [`
    :host {
      display: block;
      position: relative;
    }
    .ngx-word-cloud {
      background: var(--ngx-chart-bg, #ffffff);
      border: 1px solid var(--border-color, #e2e8f0);
      border-radius: 16px;
      padding: 16px;
      box-sizing: border-box;
      font-family: var(--ngx-font-family, system-ui, sans-serif);
      position: relative;
      width: 100%;
    }
    .chart-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 12px;
      min-height: 24px;
      position: relative;
    }
    .header-info {
      display: flex;
      flex-direction: column;
    }
    .header-title {
      font-size: 14px;
      font-weight: 700;
      color: var(--ngx-chart-axis-text, #334155);
    }
    .header-subtitle {
      font-size: 11px;
      font-weight: 500;
      color: var(--ngx-chart-axis-text, #64748b);
    }
    .word-cloud-svg {
      display: block;
      overflow: visible;
    }
    .word-group {
      cursor: pointer;
      transition: opacity 0.2s ease, transform 0.2s ease;
    }
    .word-group.dimmed {
      opacity: 0.18 !important;
    }
    .word-group.highlighted {
      transform: scale(1.1);
      filter: drop-shadow(0 4px 8px rgba(0,0,0,0.18));
      opacity: 1 !important;
    }
    .cloud-word-text {
      user-select: none;
      transition: fill 0.15s ease;
    }

    /* Glassmorphic Tooltip */
    .chart-tooltip {
      position: absolute;
      pointer-events: none;
      transform: translate(-50%, -100%) translateY(-10px);
      background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.92));
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      color: var(--ngx-chart-tooltip-color, #f8fafc);
      padding: 10px 14px;
      border-radius: 10px;
      font-size: 12px;
      min-width: 120px;
      box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3), 0 8px 10px -6px rgba(0,0,0,0.3);
      border: 1px solid rgba(255, 255, 255, 0.1);
      z-index: 100;
      transition: left 0.1s cubic-bezier(0.16, 1, 0.3, 1), top 0.1s cubic-bezier(0.16, 1, 0.3, 1);
    }
    .tt-cat {
      font-weight: 700;
      margin-bottom: 6px;
      font-size: 12.5px;
      border-bottom: 1px solid rgba(255, 255, 255, 0.15);
      padding-bottom: 4px;
      color: #38bdf8;
    }
    .tt-row {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-top: 4px;
    }
    .tt-name {
      color: rgba(248, 250, 252, 0.8);
      flex: 1;
    }
    .tt-val {
      font-weight: 700;
      font-family: monospace;
    }

    /* Export dropdown styles */
    .chart-export-menu {
      position: relative;
      z-index: 50;
    }
    .export-trigger {
      padding: 4px 10px;
      font-size: 11px;
      font-weight: 600;
      color: var(--ngx-chart-axis-text, #64748b);
      background: rgba(241, 245, 249, 0.8);
      backdrop-filter: blur(8px);
      border: 1px solid var(--ngx-chart-grid, #e2e8f0);
      border-radius: 6px;
      cursor: pointer;
      transition: all 0.15s;
    }
    .export-trigger:hover {
      background: #ffffff;
      color: #4f46e5;
      border-color: #4f46e5;
    }
    .export-dropdown {
      position: absolute;
      right: 0;
      top: calc(100% + 4px);
      background: #ffffff;
      border: 1px solid var(--ngx-chart-grid, #e2e8f0);
      border-radius: 8px;
      box-shadow: 0 10px 15px -3px rgba(0,0,0,0.1);
      padding: 4px;
      display: flex;
      flex-direction: column;
      gap: 2px;
      min-width: 120px;
    }
    .export-dropdown button {
      background: none;
      border: none;
      padding: 6px 10px;
      font-size: 11px;
      text-align: left;
      cursor: pointer;
      color: #1e293b;
      border-radius: 4px;
      width: 100%;
      transition: all 0.12s;
    }
    .export-dropdown button:hover {
      background: rgba(79, 70, 229, 0.06);
      color: #4f46e5;
    }
  `]
})
export class WordCloudComponent {
  data = input<WordItem[]>([]);
  height = input<number>(350);
  colors = input<string[]>(CHART_COLORS);
  showExport = input<boolean>(false);
  tooltipTemplate = input<TemplateRef<any> | null>(null);

  containerWidth = signal<number>(500);
  hoveredIndex = signal<number | null>(null);
  tooltip = signal<any | null>(null);
  tooltipX = signal<number>(0);
  tooltipY = signal<number>(0);
  exportMenuOpen = signal(false);

  svgEl = viewChild<ElementRef<SVGElement>>('svgEl');

  margin = computed(() => ({
    top: 10,
    right: 10,
    bottom: 10,
    left: 10
  }));

  svgHeight = computed(() => this.height());
  innerW = computed(() => Math.max(10, this.containerWidth() - this.margin().left - this.margin().right));
  innerH = computed(() => Math.max(10, this.svgHeight() - this.margin().top - this.margin().bottom));

  // Placement calculation based on Archimedean spiral
  placedWords = computed<PlacedWord[]>(() => {
    const raw = [...this.data()].sort((a, b) => b.value - a.value);
    if (raw.length === 0) return [];

    const w = this.innerW();
    const h = this.innerH();
    const cx = w / 2;
    const cy = h / 2;

    const minVal = Math.min(...raw.map(d => d.value));
    const maxVal = Math.max(1, ...raw.map(d => d.value));

    const cols = this.colors();
    const placed: PlacedWord[] = [];
    const boxes: BoundingBox[] = [];

    // Aspect ratio multiplier to handle non-square layout bounds
    const aspectRatio = w / h;

    raw.forEach((d, idx) => {
      // Scale font size
      const fSize = Math.round(scale(d.value, minVal, maxVal, 10, 42));

      // Bounding box approximation (standard average character width multiplier is 0.55)
      const wordW = d.text.length * fSize * 0.58;
      const wordH = fSize * 1.1;

      let placedSuccessfully = false;
      let theta = 0;
      let radiusMultiplier = 1.5;

      // Try placing along the Archimedean spiral
      for (let step = 0; step < 300; step++) {
        // Spiral equations
        const r = radiusMultiplier * theta;
        const x = cx + r * Math.cos(theta) * aspectRatio;
        const y = cy + r * Math.sin(theta);

        // Word box centered at (x, y)
        const box: BoundingBox = {
          x1: x - wordW / 2,
          y1: y - wordH / 2,
          x2: x + wordW / 2,
          y2: y + wordH / 2
        };

        // Collision check
        const collides = boxes.some(b => {
          return !(box.x2 < b.x1 || box.x1 > b.x2 || box.y2 < b.y1 || box.y1 > b.y2);
        });

        // Check if outside SVG bounds (leave 10px buffer)
        const outOfBounds = box.x1 < 10 || box.x2 > w - 10 || box.y1 < 10 || box.y2 > h - 10;

        if (!collides && !outOfBounds) {
          boxes.push(box);
          placed.push({
            raw: d,
            index: idx,
            text: d.text,
            fontSize: fSize,
            x,
            y,
            width: wordW,
            height: wordH,
            color: d.color || cols[idx % cols.length]
          });
          placedSuccessfully = true;
          break;
        }

        // Increment spiral parameters
        theta += 0.12;
      }

      // Fallback: If cannot fit, place on outer edge or omit to prevent clutter
      if (!placedSuccessfully) {
        // Place at random boundary spot
        const angle = Math.random() * Math.PI * 2;
        const radius = Math.min(w, h) * 0.42;
        const x = cx + radius * Math.cos(angle);
        const y = cy + radius * Math.sin(angle);
        placed.push({
          raw: d,
          index: idx,
          text: d.text,
          fontSize: fSize,
          x,
          y,
          width: wordW,
          height: wordH,
          color: d.color || cols[idx % cols.length]
        });
      }
    });

    return placed;
  });

  constructor() {
    const hostEl = inject(ElementRef).nativeElement;
    if (typeof ResizeObserver !== 'undefined') {
      const resizeObserver = new ResizeObserver(entries => {
        if (!entries || entries.length === 0) return;
        const width = entries[0].contentRect.width;
        if (width > 0) {
          this.containerWidth.set(width);
        }
      });
      resizeObserver.observe(hostEl);
      inject(DestroyRef).onDestroy(() => resizeObserver.disconnect());
    }
  }

  onWordHover(idx: number) {
    this.hoveredIndex.set(idx);
    const word = this.placedWords()[idx];
    if (word) {
      this.tooltip.set(word.raw);
    }
  }

  onMouseMove(event: MouseEvent) {
    const el = event.currentTarget as SVGElement;
    const container = el.closest('.ngx-word-cloud');
    if (container) {
      const rect = container.getBoundingClientRect();
      this.tooltipX.set(event.clientX - rect.left);
      this.tooltipY.set(event.clientY - rect.top);
    }
  }

  onMouseLeave() {
    this.hoveredIndex.set(null);
    this.tooltip.set(null);
  }

  toggleExportMenu(event: MouseEvent): void {
    event.stopPropagation();
    this.exportMenuOpen.set(!this.exportMenuOpen());
  }

  @HostListener('document:click')
  closeExportMenu(): void {
    this.exportMenuOpen.set(false);
  }

  onExport(type: 'json' | 'csv' | 'svg' | 'pdf'): void {
    this.exportMenuOpen.set(false);
    if (type === 'json') this.exportToJson();
    else if (type === 'csv') this.exportToCsv();
    else if (type === 'svg') this.exportToSvg();
    else if (type === 'pdf') this.exportToPdf();
  }

  exportToCsv(): void {
    const words = this.placedWords();
    if (!words.length) return;

    let csv = 'Text,Value\n';
    words.forEach(w => {
      csv += `"${w.text}",${w.raw.value}\n`;
    });

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'word-cloud-data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToJson(): void {
    const words = this.placedWords();
    if (!words.length) return;

    const data = words.map(w => ({
      text: w.text,
      value: w.raw.value
    }));

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'word-cloud-data.json');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToSvg(): void {
    const svg = this.svgEl()?.nativeElement;
    if (!svg) return;
    const serializer = new XMLSerializer();
    let source = serializer.serializeToString(svg);
    if (!source.match(/^<svg[^>]+xmlns="http\:\/\/www\.w3\.org\/2000\/svg"/)) {
      source = source.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
    }
    if (!source.match(/^<svg[^>]+xmlns\:xlink="http\:\/\/www\.w3\.org\/1999\/xlink"/)) {
      source = source.replace(/^<svg/, '<svg xmlns:xlink="http://www.w3.org/1999/xlink"');
    }
    source = '<?xml version="1.0" encoding="utf-8"?>\n' + source;
    const blob = new Blob([source], { type: 'image/svg+xml;charset=utf-8' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'word-cloud.svg');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  exportToPdf(): void {
    const svg = this.svgEl()?.nativeElement;
    if (!svg || typeof window === 'undefined' || typeof document === 'undefined') return;

    const printWindow = window.open('', '_blank');
    if (!printWindow) {
      alert('Pop-up blocker prevented printing. Please allow pop-ups for this site.');
      return;
    }

    const svgHtml = svg.outerHTML;
    const printTemplate = `
      <html>
      <head>
        <title>Word Cloud Export</title>
        <style>
          body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; padding: 24px; color: #0f172a; text-align: center; }
          .header { display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #e2e8f0; padding-bottom: 12px; margin-bottom: 24px; text-align: left; }
          .title { font-size: 20px; font-weight: bold; }
          .date { font-size: 12px; color: #64748b; }
          .chart-container { display: inline-block; margin-top: 24px; border: 1px solid #cbd5e1; border-radius: 12px; padding: 20px; background: #ffffff; width: 90%; }
          svg { width: 100%; height: auto; }
          .cloud-word-text { font-weight: bold; }
          @media print {
            body { padding: 0; }
            .chart-container { border: none; padding: 0; width: 100%; }
          }
        </style>
      </head>
      <body>
        <div class="header">
          <div class="title">Word Cloud Frequency Analysis</div>
          <div class="date">${new Date().toLocaleString()}</div>
        </div>
        <div class="chart-container">
          ${svgHtml}
        </div>
        <script>
          window.onload = function() {
            window.print();
            setTimeout(function() { window.close(); }, 500);
          };
        </script>
      </body>
      </html>
    `;

    printWindow.document.write(printTemplate);
    printWindow.document.close();
  }

  formatNumber(v: number): string {
    return fmtNum(v);
  }
}

