import {
  Injectable, ApplicationRef, createComponent, EnvironmentInjector,
  inject, signal, Type, PLATFORM_ID
} from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { DialogContainerComponent } from './dialog-container.component';

export interface DialogConfig<D = unknown> {
  /** Data passed to the dialog content component via the `dialogData` input. */
  data?: D;
  /** Whether clicking the backdrop closes the dialog. Defaults to true. */
  closeOnBackdrop?: boolean;
  /** Additional CSS class(es) to apply to the dialog panel. */
  panelClass?: string | string[];
  /** ARIA label for the dialog (for screen readers). */
  ariaLabel?: string;
  /** Max width of the dialog panel (CSS value). Defaults to '560px'. */
  maxWidth?: string;
}

export interface DialogRef<R = unknown> {
  /** Emits the result value and removes the dialog from the DOM. */
  close(result?: R): void;
  /** Signal that resolves with the result once the dialog closes. */
  readonly closed: ReturnType<typeof signal<R | undefined>>;
}

/**
 * DialogService — programmatically opens Angular components inside a floating
 * overlay without requiring NgModule or z-index hacks.
 *
 * Usage:
 * ```ts
 * const ref = this.dialog.open(MyFormComponent, { data: { id: 42 } });
 * ref.closed(); // reactive signal — undefined until dialog closes
 * ```
 */
@Injectable({ providedIn: 'root' })
export class DialogService {
  private appRef = inject(ApplicationRef);
  private injector = inject(EnvironmentInjector);
  private platformId = inject(PLATFORM_ID);

  open<C, D = unknown, R = unknown>(
    component: Type<C>,
    config?: DialogConfig<D>,
  ): DialogRef<R> {
    const closedSignal = signal<R | undefined>(undefined);
    let remove = () => {};

    const previouslyFocused = isPlatformBrowser(this.platformId) ? document.activeElement as HTMLElement : null;

    const dialogRef: DialogRef<R> = {
      closed: closedSignal,
      close: (result?: R) => {
        closedSignal.set(result);
        if (isPlatformBrowser(this.platformId)) {
          remove();
        }
      },
    };

    if (!isPlatformBrowser(this.platformId)) {
      return dialogRef;
    }

    const cfg: Required<DialogConfig<D>> = {
      data: config?.data as D,
      closeOnBackdrop: config?.closeOnBackdrop ?? true,
      panelClass: config?.panelClass ?? [],
      ariaLabel: config?.ariaLabel ?? 'Dialog',
      maxWidth: config?.maxWidth ?? '560px',
    };

    // Create a host element appended to <body>
    const hostEl = document.createElement('ngx-dialog-host');
    document.body.appendChild(hostEl);

    // Create the container component
    const containerRef = createComponent(DialogContainerComponent, {
      environmentInjector: this.injector,
      hostElement: hostEl,
    });

    const container = containerRef.instance;
    container.ariaLabel = cfg.ariaLabel;
    container.maxWidth = cfg.maxWidth;
    container.panelClass = Array.isArray(cfg.panelClass)
      ? cfg.panelClass.join(' ')
      : cfg.panelClass;

    container.backdropClick = () => {
      if (cfg.closeOnBackdrop) dialogRef.close();
    };

    // Create the content component and project it into the container
    const contentRef = createComponent(component as Type<unknown>, {
      environmentInjector: this.injector,
      projectableNodes: [],
    });

    // Always assign common integration properties so dynamic dialog content
    // can close itself even when these are plain class fields (not @Input).
    const instance = contentRef.instance as Record<string, unknown>;
    instance['dialogData'] = cfg.data;
    instance['dialogRef'] = dialogRef;

    // If the content uses Angular inputs, update them through setInput as well.
    if (typeof contentRef.setInput === 'function') {
      try { contentRef.setInput('dialogData', cfg.data); } catch {}
      try { contentRef.setInput('dialogRef', dialogRef); } catch {}
    }

    container.attachContent(contentRef.hostView);
    this.appRef.attachView(containerRef.hostView);

    // Ensure the content template sees injected properties immediately.
    contentRef.changeDetectorRef.detectChanges();

    containerRef.changeDetectorRef.detectChanges();

    remove = () => {
      this.appRef.detachView(containerRef.hostView);
      contentRef.destroy();
      containerRef.destroy();
      if (document.body.contains(hostEl)) {
        document.body.removeChild(hostEl);
      }
      if (previouslyFocused && typeof previouslyFocused.focus === 'function') {
        previouslyFocused.focus();
      }
    };

    return dialogRef;
  }
}

import { Injectable, signal, computed } from '@angular/core';

@Injectable()
export class GanttKeyboardService {
  readonly focusedTaskId = signal<string | null>(null);

  focusTask(taskId: string): void {
    this.focusedTaskId.set(taskId);
  }

  clearFocus(): void {
    this.focusedTaskId.set(null);
  }

  handleKeyDown(
    event: KeyboardEvent,
    visibleTaskIds: string[],
    callbacks: {
      onSelect?: (taskId: string) => void;
      onEscape?: () => void;
    }
  ): void {
    const currentId = this.focusedTaskId();
    const currentIndex = currentId ? visibleTaskIds.indexOf(currentId) : -1;

    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        if (currentIndex < visibleTaskIds.length - 1) {
          this.focusTask(visibleTaskIds[currentIndex + 1]);
        }
        break;
      case 'ArrowUp':
        event.preventDefault();
        if (currentIndex > 0) {
          this.focusTask(visibleTaskIds[currentIndex - 1]);
        }
        break;
      case 'Enter':
      case ' ':
        event.preventDefault();
        if (currentId && callbacks.onSelect) {
          callbacks.onSelect(currentId);
        }
        break;
      case 'Escape':
        this.clearFocus();
        callbacks.onEscape?.();
        break;
    }
  }
}

import { Injectable } from '@angular/core';
import { GanttTask } from '../models/gantt-task.model';
import { GanttGroup } from '../models/gantt-group.model';

export interface FlatRow {
  task: GanttTask;
  /** Additional tasks that share this row (same rowId). */
  extraTasks: GanttTask[];
  depth: number;
  rowIndex: number;
  hasChildren: boolean;
  isVisible: boolean;
  /** Set when this row is a group header. */
  group?: GanttGroup;
  /** Whether this is a group header row. */
  isGroupHeader: boolean;
}

interface RowGroup {
  primary: GanttTask;
  extra: GanttTask[];
}

@Injectable()
export class GanttLayoutService {
  flattenTasks(tasks: GanttTask[], groups?: GanttGroup[]): FlatRow[] {
    if (groups && groups.length > 0) {
      return this.flattenWithGroups(tasks, groups);
    }
    return this.flattenTree(tasks);
  }

  private flattenTree(tasks: GanttTask[]): FlatRow[] {
    const childrenMap = new Map<string | null, GanttTask[]>();
    for (const task of tasks) {
      const parentId = task.parentId;
      if (!childrenMap.has(parentId)) {
        childrenMap.set(parentId, []);
      }
      childrenMap.get(parentId)!.push(task);
    }

    const rows: FlatRow[] = [];
    let rowIndex = 0;

    const traverse = (parentId: string | null, depth: number, parentVisible: boolean): void => {
      const children = childrenMap.get(parentId) || [];

      // Group children by rowId, preserving original order for primary tasks.
      const rowGroups: RowGroup[] = [];
      const rowIdToGroup = new Map<string, RowGroup>();

      for (const task of children) {
        if (task.rowId) {
          const existing = rowIdToGroup.get(task.rowId);
          if (existing) {
            existing.extra.push(task);
          } else {
            const group = { primary: task, extra: [] as GanttTask[] };
            rowGroups.push(group);
            rowIdToGroup.set(task.rowId, group);
          }
        } else {
          rowGroups.push({ primary: task, extra: [] });
        }
      }

      for (const { primary: task, extra: extraTasks } of rowGroups) {
        const hasChildren = childrenMap.has(task.id) && childrenMap.get(task.id)!.length > 0;
        const isVisible = parentVisible;
        rows.push({ task, extraTasks, depth, rowIndex: isVisible ? rowIndex : -1, hasChildren, isVisible, isGroupHeader: false });
        if (isVisible) rowIndex++;
        const childVisible = isVisible && !task.collapsed;
        traverse(task.id, depth + 1, childVisible);
      }
    };

    traverse(null, 0, true);
    return rows;
  }

  private flattenWithGroups(tasks: GanttTask[], groups: GanttGroup[]): FlatRow[] {
    const rows: FlatRow[] = [];
    let rowIndex = 0;

    // Build a map of tasks by group_id
    const tasksByGroup = new Map<string, GanttTask[]>();
    const ungroupedTasks: GanttTask[] = [];
    for (const task of tasks) {
      if (task.group_id) {
        if (!tasksByGroup.has(task.group_id)) {
          tasksByGroup.set(task.group_id, []);
        }
        tasksByGroup.get(task.group_id)!.push(task);
      } else {
        ungroupedTasks.push(task);
      }
    }

    for (const group of groups) {
      // Create a pseudo-task for the group header
      const groupTask: GanttTask = {
        id: `__group__${group.id}`,
        name: group.title,
        start: new Date(),
        end: new Date(),
        progress: 0,
        parentId: null,
        collapsed: group.expanded === false,
        isMilestone: false,
        cssClass: group.class,
      };

      const groupTasks = tasksByGroup.get(group.id) || [];

      // Calculate group date range
      if (groupTasks.length > 0) {
        let minStart = groupTasks[0].start.getTime();
        let maxEnd = groupTasks[0].end.getTime();
        let totalProgress = 0;
        for (const t of groupTasks) {
          if (t.start.getTime() < minStart) minStart = t.start.getTime();
          if (t.end.getTime() > maxEnd) maxEnd = t.end.getTime();
          totalProgress += t.progress;
        }
        groupTask.start = new Date(minStart);
        groupTask.end = new Date(maxEnd);
        groupTask.progress = Math.round(totalProgress / groupTasks.length);
      }

      const hasChildren = groupTasks.length > 0;
      rows.push({
        task: groupTask,
        extraTasks: [],
        depth: 0,
        rowIndex: rowIndex++,
        hasChildren,
        isVisible: true,
        group,
        isGroupHeader: true,
      });

      if (group.expanded !== false) {
        // Flatten group tasks using tree logic
        const groupRows = this.flattenTree(groupTasks);
        for (const r of groupRows) {
          if (r.isVisible) {
            r.rowIndex = rowIndex++;
            r.depth += 1; // indent within group
          }
          rows.push(r);
        }
      }
    }

    // Also flatten any ungrouped tasks
    if (ungroupedTasks.length > 0) {
      const ungroupedRows = this.flattenTree(ungroupedTasks);
      for (const r of ungroupedRows) {
        if (r.isVisible) {
          r.rowIndex = rowIndex++;
        }
        rows.push(r);
      }
    }

    return rows;
  }
}

import { Injectable, ElementRef } from '@angular/core';

/**
 * Service for exporting the gantt chart as a PNG image.
 * Requires html2canvas as an optional peer dependency for full export.
 * Falls back to SVG serialization if html2canvas is not available.
 */
@Injectable()
export class GanttPrintService {
  private root: HTMLElement | null = null;

  register(rootRef: ElementRef<HTMLElement>): void {
    this.root = rootRef.nativeElement;
  }

  /**
   * Export the gantt chart as a PNG data URL.
   * Uses the Canvas API to capture the rendered content.
   */
  async exportAsImage(ignoreElementClass?: string): Promise<string | null> {
    if (!this.root) {
      console.warn('[GanttPrintService] No root element registered.');
      return null;
    }

    try {
      // Try to use html2canvas if available
      const html2canvas = await this.loadHtml2Canvas();
      if (html2canvas) {
        const canvas = await html2canvas(this.root, {
          logging: false,
          allowTaint: true,
          useCORS: true,
          width: this.root.scrollWidth,
          height: this.root.scrollHeight,
          ignoreElements: (element: Element) => {
            if (ignoreElementClass && element.classList.contains(ignoreElementClass)) {
              return true;
            }
            return false;
          },
        });
        return canvas.toDataURL('image/png');
      }

      // Fallback: capture via basic canvas rendering
      return this.fallbackCapture();
    } catch {
      console.warn('[GanttPrintService] Export failed.');
      return null;
    }
  }

  /**
   * Download the gantt chart as a PNG file.
   */
  async print(name: string = 'gantt-chart', ignoreElementClass?: string): Promise<void> {
    const dataUrl = await this.exportAsImage(ignoreElementClass);
    if (dataUrl) {
      const link = document.createElement('a');
      link.download = `${name}.png`;
      link.href = dataUrl;
      link.click();
    }
  }

  private async loadHtml2Canvas(): Promise<((el: HTMLElement, opts: unknown) => Promise<HTMLCanvasElement>) | null> {
    try {
      // html2canvas is an optional peer dependency – if not installed, fallback is used
      const module = await (Function('return import("html2canvas")')() as Promise<{ default: (el: HTMLElement, opts: unknown) => Promise<HTMLCanvasElement> }>);
      return module.default || null;
    } catch {
      return null;
    }
  }

  private fallbackCapture(): string | null {
    if (!this.root) return null;

    // Basic fallback: render a simple canvas with the gantt dimensions
    const canvas = document.createElement('canvas');
    const rect = this.root.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;
    const ctx = canvas.getContext('2d');
    if (!ctx) return null;

    // Fill with background
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw a message indicating html2canvas is needed for full export
    ctx.fillStyle = '#6c757d';
    ctx.font = '14px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(
      'Install html2canvas for full chart export (npm install html2canvas)',
      canvas.width / 2,
      canvas.height / 2,
    );

    return canvas.toDataURL('image/png');
  }
}

import { Injectable } from '@angular/core';
import { ZoomLevel } from '../models';
import {
  diffDays, diffHours, startOfDay, startOfHour, startOfWeek, startOfMonth,
  startOfQuarter, startOfYear, addDays, addHours, snapToDay, daysInMonth,
} from '../utils/date-utils';

@Injectable()
export class GanttScaleService {
  dateToX(date: Date, startDate: Date, columnWidth: number, zoomLevel: ZoomLevel): number {
    switch (zoomLevel) {
      case ZoomLevel.Hour: {
        const hours = diffHours(date, startOfHour(startDate));
        return hours * columnWidth;
      }
      case ZoomLevel.Day: {
        const hours = diffHours(date, startOfDay(startDate));
        return (hours / 24) * columnWidth;
      }
      case ZoomLevel.Week: {
        const totalDays = (date.getTime() - startOfWeek(startDate).getTime()) / 86400000;
        return (totalDays / 7) * columnWidth;
      }
      case ZoomLevel.Month: {
        const start = startOfMonth(startDate);
        const months =
          (date.getFullYear() - start.getFullYear()) * 12 +
          (date.getMonth() - start.getMonth());
        const monthStart = startOfMonth(date);
        const msInMonth = date.getTime() - monthStart.getTime();
        const dim = daysInMonth(date);
        const monthFraction = msInMonth / (dim * 86400000);
        return (months + monthFraction) * columnWidth;
      }
      case ZoomLevel.Quarter: {
        const start = startOfQuarter(startDate);
        const startQ = start.getFullYear() * 4 + Math.floor(start.getMonth() / 3);
        const dateQ = date.getFullYear() * 4 + Math.floor(date.getMonth() / 3);
        const qDiff = dateQ - startQ;
        // Fraction within the quarter
        const qStart = new Date(date.getFullYear(), Math.floor(date.getMonth() / 3) * 3, 1);
        const qEnd = new Date(date.getFullYear(), Math.floor(date.getMonth() / 3) * 3 + 3, 1);
        const qDays = (qEnd.getTime() - qStart.getTime()) / 86400000;
        const dayInQ = (date.getTime() - qStart.getTime()) / 86400000;
        return (qDiff + dayInQ / qDays) * columnWidth;
      }
      case ZoomLevel.Year: {
        const start = startOfYear(startDate);
        const yearDiff = date.getFullYear() - start.getFullYear();
        const yearStart = new Date(date.getFullYear(), 0, 1);
        const yearEnd = new Date(date.getFullYear() + 1, 0, 1);
        const yDays = (yearEnd.getTime() - yearStart.getTime()) / 86400000;
        const dayInY = (date.getTime() - yearStart.getTime()) / 86400000;
        return (yearDiff + dayInY / yDays) * columnWidth;
      }
    }
  }

  xToDate(x: number, startDate: Date, columnWidth: number, zoomLevel: ZoomLevel): Date {
    switch (zoomLevel) {
      case ZoomLevel.Hour: {
        const hours = x / columnWidth;
        return addHours(startOfHour(startDate), hours);
      }
      case ZoomLevel.Day: {
        const days = x / columnWidth;
        return new Date(startOfDay(startDate).getTime() + days * 86400000);
      }
      case ZoomLevel.Week: {
        const weeks = x / columnWidth;
        return new Date(startOfWeek(startDate).getTime() + weeks * 604800000);
      }
      case ZoomLevel.Month: {
        const months = x / columnWidth;
        const start = startOfMonth(startDate);
        const result = new Date(start);
        result.setMonth(result.getMonth() + Math.floor(months));
        const fraction = months - Math.floor(months);
        const dim = daysInMonth(result);
        return new Date(result.getTime() + fraction * dim * 86400000);
      }
      case ZoomLevel.Quarter: {
        const quarters = x / columnWidth;
        const start = startOfQuarter(startDate);
        const result = new Date(start);
        result.setMonth(result.getMonth() + Math.floor(quarters) * 3);
        const fraction = quarters - Math.floor(quarters);
        const qStart = new Date(result.getFullYear(), Math.floor(result.getMonth() / 3) * 3, 1);
        const qEnd = new Date(result.getFullYear(), Math.floor(result.getMonth() / 3) * 3 + 3, 1);
        const qDays = (qEnd.getTime() - qStart.getTime()) / 86400000;
        return new Date(qStart.getTime() + fraction * qDays * 86400000);
      }
      case ZoomLevel.Year: {
        const years = x / columnWidth;
        const start = startOfYear(startDate);
        const result = new Date(start);
        result.setFullYear(result.getFullYear() + Math.floor(years));
        const fraction = years - Math.floor(years);
        const yearStart = new Date(result.getFullYear(), 0, 1);
        const yearEnd = new Date(result.getFullYear() + 1, 0, 1);
        const yDays = (yearEnd.getTime() - yearStart.getTime()) / 86400000;
        return new Date(yearStart.getTime() + fraction * yDays * 86400000);
      }
    }
  }

  snapDate(date: Date, snapTo: 'none' | 'day' | 'hour'): Date {
    switch (snapTo) {
      case 'day':
        return snapToDay(date);
      case 'hour': {
        const result = new Date(date);
        if (result.getMinutes() >= 30) {
          result.setHours(result.getHours() + 1);
        }
        result.setMinutes(0, 0, 0);
        return result;
      }
      default:
        return date;
    }
  }

  getBarWidth(start: Date, end: Date, startDate: Date, columnWidth: number, zoomLevel: ZoomLevel): number {
    const x1 = this.dateToX(start, startDate, columnWidth, zoomLevel);
    const x2 = this.dateToX(end, startDate, columnWidth, zoomLevel);
    return Math.max(x2 - x1, 4);
  }
}

import { Injectable } from '@angular/core';
import { GridColumnDef } from './models';

/**
 * Standalone injectable service for exporting grid data to JSON, CSV, and Excel formats.
 * Extracted from DataGridComponent to enable reuse and reduce component size.
 */
@Injectable({ providedIn: 'root' })
export class GridExportService {

  /**
   * Export data as a JSON file download.
   */
  exportToJson<T>(data: T[], filename = 'grid-data.json'): void {
    const dataStr = 'data:text/json;charset=utf-8,' + encodeURIComponent(JSON.stringify(data, null, 2));
    this.triggerDownload(dataStr, filename);
  }

  /**
   * Export data as a CSV file download.
   */
  exportToCsv<T extends object>(data: T[], columns: GridColumnDef<T>[], filename = 'grid-data.csv'): void {
    if (data.length === 0) return;
    const headers = columns.map(c => c.title);
    const fields = columns.map(c => c.field);
    const rows = data.map(row => {
      const r = row as Record<string, unknown>;
      return fields.map(field => {
        const val = r[field] ?? '';
        const valStr = typeof val === 'object' ? JSON.stringify(val) : String(val);
        return `"${valStr.replace(/"/g, '""')}"`;
      });
    });
    const csvContent = [headers.join(','), ...rows.map(e => e.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    this.triggerDownload(url, filename);
  }

  /**
   * Export data as an Excel (.xls) file download using an HTML table template.
   */
  exportToExcel<T extends object>(data: T[], columns: GridColumnDef<T>[], filename = 'grid-data.xls'): void {
    if (data.length === 0) return;

    let tableHtml = '<table><thead><tr>';
    columns.forEach(c => {
      tableHtml += `<th>${c.title}</th>`;
    });
    tableHtml += '</tr></thead><tbody>';

    data.forEach(row => {
      const r = row as Record<string, unknown>;
      tableHtml += '<tr>';
      columns.forEach(c => {
        const val = r[c.field] ?? '';
        const valStr = typeof val === 'object' ? JSON.stringify(val) : String(val);
        const alignClass = c.align ? ` class="text-${c.align}"` : '';
        tableHtml += `<td${alignClass}>${valStr}</td>`;
      });
      tableHtml += '</tr>';
    });
    tableHtml += '</tbody></table>';

    const worksheetName = 'Grid Export';
    const template = `
      <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
      <head>
      <!--[if gte mso 9]>
      <xml>
       <x:ExcelWorkbook>
        <x:ExcelWorksheets>
         <x:ExcelWorksheet>
          <x:Name>${worksheetName}</x:Name>
          <x:WorksheetOptions>
           <x:DisplayGridlines/>
          </x:WorksheetOptions>
         </x:ExcelWorksheet>
        </x:ExcelWorksheets>
       </x:ExcelWorkbook>
      </xml>
      <![endif]-->
      <style>
        table { border-collapse: collapse; font-family: sans-serif; font-size: 11pt; }
        th { background-color: #f1f5f9; color: #1e293b; font-weight: bold; border: 1px solid #cbd5e1; padding: 6px; }
        td { border: 1px solid #cbd5e1; padding: 6px; }
        .text-right { text-align: right; }
        .text-center { text-align: center; }
        .text-left { text-align: left; }
      </style>
      </head>
      <body>
      ${tableHtml}
      </body>
      </html>
    `;

    const blob = new Blob([template], { type: 'application/vnd.ms-excel;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    this.triggerDownload(url, filename);
  }

  /**
   * Export data as a beautifully styled PDF format via browser print window.
   */
  exportToPdf<T extends object>(data: T[], columns: GridColumnDef<T>[], title = 'Data Grid Export'): void {
    if (data.length === 0 || typeof window === 'undefined' || typeof document === 'undefined') return;

    const printWindow = window.open('', '_blank');
    if (!printWindow) {
      alert('Pop-up blocker prevented printing. Please allow pop-ups for this site.');
      return;
    }

    let tableHtml = '<table><thead><tr>';
    columns.forEach(c => {
      tableHtml += `<th>${c.title}</th>`;
    });
    tableHtml += '</tr></thead><tbody>';

    data.forEach(row => {
      const r = row as Record<string, unknown>;
      tableHtml += '<tr>';
      columns.forEach(c => {
        const val = r[c.field] ?? '';
        const valStr = typeof val === 'object' ? JSON.stringify(val) : String(val);
        const alignClass = c.align ? ` class="text-${c.align}"` : '';
        tableHtml += `<td${alignClass}>${valStr}</td>`;
      });
      tableHtml += '</tr>';
    });
    tableHtml += '</tbody></table>';

    const printTemplate = `
      <html>
      <head>
        <title>${title}</title>
        <style>
          body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; padding: 24px; color: #0f172a; }
          .header { display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #e2e8f0; padding-bottom: 12px; margin-bottom: 24px; }
          .title { font-size: 20px; font-weight: bold; }
          .date { font-size: 12px; color: #64748b; }
          table { width: 100%; border-collapse: collapse; margin-top: 12px; font-size: 10pt; }
          th { background-color: #f8fafc; color: #1e293b; font-weight: bold; border: 1px solid #cbd5e1; padding: 10px 8px; text-align: left; }
          td { border: 1px solid #cbd5e1; padding: 8px; color: #334155; }
          .text-right { text-align: right; }
          .text-center { text-align: center; }
          .text-left { text-align: left; }
          @media print {
            body { padding: 0; }
            button { display: none; }
          }
        </style>
      </head>
      <body>
        <div class="header">
          <div class="title">${title}</div>
          <div class="date">${new Date().toLocaleString()}</div>
        </div>
        ${tableHtml}
        <script>
          window.onload = function() {
            window.print();
            setTimeout(function() { window.close(); }, 500);
          };
        </script>
      </body>
      </html>
    `;

    printWindow.document.write(printTemplate);
    printWindow.document.close();
  }

  /**
   * Create a temporary anchor element, trigger a download, and clean up.
   */
  private triggerDownload(href: string, filename: string): void {
    const downloadAnchor = document.createElement('a');
    downloadAnchor.setAttribute('href', href);
    downloadAnchor.setAttribute('download', filename);
    document.body.appendChild(downloadAnchor);
    downloadAnchor.click();
    downloadAnchor.remove();
  }
}

import { Injectable, signal, computed } from '@angular/core';

export interface WebLlmMessage {
  role: 'user' | 'assistant' | 'system';
  content: string;
}

@Injectable({
  providedIn: 'root'
})
export class NgxWebLlmService {
  private engine: any = null;

  status = signal<string>('idle');
  progress = signal<number>(0);
  isReady = signal<boolean>(false);
  error = signal<string | null>(null);

  isGpuSupported(): boolean {
    return typeof navigator !== 'undefined' && 'gpu' in navigator && !!(navigator as any).gpu;
  }

  async init(
    modelId: string = 'Qwen2.5-0.5B-Instruct',
    onProgress?: (val: number, msg: string) => void
  ): Promise<void> {
    if (this.isReady()) return;

    this.status.set('loading_scripts');
    this.error.set(null);

    // If GPU is not supported, simulate model loading (useful for testing or fallback dev setups)
    if (!this.isGpuSupported()) {
      console.warn('WebGPU is not supported in this browser environment. Simulating fallback WebLLM Engine.');
      await this.simulateLoading(onProgress);
      return;
    }

    try {
      // Dynamic import of web-llm from CDN. Using type casting to bypass TS compilation lookup checks
      const webLlmModule = await (Function('return import("https://cdn.jsdelivr.net/npm/@mlc-ai/web-llm@0.2.46/+esm")')() as Promise<any>);

      this.status.set('downloading_model');
      this.progress.set(0);

      const engine = await webLlmModule.CreateWebGPUEngine(
        modelId,
        {
          initProgressCallback: (report: any) => {
            const val = report.progress;
            this.progress.set(Math.round(val * 100));
            this.status.set(`loading_model: ${report.text}`);
            if (onProgress) {
              onProgress(val, report.text);
            }
          }
        }
      );

      this.engine = engine;
      this.isReady.set(true);
      this.status.set('ready');
    } catch (err: any) {
      const errMsg = err.message || String(err);
      this.status.set('error');
      this.error.set(errMsg);
      throw new Error(`WebLLM Initialization failed: ${errMsg}`);
    }
  }

  private async simulateLoading(onProgress?: (val: number, msg: string) => void): Promise<void> {
    const steps = [
      { progress: 0.1, text: 'Fetching model config...' },
      { progress: 0.3, text: 'Loading WebGPU device adapter...' },
      { progress: 0.6, text: 'Downloading model weights (simulated)...' },
      { progress: 0.9, text: 'Warming up runtime execution pipeline...' },
      { progress: 1.0, text: 'Finished warming up' }
    ];

    for (const step of steps) {
      await new Promise(resolve => setTimeout(resolve, 100));
      this.progress.set(Math.round(step.progress * 100));
      this.status.set(`loading_model: ${step.text}`);
      if (onProgress) {
        onProgress(step.progress, step.text);
      }
    }

    this.engine = {
      chat: {
        completions: {
          create: async (params: any) => {
            // Return an async iterable stream simulator
            const responseText = `[Simulated WebLLM response to: "${params.messages[params.messages.length - 1]?.content}"] This is a locally generated streaming response using simulated model weights, as WebGPU is not supported on this device.`;
            const tokens = responseText.split(' ');
            return (async function* () {
              for (const token of tokens) {
                await new Promise(resolve => setTimeout(resolve, 40));
                yield {
                  choices: [
                    {
                      delta: {
                        content: token + ' '
                      }
                    }
                  ]
                };
              }
            })();
          }
        }
      }
    };
    this.isReady.set(true);
    this.status.set('ready');
  }

  async generate(
    messages: WebLlmMessage[],
    onToken?: (text: string) => void,
    options?: { max_tokens?: number; temperature?: number }
  ): Promise<string> {
    if (!this.engine) {
      throw new Error('WebLLM Engine is not initialized. Call init() first.');
    }

    this.status.set('generating');
    try {
      let fullText = '';
      const reply = await this.engine.chat.completions.create({
        messages,
        stream: true,
        max_tokens: options?.max_tokens ?? 1024,
        temperature: options?.temperature ?? 0.7
      });

      for await (const chunk of reply) {
        const delta = chunk.choices[0]?.delta?.content || '';
        if (delta) {
          fullText += delta;
          if (onToken) {
            onToken(fullText);
          }
        }
      }
      this.status.set('ready');
      return fullText;
    } catch (err: any) {
      this.status.set('error');
      this.error.set(err.message || String(err));
      throw err;
    }
  }

  reset(): void {
    this.engine = null;
    this.isReady.set(false);
    this.status.set('idle');
    this.progress.set(0);
    this.error.set(null);
  }
}

import { Injectable, ApplicationRef, createComponent, EnvironmentInjector, Component, input, signal, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';

export type NotificationType = 'success' | 'error' | 'info' | 'warning';
export type NotificationPosition = 'top-right' | 'top-left' | 'top-center' | 'bottom-right' | 'bottom-left' | 'bottom-center';

export interface NotificationOptions {
  message: string;
  type?: NotificationType;
  title?: string;
  duration?: number;
  closable?: boolean;
  position?: NotificationPosition;
}

export interface NotificationItem extends Required<NotificationOptions> {
  id: number;
  visible: boolean;
}

let nextId = 0;

@Component({
  selector: 'ngx-notification-container',
  standalone: true,
  imports: [CommonModule],
  host: {
    'role': 'log',
    'aria-live': 'polite',
    'aria-relevant': 'additions',
  },
  template: `
    @for (n of items(); track n.id) {
      <div class="notification" [class]="'notif-' + n.type" [class.visible]="n.visible" [attr.role]="n.type === 'error' ? 'alert' : 'status'">
        <span class="notif-icon">{{ icons[n.type] }}</span>
        <div class="notif-body">
          @if (n.title) { <div class="notif-title">{{ n.title }}</div> }
          <div class="notif-msg">{{ n.message }}</div>
        </div>
        @if (n.closable) {
          <button class="notif-close" (click)="remove(n.id)" aria-label="Close">×</button>
        }
      </div>
    }
  `,
  styles: [`
    :host { position: fixed; z-index: 10000; display: flex; flex-direction: column; gap: 10px; padding: 16px; pointer-events: none; }
    .notification {
      display: flex; align-items: flex-start; gap: 10px; min-width: 280px; max-width: 380px;
      padding: 12px 14px; border-radius: var(--ngx-notif-radius, 8px); box-shadow: 0 4px 20px rgba(0,0,0,0.15);
      pointer-events: all; font-family: inherit; font-size: 13px; opacity: 0; transform: translateX(20px);
      transition: opacity 0.25s, transform 0.25s; border-left: 4px solid transparent;
      background: var(--ngx-notif-bg, #fff); color: var(--ngx-notif-text, #212529);
    }
    .notification.visible { opacity: 1; transform: translateX(0); }
    .notif-success { border-left-color: #27ae60; }
    .notif-error { border-left-color: #e74c3c; }
    .notif-info { border-left-color: #1a73e8; }
    .notif-warning { border-left-color: #f39c12; }
    .notif-icon { font-size: 18px; flex-shrink: 0; }
    .notif-body { flex: 1; }
    .notif-title { font-weight: 700; margin-bottom: 3px; font-size: 13px; }
    .notif-msg { color: var(--ngx-color-text-secondary, #595f66); font-size: 12px; }
    .notif-close { background: none; border: none; font-size: 18px; cursor: pointer; color: var(--ngx-color-text-disabled, #767b83); padding: 0; line-height: 1; margin-left: 4px; }
    .notif-close:hover { color: #495057; }
  `]
})
export class NotificationContainerComponent implements OnInit {
  items = signal<NotificationItem[]>([]);
  icons: Record<NotificationType, string> = { success: '✅', error: '❌', info: 'ℹ️', warning: '⚠️' };

  ngOnInit() {}

  add(opts: NotificationOptions): number {
    const id = ++nextId;
    const item: NotificationItem = {
      id, visible: false,
      message: opts.message,
      type: opts.type ?? 'info',
      title: opts.title ?? '',
      duration: opts.duration ?? 4000,
      closable: opts.closable ?? true,
      position: opts.position ?? 'top-right'
    };
    this.items.update(arr => [...arr, item]);
    setTimeout(() => this.items.update(arr => arr.map(n => n.id === id ? { ...n, visible: true } : n)), 10);
    if (item.duration > 0) { setTimeout(() => this.remove(id), item.duration); }
    return id;
  }

  remove(id: number): void {
    this.items.update(arr => arr.map(n => n.id === id ? { ...n, visible: false } : n));
    setTimeout(() => this.items.update(arr => arr.filter(n => n.id !== id)), 300);
  }
}

const POSITIONS: Record<NotificationPosition, string> = {
  'top-right': 'top:0;right:0',
  'top-left': 'top:0;left:0',
  'top-center': 'top:0;left:50%;transform:translateX(-50%)',
  'bottom-right': 'bottom:0;right:0',
  'bottom-left': 'bottom:0;left:0',
  'bottom-center': 'bottom:0;left:50%;transform:translateX(-50%)'
};

@Injectable({ providedIn: 'root' })
export class NotificationService {
  private containers = new Map<NotificationPosition, NotificationContainerComponent>();

  constructor(private appRef: ApplicationRef, private injector: EnvironmentInjector) {}

  private getContainer(pos: NotificationPosition): NotificationContainerComponent {
    if (this.containers.has(pos)) return this.containers.get(pos)!;
    const ref = createComponent(NotificationContainerComponent, { environmentInjector: this.injector });
    const el: HTMLElement = ref.location.nativeElement;
    el.setAttribute('style', POSITIONS[pos]);
    document.body.appendChild(el);
    this.appRef.attachView(ref.hostView);
    this.containers.set(pos, ref.instance);
    return ref.instance;
  }

  show(opts: NotificationOptions): number {
    const pos = opts.position ?? 'top-right';
    return this.getContainer(pos).add(opts);
  }

  success(message: string, title?: string, opts?: Partial<NotificationOptions>): number {
    return this.show({ ...opts, message, title, type: 'success' });
  }
  error(message: string, title?: string, opts?: Partial<NotificationOptions>): number {
    return this.show({ ...opts, message, title, type: 'error' });
  }
  info(message: string, title?: string, opts?: Partial<NotificationOptions>): number {
    return this.show({ ...opts, message, title, type: 'info' });
  }
  warning(message: string, title?: string, opts?: Partial<NotificationOptions>): number {
    return this.show({ ...opts, message, title, type: 'warning' });
  }
}

