                            editing: isEditing(row),
                            expanded: isExpanded(row)
                          }" />
                        </td>
                      } @else {
                        @for (col of orderedColumns(); track col.field) {
                          @if (getCellRowSpan(row, col.field, i, group.items) > 0) {
                            <td
                              class="grid-td"
