                                @if (resolveEditCellTemplate(col); as activeEditTemplate) {
                                  <ng-container *ngTemplateOutlet="activeEditTemplate; context: {
                                    $implicit: getDraftValue(row, col.field),
                                    value: getCellValue(row, col.field),
