                    [class.pinned-left-last]="cell.isPinnedLast"
                    [class.pinned-right]="cell.column.pinned === 'right'"
                    [class.pinned-right-first]="cell.isPinnedFirst"
                    [style.left.px]="cell.column.pinned === 'left' ? cell.leftOffset : null"
