    }
    .action-btn:last-child { margin-right: 0; }
    .grid-loading-cell, .grid-empty-cell {
      padding: 48px;
      text-align: center;
      color: var(--ngx-grid-text-secondary, #64748b);
      font-weight: 500;
    }
    .grid-spinner {
      width: 28px;
      height: 28px;
