      margin-left: 2px;
      font-weight: 700;
    }
    
    /* Global Search Styles */
    .grid-search-wrap {
      position: relative;
      display: inline-flex;
      align-items: center;
    }
    .grid-search-input {
      padding: 6px 30px 6px 12px;
      border: 1px solid var(--ngx-grid-border, #cbd5e1);
