  `,
  styles: [`
    :host {
      display: block;
      height: 100%;
      font-family: var(--ngx-font-family, system-ui, -apple-system, sans-serif);
    }

    .ngx-ai-chat-container {
      display: flex;
      flex-direction: column;
      height: 100%;
      background: var(--ngx-ai-chat-bg, #ffffff);
      border: 1px solid var(--ngx-ai-chat-border, #e2e8f0);
