      box-shadow: 0 4px 20px rgba(0, 0, 0, 0.05);
      transition: all 0.3s ease;
    }

    .ngx-ai-chat-container.dark-mode {
      --ngx-ai-chat-bg: #1e293b;
      --ngx-ai-chat-border: #334155;
      --ngx-ai-header-bg: #0f172a;
      --ngx-ai-header-text: #f8fafc;
      --ngx-ai-bubble-user-bg: #3b82f6;
      --ngx-ai-bubble-user-text: #ffffff;
      --ngx-ai-bubble-assistant-bg: #334155;
      --ngx-ai-bubble-assistant-text: #f8fafc;
      --ngx-ai-input-bg: #0f172a;
      --ngx-ai-input-text: #f8fafc;
      --ngx-ai-input-border: #334155;
    }

    /* Header */
    .ngx-ai-chat-header {
      display: flex;
      align-items: center;
      padding: 14px 18px;
      background: var(--ngx-ai-header-bg, #f8fafc);
      border-bottom: 1px solid var(--ngx-ai-chat-border, #e2e8f0);
      gap: 12px;
    }

    .header-avatar {
      position: relative;
      width: 40px;
      height: 40px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 700;
      color: #fff;
      font-size: 14px;
    }

    .header-avatar img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      border-radius: 50%;
    }

    .status-indicator {
      position: absolute;
      bottom: 0;
      right: 0;
      width: 10px;
      height: 10px;
      border-radius: 50%;
      background: #94a3b8;
      border: 2px solid var(--ngx-ai-chat-bg, #fff);
    }

    .status-indicator.online {
      background: #10b981;
    }

    .header-info {
      flex: 1;
    }

    .agent-title {
      font-weight: 600;
      font-size: 15px;
      color: var(--ngx-ai-header-text, #1e293b);
    }

    .agent-status {
      font-size: 12px;
      color: #64748b;
    }

    .header-actions {
      display: flex;
      gap: 8px;
    }

    .header-btn {
      background: none;
      border: none;
      padding: 8px;
      border-radius: 50%;
      cursor: pointer;
      color: #64748b;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background-color 0.2s;
    }

    .header-btn:hover {
      background-color: rgba(100, 116, 139, 0.1);
    }

    .svg-icon {
      width: 20px;
      height: 20px;
      fill: currentColor;
    }

    /* Chat Body */
    .ngx-ai-chat-body {
      flex: 1;
      overflow-y: auto;
      padding: 16px 20px;
      display: flex;
      flex-direction: column;
    }

    .messages-list {
