      background: rgba(255, 255, 255, 0.05);
    }

    .steps-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 8px 12px;
      background: rgba(148, 163, 184, 0.1);
      border-bottom: 1px solid rgba(148, 163, 184, 0.1);
    }

    .steps-title-text {
      font-size: 12px;
      font-weight: 600;
      opacity: 0.8;
    }

    .steps-badge {
      font-size: 10px;
      font-weight: 700;
      background: rgba(148, 163, 184, 0.2);
      padding: 2px 6px;
      border-radius: 10px;
    }

    .steps-list {
      display: flex;
      flex-direction: column;
    }

    .agent-step-item {
      border-bottom: 1px solid rgba(148, 163, 184, 0.08);
    }

    .agent-step-item:last-child {
      border-bottom: none;
    }

    .step-summary {
      display: flex;
      align-items: center;
      padding: 8px 12px;
      cursor: pointer;
      font-size: 12px;
      gap: 8px;
      transition: background-color 0.2s;
    }

    .step-summary:hover {
      background: rgba(148, 163, 184, 0.05);
    }

    .step-status-icon {
      width: 16px;
      height: 16px;
      border-radius: 50%;
      display: flex;
