      justify-content: center;
      font-size: 10px;
      font-weight: bold;
      color: #fff;
    }

    .step-status-icon.success {
      background: #10b981;
    }

    .step-status-icon.error {
      background: #ef4444;
    }

    .step-status-icon.running {
      background: #3b82f6;
    }

    .step-name {
