    }

    .card-title {
      font-size: 14px;
      font-weight: 600;
      margin: 0 0 2px;
    }

    .card-subtitle {
      font-size: 12px;
      font-weight: 500;
      color: #64748b;
      margin: 0 0 6px;
    }

    .card-description {
      font-size: 12px;
      color: #64748b;
      line-height: 1.4;
