    .ngx-ai-chat-footer {
      padding: 14px 18px;
      background: var(--ngx-ai-header-bg, #f8fafc);
      border-top: 1px solid var(--ngx-ai-chat-border, #e2e8f0);
    }

    .input-form {
      display: flex;
      gap: 10px;
    }

    .chat-input {
      flex: 1;
      padding: 10px 14px;
      border-radius: 8px;
      border: 1px solid var(--ngx-ai-input-border, #cbd5e1);
      background: var(--ngx-ai-input-bg, #fff);
      color: var(--ngx-ai-input-text, #1e293b);
      font-size: 14px;
      outline: none;
      transition: border-color 0.2s;
    }

    .chat-input:focus {
      border-color: var(--ngx-ai-bubble-user-bg, #1a73e8);
    }

    .send-btn {
      width: 38px;
      height: 38px;
      border-radius: 8px;
      background: var(--ngx-ai-bubble-user-bg, #1a73e8);
      color: #fff;
      border: none;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background-color 0.2s, transform 0.1s;
    }

    .send-btn:hover:not(:disabled) {
      background-color: #1557b0;
      transform: translateY(-1px);
    }

    .send-btn:disabled {
      background-color: #94a3b8;
      cursor: not-allowed;
    }

    /* Attachment Previews in Input Area */
    .attachments-preview-bar {
      display: flex;
      gap: 8px;
      padding: 8px;
      overflow-x: auto;
      border-bottom: 1px solid var(--ngx-ai-chat-border, #e2e8f0);
      background: var(--ngx-ai-chat-bg, #ffffff);
    }
    .attachment-preview-tag {
      display: flex;
      align-items: center;
      gap: 6px;
      padding: 4px 8px;
      background: #f1f5f9;
      border: 1px solid #cbd5e1;
      border-radius: 6px;
      font-size: 11px;
      max-width: 150px;
    }
    .attachment-thumb {
      width: 18px;
      height: 18px;
      object-fit: cover;
      border-radius: 2px;
    }
    .attachment-icon {
      font-size: 12px;
    }
    .attachment-name {
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
      flex: 1;
      color: #334155;
    }
    .remove-attachment-btn {
      background: none;
      border: none;
      color: #94a3b8;
      cursor: pointer;
      padding: 0 2px;
      font-size: 10px;
    }
    .remove-attachment-btn:hover {
      color: #ef4444;
    }

    /* Attachments inside bubble */
    .message-attachments-list {
      display: flex;
      flex-direction: column;
      gap: 6px;
      margin-top: 8px;
    }
    .msg-attachment-item {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 6px 10px;
      background: rgba(255,255,255,0.7);
      border: 1px solid rgba(0,0,0,0.06);
      border-radius: 8px;
      text-decoration: none;
      color: inherit;
      max-width: 250px;
      font-size: 12px;
      transition: background 0.2s;
    }
    .msg-attachment-item:hover {
      background: rgba(255,255,255,0.9);
    }
    .msg-attachment-img-preview {
      width: 32px;
      height: 32px;
      overflow: hidden;
      border-radius: 4px;
    }
    .msg-attachment-img-preview img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }
    .msg-attachment-icon {
      font-size: 16px;
    }
    .msg-attachment-name {
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
      font-weight: 500;
    }

    /* Attach button */
    .attach-btn {
      background: none;
      border: none;
      color: #64748b;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 8px;
      border-radius: 8px;
      transition: background 0.2s;
    }
    .attach-btn:hover:not(:disabled) {
      background: rgba(100, 116, 139, 0.1);
      color: #334155;
    }
    .attach-btn:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }

    /* Meta Row / Feedback Row styling */
    .msg-meta-row {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-top: 4px;
      min-width: 80px;
    }
    .feedback-actions {
      display: flex;
      gap: 4px;
      opacity: 0.3;
      transition: opacity 0.2s;
    }
    .message-wrapper:hover .feedback-actions {
      opacity: 1;
    }
    .feedback-tiny-btn {
      background: transparent;
      border: none;
      cursor: pointer;
      font-size: 10px;
      padding: 2px;
      border-radius: 4px;
      transition: background 0.2s;
    }
    .feedback-tiny-btn:hover {
      background: rgba(0,0,0,0.08);
    }
    .feedback-tiny-btn.selected {
      background: rgba(0,0,0,0.12);
      transform: scale(1.1);
    }

    /* Dark Mode specific overrides */
    .dark-mode .attachments-preview-bar {
      border-bottom-color: var(--ngx-ai-chat-border, #334155);
      background: var(--ngx-ai-chat-bg, #1e293b);
    }
    .dark-mode .attachment-preview-tag {
      background: #334155;
      border-color: #475569;
    }
    .dark-mode .attachment-name {
      color: #f8fafc;
    }
    .dark-mode .msg-attachment-item {
      background: rgba(15, 23, 42, 0.4);
      border-color: rgba(255,255,255,0.06);
    }
    .dark-mode .msg-attachment-item:hover {
      background: rgba(15, 23, 42, 0.6);
    }
    .dark-mode .attach-btn {
      color: #94a3b8;
    }
    .dark-mode .attach-btn:hover:not(:disabled) {
      background: rgba(255, 255, 255, 0.05);
      color: #f8fafc;
    }
    .dark-mode .feedback-tiny-btn:hover {
      background: rgba(255,255,255,0.08);
    }
    .dark-mode .feedback-tiny-btn.selected {
      background: rgba(255,255,255,0.15);
    }
  `]
})
export class AIChatComponent {
  private sanitizer = inject(DomSanitizer);
  messages = input<AIMessage[]>([]);
  agentName = input('AI Agent');
  agentAvatarUrl = input('');
  isOnline = input(true);
  isTyping = input(false);
  isStreaming = input(false);
  showSenderNames = input(false);
  theme = input<'light' | 'dark'>('light');
  placeholder = input('Type a message...');
  disabled = input(false);
  quickReplies = input<QuickReply[]>([]);
  avatarBg = input('#4f46e5');

  sendMessage = output<string>();
  quickReplyClick = output<QuickReply>();
  cardActionClick = output<AICardAction>();
  clearHistory = output<void>();
  messageFeedback = output<{ messageId: string; rating: 'like' | 'dislike' }>();
  fileAttached = output<{ name: string; type: string; size: number; file: File }>();
  messageSent = output<{ content: string; attachments: { name: string; url: string; type: string; size?: number }[] }>();

  chatBody = viewChild<ElementRef>('chatBody');

  inputText = '';
  attachedFiles = signal<{ name: string; type: string; size: number; url: string; rawFile: File }[]>([]);
  msgFeedbackMap: Record<string, 'like' | 'dislike'> = {};

  @HostListener('click', ['$event'])
  onHostClick(event: MouseEvent) {
    const target = event.target as HTMLElement;
    if (target && target.classList.contains('copy-code-btn')) {
      const codeText = target.getAttribute('data-code');
      if (codeText) {
        navigator.clipboard.writeText(decodeURIComponent(codeText)).then(() => {
          target.innerText = 'Copied!';
          setTimeout(() => { target.innerText = 'Copy'; }, 2000);
        });
      }
    }
  }

  onFileSelected(event: Event) {
    const inputEl = event.target as HTMLInputElement;
    if (inputEl && inputEl.files) {
      const filesArray = Array.from(inputEl.files);
      filesArray.forEach(file => {
        const fileUrl = URL.createObjectURL(file);
        const attachment = {
          name: file.name,
          type: file.type,
          size: file.size,
          url: fileUrl,
          rawFile: file
        };
        this.attachedFiles.update(current => [...current, attachment]);
        this.fileAttached.emit({
          name: file.name,
          type: file.type,
          size: file.size,
          file: file
        });
      });
      // Reset input value to allow selecting same file again
      inputEl.value = '';
    }
  }

  removeAttachment(file: any) {
    URL.revokeObjectURL(file.url);
    this.attachedFiles.update(current => current.filter(f => f.url !== file.url));
  }

  onMessageRating(messageId: string, rating: 'like' | 'dislike') {
    if (this.msgFeedbackMap[messageId] === rating) {
      delete this.msgFeedbackMap[messageId];
    } else {
      this.msgFeedbackMap[messageId] = rating;
    }
    this.messageFeedback.emit({ messageId, rating });
  }

  constructor() {
    // Automatically scroll to bottom when messages or typing status changes
    effect(() => {
      this.messages();
      this.isTyping();
      this.scrollToBottom();
    });
  }

  onSubmit(): void {
    const text = this.inputText.trim();
    if (!text && this.attachedFiles().length === 0) return;
    if (this.disabled()) return;
    
    const attachmentsData = this.attachedFiles().map(f => ({
      name: f.name,
      url: f.url,
      type: f.type,
      size: f.size
    }));
    
    this.sendMessage.emit(text);
    this.messageSent.emit({ content: text, attachments: attachmentsData });
    
    this.attachedFiles.set([]);
    this.inputText = '';
  }

  toggleStep(step: AgentStep): void {
    step.collapsed = !step.collapsed;
  }

  getCompletedStepsCount(steps: AgentStep[]): number {
    return steps.filter(s => s.status === 'success' || s.status === 'error').length;
  }

  getInitials(name: string): string {
    if (!name) return 'AI';
    const parts = name.split(' ');
    if (parts.length >= 2) {
      return (parts[0][0] + parts[1][0]).toUpperCase();
    }
    return name.slice(0, 2).toUpperCase();
  }

  scrollToBottom(): void {
    setTimeout(() => {
      const el = this.chatBody()?.nativeElement;
      if (el) {
        el.scrollTop = el.scrollHeight;
      }
    }, 100);
  }

  formatMessage(content: string): SafeHtml {
    if (!content) return '';
    // Very basic escaping and formatting to keep it lightweight.
    // In actual project, a custom template or markdown pipe can be used.
    let formatted = content
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');

    // Handle unclosed triple backticks (code blocks) during streaming
    const codeBlockCount = (formatted.match(/```/g) || []).length;
    if (codeBlockCount % 2 !== 0) {
      formatted += '\n```';
    }

    // Handle unclosed bold markers during streaming
    const boldCount = (formatted.match(/\*\*/g) || []).length;
    if (boldCount % 2 !== 0) {
      formatted += '**';
    }

    // Handle unclosed inline code backticks during streaming
    const inlineCodeCount = (formatted.match(/`/g) || []).length;
    if (inlineCodeCount % 2 !== 0) {
      formatted += '`';
    }

    // Bold markdown helper
    formatted = formatted.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

    // Code blocks helper
    formatted = formatted.replace(/```(\w*)\n([\s\S]*?)```/g, (_, lang, code) => {
      const language = lang || 'code';
      const cleanCode = code.trim();
      const encoded = encodeURIComponent(cleanCode);
      return `
        <div class="code-container" style="background: rgba(0,0,0,0.05); padding: 8px 12px; border-radius: 6px; font-family: monospace; font-size: 12px; margin: 8px 0; border-left: 3px solid #3b82f6; overflow-x: auto; position: relative;">
          <div style="display: flex; justify-content: space-between; align-items: center; font-size: 10px; font-weight: bold; opacity: 0.6; margin-bottom: 4px; text-transform: uppercase;">
            <span>${language}</span>
            <button class="copy-code-btn" data-code="${encoded}" style="background: transparent; border: 1px solid rgba(0,0,0,0.15); padding: 2px 6px; border-radius: 4px; cursor: pointer; font-size: 9px; font-family: sans-serif; transition: all 0.2s;">Copy</button>
          </div>
          <pre style="margin: 0; white-space: pre-wrap;"><code>${cleanCode}</code></pre>
        </div>
      `;
    });

    // Inline code helper
    formatted = formatted.replace(/`(.*?)`/g, '<code style="background: rgba(0,0,0,0.06); padding: 2px 4px; border-radius: 4px; font-family: monospace; font-size: 12px;">$1</code>');

    return this.sanitizer.bypassSecurityTrustHtml(formatted);
  }
}

components.stylesData:
:host {
  display: block;
  height: 100%;
  font-family: var(--ngx-font-family, system-ui, -apple-system, sans-serif);
}

.ngx-ai-chat-container {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: var(--ngx-ai-chat-bg, #ffffff);
  border: 1px solid var(--ngx-ai-chat-border, #e2e8f0);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.05);
  transition: all 0.3s ease;
}

.ngx-ai-chat-container.dark-mode {
  --ngx-ai-chat-bg: #1e293b;
  --ngx-ai-chat-border: #334155;
  --ngx-ai-header-bg: #0f172a;
  --ngx-ai-header-text: #f8fafc;
  --ngx-ai-bubble-user-bg: #3b82f6;
  --ngx-ai-bubble-user-text: #ffffff;
  --ngx-ai-bubble-assistant-bg: #334155;
  --ngx-ai-bubble-assistant-text: #f8fafc;
  --ngx-ai-input-bg: #0f172a;
  --ngx-ai-input-text: #f8fafc;
  --ngx-ai-input-border: #334155;
}

/* Header */
.ngx-ai-chat-header {
  display: flex;
  align-items: center;
  padding: 14px 18px;
  background: var(--ngx-ai-header-bg, #f8fafc);
  border-bottom: 1px solid var(--ngx-ai-chat-border, #e2e8f0);
  gap: 12px;
}

.header-avatar {
  position: relative;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  color: #fff;
  font-size: 14px;
}

.header-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 50%;
}

.status-indicator {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #94a3b8;
  border: 2px solid var(--ngx-ai-chat-bg, #fff);
}

.status-indicator.online {
  background: #10b981;
}

.header-info {
  flex: 1;
}

.agent-title {
  font-weight: 600;
  font-size: 15px;
  color: var(--ngx-ai-header-text, #1e293b);
}

.agent-status {
  font-size: 12px;
  color: #64748b;
}

.header-actions {
  display: flex;
  gap: 8px;
}

.header-btn {
  background: none;
  border: none;
  padding: 8px;
  border-radius: 50%;
  cursor: pointer;
  color: #64748b;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background-color 0.2s;
}

.header-btn:hover {
  background-color: rgba(100, 116, 139, 0.1);
}

.svg-icon {
  width: 20px;
  height: 20px;
  fill: currentColor;
}

/* Chat Body */
.ngx-ai-chat-body {
  flex: 1;
  overflow-y: auto;
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
}

.messages-list {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.message-wrapper {
  display: flex;
  gap: 12px;
  max-width: 85%;
}

.message-wrapper.user-msg {
  align-self: flex-end;
  flex-direction: row-reverse;
  max-width: 75%;
}

.message-wrapper.assistant-msg {
  align-self: flex-start;
}

.msg-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-weight: 600;
  font-size: 12px;
  flex-shrink: 0;
}

.msg-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 50%;
}

.msg-bubble-container {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.user-msg .msg-bubble-container {
  align-items: flex-end;
}

.msg-sender {
  font-size: 11px;
  font-weight: 600;
  color: #64748b;
  margin-left: 4px;
}

.msg-bubble {
  padding: 12px 16px;
  border-radius: 16px;
  font-size: 14px;
  line-height: 1.5;
  word-break: break-word;
}

.user-msg .msg-bubble {
  background: var(--ngx-ai-bubble-user-bg, #1a73e8);
  color: var(--ngx-ai-bubble-user-text, #ffffff);
  border-bottom-right-radius: 4px;
}

.assistant-msg .msg-bubble {
  background: var(--ngx-ai-bubble-assistant-bg, #f1f5f9);
  color: var(--ngx-ai-bubble-assistant-text, #1e293b);
  border-bottom-left-radius: 4px;
}

.msg-text {
  white-space: pre-wrap;
}

.msg-time {
  font-size: 10px;
  color: #94a3b8;
  margin: 0 4px;
}

/* Agent Steps Accordion */
.agent-steps-container {
  margin-top: 10px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 8px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.05);
}

.steps-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 12px;
  background: rgba(148, 163, 184, 0.1);
  border-bottom: 1px solid rgba(148, 163, 184, 0.1);
}

.steps-title-text {
  font-size: 12px;
  font-weight: 600;
  opacity: 0.8;
}

.steps-badge {
  font-size: 10px;
  font-weight: 700;
  background: rgba(148, 163, 184, 0.2);
  padding: 2px 6px;
  border-radius: 10px;
}

.steps-list {
  display: flex;
  flex-direction: column;
}

.agent-step-item {
  border-bottom: 1px solid rgba(148, 163, 184, 0.08);
}

.agent-step-item:last-child {
  border-bottom: none;
}

.step-summary {
  display: flex;
  align-items: center;
  padding: 8px 12px;
  cursor: pointer;
  font-size: 12px;
  gap: 8px;
  transition: background-color 0.2s;
}

.step-summary:hover {
  background: rgba(148, 163, 184, 0.05);
}

.step-status-icon {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  font-weight: bold;
  color: #fff;
}

.step-status-icon.success {
  background: #10b981;
}

.step-status-icon.error {
  background: #ef4444;
}

.step-status-icon.running {
  background: #3b82f6;
}

.step-name {
  flex: 1;
  font-weight: 500;
}

.step-duration {
  font-size: 10px;
  opacity: 0.6;
}

.step-chevron {
  font-size: 8px;
  transition: transform 0.2s;
  opacity: 0.5;
}

.step-chevron.expanded {
  transform: rotate(180deg);
}

.step-details {
  padding: 8px 12px;
  background: rgba(0, 0, 0, 0.02);
  display: flex;
  flex-direction: column;
  gap: 8px;
  border-top: 1px solid rgba(148, 163, 184, 0.05);
}

.step-detail-section {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.detail-label {
  font-size: 10px;
  font-weight: 600;
  opacity: 0.6;
  text-transform: uppercase;
  letter-spacing: 0.3px;
}

.detail-code {
  margin: 0;
  padding: 6px 10px;
  background: rgba(0, 0, 0, 0.05);
  border-radius: 4px;
  font-family: monospace;
  font-size: 11px;
  overflow-x: auto;
  white-space: pre-wrap;
  max-height: 120px;
}

/* Structured Response Carousel Cards */
.cards-carousel {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  padding: 10px 4px 6px;
  margin-top: 8px;
  scroll-snap-type: x mandatory;
  scrollbar-width: thin;
}

.cards-carousel::-webkit-scrollbar {
  height: 6px;
}
.cards-carousel::-webkit-scrollbar-thumb {
  background: rgba(148, 163, 184, 0.3);
  border-radius: 3px;
}

.ai-carousel-card {
  flex: 0 0 240px;
  background: var(--ngx-ai-chat-bg, #fff);
  border: 1px solid var(--ngx-ai-chat-border, #e2e8f0);
  border-radius: 12px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  scroll-snap-align: start;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}

.card-img-container {
  height: 120px;
  overflow: hidden;
}

.card-img-container img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.card-body {
  padding: 12px;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.card-title {
  font-size: 14px;
  font-weight: 600;
  margin: 0 0 2px;
}

.card-subtitle {
  font-size: 12px;
  font-weight: 500;
  color: #64748b;
  margin: 0 0 6px;
}

.card-description {
  font-size: 12px;
  color: #64748b;
  line-height: 1.4;
  margin: 0 0 12px;
  flex: 1;
}

.card-actions {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.card-action-btn {
  width: 100%;
  padding: 6px 12px;
  font-size: 12px;
  font-weight: 600;
  border-radius: 6px;
  border: 1px solid var(--ngx-ai-chat-border, #e2e8f0);
  background: none;
  cursor: pointer;
  transition: all 0.2s;
}

.card-action-btn.btn-primary {
  background: var(--ngx-ai-bubble-user-bg, #1a73e8);
  color: #fff;
  border-color: transparent;
}

.card-action-btn:hover {
  opacity: 0.9;
  transform: translateY(-1px);
}

/* Typing Indicator Bubble */
.typing-bubble {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 12px 20px;
}

.typing-indicator {
  display: flex;
  gap: 4px;
}

.typing-indicator span {
  width: 8px;
  height: 8px;
  background: #94a3b8;
  border-radius: 50%;
  animation: typing 1.4s infinite ease-in-out both;
}

.typing-indicator span:nth-child(1) { animation-delay: -0.32s; }
.typing-indicator span:nth-child(2) { animation-delay: -0.16s; }

@keyframes typing {
  0%, 80%, 100% { transform: scale(0); }
  40% { transform: scale(1.0); }
}

.streaming-cursor {
  display: inline-block;
  width: 6px;
  height: 14px;
  background-color: var(--ngx-ai-chat-primary, #3b82f6);
  margin-left: 4px;
  animation: blink-cursor 1s step-end infinite;
  vertical-align: middle;
}

@keyframes blink-cursor {
  from, to { background-color: transparent }
  50% { background-color: var(--ngx-ai-chat-primary, #3b82f6) }
}

/* Spinner */
.spinner {
  width: 10px;
  height: 10px;
  border: 2px solid rgba(255, 255, 255, 0.3);
  border-radius: 50%;
  border-top-color: #fff;
  animation: spin 1s ease-in-out infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* Quick Replies */
.quick-replies-container {
  padding: 10px 16px 4px;
  background: transparent;
}

.quick-replies-list {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 6px;
  scrollbar-width: none;
}

.quick-replies-list::-webkit-scrollbar {
  display: none;
}

.quick-reply-btn {
  flex: 0 0 auto;
  padding: 6px 14px;
  border-radius: 18px;
  border: 1px solid var(--ngx-ai-chat-border, #e2e8f0);
  background: var(--ngx-ai-chat-bg, #fff);
  font-size: 13px;
  font-weight: 500;
  color: #64748b;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: all 0.2s;
}

.quick-reply-btn:hover {
  border-color: var(--ngx-ai-bubble-user-bg, #1a73e8);
  color: var(--ngx-ai-bubble-user-bg, #1a73e8);
  background-color: rgba(26, 115, 232, 0.04);
}

/* Chat Footer */
.ngx-ai-chat-footer {
  padding: 14px 18px;
  background: var(--ngx-ai-header-bg, #f8fafc);
  border-top: 1px solid var(--ngx-ai-chat-border, #e2e8f0);
}

.input-form {
  display: flex;
  gap: 10px;
}

.chat-input {
  flex: 1;
  padding: 10px 14px;
  border-radius: 8px;
  border: 1px solid var(--ngx-ai-input-border, #cbd5e1);
  background: var(--ngx-ai-input-bg, #fff);
  color: var(--ngx-ai-input-text, #1e293b);
  font-size: 14px;
  outline: none;
  transition: border-color 0.2s;
}

.chat-input:focus {
  border-color: var(--ngx-ai-bubble-user-bg, #1a73e8);
}

.send-btn {
  width: 38px;
  height: 38px;
  border-radius: 8px;
  background: var(--ngx-ai-bubble-user-bg, #1a73e8);
  color: #fff;
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background-color 0.2s, transform 0.1s;
}

.send-btn:hover:not(:disabled) {
  background-color: #1557b0;
  transform: translateY(-1px);
}

.send-btn:disabled {
  background-color: #94a3b8;
  cursor: not-allowed;
}

/* Attachment Previews in Input Area */
.attachments-preview-bar {
  display: flex;
  gap: 8px;
  padding: 8px;
  overflow-x: auto;
  border-bottom: 1px solid var(--ngx-ai-chat-border, #e2e8f0);
  background: var(--ngx-ai-chat-bg, #ffffff);
}
.attachment-preview-tag {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
  background: #f1f5f9;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  font-size: 11px;
  max-width: 150px;
}
.attachment-thumb {
  width: 18px;
  height: 18px;
  object-fit: cover;
  border-radius: 2px;
}
.attachment-icon {
  font-size: 12px;
}
.attachment-name {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  flex: 1;
  color: #334155;
}
.remove-attachment-btn {
  background: none;
  border: none;
  color: #94a3b8;
  cursor: pointer;
  padding: 0 2px;
  font-size: 10px;
}
.remove-attachment-btn:hover {
  color: #ef4444;
}

/* Attachments inside bubble */
.message-attachments-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 8px;
}
.msg-attachment-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  background: rgba(255,255,255,0.7);
  border: 1px solid rgba(0,0,0,0.06);
  border-radius: 8px;
  text-decoration: none;
  color: inherit;
  max-width: 250px;
  font-size: 12px;
  transition: background 0.2s;
}
.msg-attachment-item:hover {
  background: rgba(255,255,255,0.9);
}
.msg-attachment-img-preview {
  width: 32px;
  height: 32px;
  overflow: hidden;
  border-radius: 4px;
}
.msg-attachment-img-preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.msg-attachment-icon {
  font-size: 16px;
}
.msg-attachment-name {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-weight: 500;
}

/* Attach button */
.attach-btn {
  background: none;
  border: none;
  color: #64748b;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8px;
  border-radius: 8px;
  transition: background 0.2s;
}
.attach-btn:hover:not(:disabled) {
  background: rgba(100, 116, 139, 0.1);
  color: #334155;
}
.attach-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Meta Row / Feedback Row styling */
.msg-meta-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 4px;
  min-width: 80px;
}
.feedback-actions {
  display: flex;
  gap: 4px;
  opacity: 0.3;
  transition: opacity 0.2s;
}
.message-wrapper:hover .feedback-actions {
  opacity: 1;
}
.feedback-tiny-btn {
  background: transparent;
  border: none;
  cursor: pointer;
  font-size: 10px;
  padding: 2px;
  border-radius: 4px;
  transition: background 0.2s;
}
.feedback-tiny-btn:hover {
  background: rgba(0,0,0,0.08);
}
.feedback-tiny-btn.selected {
  background: rgba(0,0,0,0.12);
  transform: scale(1.1);
}

/* Dark Mode specific overrides */
.dark-mode .attachments-preview-bar {
  border-bottom-color: var(--ngx-ai-chat-border, #334155);
  background: var(--ngx-ai-chat-bg, #1e293b);
}
.dark-mode .attachment-preview-tag {
  background: #334155;
  border-color: #475569;
}
.dark-mode .attachment-name {
  color: #f8fafc;
}
.dark-mode .msg-attachment-item {
  background: rgba(15, 23, 42, 0.4);
  border-color: rgba(255,255,255,0.06);
}
.dark-mode .msg-attachment-item:hover {
  background: rgba(15, 23, 42, 0.6);
}
.dark-mode .attach-btn {
  color: #94a3b8;
