styles:
:host {
  display: block;
  width: 100%;
  font-family: Consolas, Monaco, 'Andale Mono', 'Ubuntu Mono', monospace;
}

.code-editor-wrapper {
  border: 1px solid var(--border-color, #e2e8f0);
  border-radius: var(--radius-md, 10px);
  background: var(--bg-secondary, #ffffff);
  box-shadow: var(--shadow-md, 0 4px 6px -1px rgba(0, 0, 0, 0.08));
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

.code-editor-wrapper.focused {
  border-color: var(--primary-color, #4f46e5);
  box-shadow: 0 0 0 3px var(--primary-glow, rgba(79, 70, 229, 0.15));
}

/* Toolbar Header */
.editor-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 16px;
  background: var(--border-light, #f1f5f9);
  border-bottom: 1px solid var(--border-color, #e2e8f0);
}

.header-left {
  display: flex;
  align-items: center;
  gap: 6px;
}

.editor-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}
.editor-dot.red { background: #ef4444; }
.editor-dot.yellow { background: #f59e0b; }
.editor-dot.green { background: #10b981; }

.editor-lang-badge {
  margin-left: 10px;
  font-size: 11px;
  font-weight: 700;
  color: var(--text-secondary, #475569);
  background: rgba(0, 0, 0, 0.05);
  padding: 2px 6px;
  border-radius: 4px;
  letter-spacing: 0.5px;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.ai-pill {
  font-size: 11px;
  font-weight: 600;
  background: linear-gradient(135deg, rgba(79, 70, 229, 0.1) 0%, rgba(124, 58, 237, 0.1) 100%);
  color: #6d28d9;
  padding: 2px 8px;
  border-radius: 9999px;
  border: 1px solid rgba(124, 58, 237, 0.2);
}

.icon-btn {
  background: transparent;
  border: none;
  color: var(--text-secondary, #475569);
  cursor: pointer;
  font-size: 11px;
  padding: 4px 8px;
  border-radius: 4px;
  transition: background 0.2s;
}
.icon-btn:hover {
  background: rgba(0, 0, 0, 0.05);
  color: var(--text-primary, #0f172a);
}

/* Editor Canvas */
.editor-canvas {
  display: flex;
  flex-direction: row;
  position: relative;
  min-height: 150px;
  background: var(--bg-secondary, #ffffff);
  cursor: text;
}

.line-numbers {
  padding: 16px 8px 16px 12px;
  border-right: 1px solid var(--border-color, #e2e8f0);
  background: rgba(0, 0, 0, 0.01);
  user-select: none;
  text-align: right;
  min-width: 40px;
}

.line-num {
  color: var(--text-muted, #94a3b8);
  font-size: 12px;
  line-height: 1.6;
  height: 19.2px;
}

.code-content-container {
  position: relative;
  flex: 1;
  overflow: hidden;
}

.hidden-textarea {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  z-index: 2;
  resize: none;
  border: none;
  outline: none;
  padding: 16px;
  font-family: inherit;
  font-size: 13px;
  line-height: 1.6;
  white-space: pre-wrap;
  word-wrap: break-word;
}

.rendered-code {
  margin: 0;
  padding: 16px;
  font-family: inherit;
  font-size: 13px;
  line-height: 1.6;
  color: var(--text-primary, #0f172a);
  white-space: pre-wrap;
  word-wrap: break-word;
  pointer-events: none;
  z-index: 1;
  overflow-y: auto;
}

.cursor-pipe {
  color: var(--primary-color, #4f46e5);
  font-weight: bold;
  animation: blink 1s step-end infinite;
}

@keyframes blink {
  from, to { opacity: 0; }
  50% { opacity: 1; }
}

.ghost-text {
  color: var(--text-muted, #94a3b8);
  font-style: italic;
  opacity: 0.7;
}

/* Footer controls */
.editor-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  background: var(--border-light, #f1f5f9);
  border-top: 1px solid var(--border-color, #e2e8f0);
  gap: 12px;
  flex-wrap: wrap;
}

.editor-footer.justify-end {
  justify-content: flex-end;
}

.suggestion-info {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--text-secondary, #475569);
}

.sparkle {
  font-size: 14px;
}

.editor-kbd {
  background: var(--bg-secondary, #ffffff);
  border: 1px solid var(--border-color, #e2e8f0);
  border-radius: 3px;
  box-shadow: 0 1px 0 rgba(0, 0, 0, 0.1);
  padding: 1px 4px;
  font-size: 11px;
  font-family: sans-serif;
  font-weight: 600;
  color: var(--text-primary, #0f172a);
}

.action-buttons {
  display: flex;
  gap: 8px;
}

.footer-btn {
  padding: 6px 12px;
  font-size: 12px;
  font-weight: 600;
  border-radius: 6px;
  cursor: pointer;
  font-family: var(--ngx-font-family, sans-serif);
  transition: all 0.2s;
}

.accept-btn {
  background: var(--primary-color, #4f46e5);
  border: 1px solid var(--primary-color, #4f46e5);
  color: #ffffff;
}
.accept-btn:hover {
  background: var(--primary-hover, #4338ca);
}

.reject-btn {
  background: transparent;
  border: 1px solid var(--border-color, #e2e8f0);
  color: var(--text-secondary, #475569);
}
.reject-btn:hover {
  background: rgba(0, 0, 0, 0.04);
  border-color: var(--text-secondary, #475569);
}

.primary-btn {
  background: var(--primary-color, #4f46e5);
  border: 1px solid var(--primary-color, #4f46e5);
  color: #ffffff;
}
.primary-btn:hover {
  background: var(--primary-hover, #4338ca);
}

.secondary-btn {
  background: transparent;
  border: 1px solid var(--border-color, #e2e8f0);
  color: var(--text-secondary, #475569);
}
.secondary-btn:hover {
  background: rgba(0, 0, 0, 0.04);
}

/* Explanation Panel */
.explanation-panel {
  background: linear-gradient(to right, rgba(79, 70, 229, 0.03), rgba(124, 58, 237, 0.03));
