  padding: 16px;
}

.explanation-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
  font-weight: 700;
  font-size: 13px;
  color: var(--primary-color, #4f46e5);
  font-family: var(--ngx-font-family, sans-serif);
}

.close-explanation-btn {
  background: transparent;
  border: none;
  color: var(--text-muted, #94a3b8);
  font-size: 14px;
  cursor: pointer;
}
.close-explanation-btn:hover {
  color: var(--text-primary, #0f172a);
}

.explanation-body {
  font-size: 12px;
  line-height: 1.6;
  color: var(--text-secondary, #475569);
  font-family: var(--ngx-font-family, sans-serif);
}

/* Toolbar Toggle Button */
.toolbar-toggle-btn {
  background: transparent;
  border: 1px solid var(--border-color, #cbd5e1);
  border-radius: 6px;
  color: var(--text-secondary, #475569);
  cursor: pointer;
  font-size: 11px;
  font-weight: 600;
  padding: 4px 8px;
  font-family: inherit;
  transition: all 0.2s;
}
.toolbar-toggle-btn:hover {
  background: rgba(0, 0, 0, 0.05);
  border-color: var(--text-primary, #0f172a);
  color: var(--text-primary, #0f172a);
}
.toolbar-toggle-btn.active {
  background: var(--primary-color, #4f46e5);
  border-color: var(--primary-color, #4f46e5);
  color: #ffffff;
}

/* Diff Canvas */
.diff-canvas {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 180px;
  background: var(--bg-secondary, #ffffff);
  border-bottom: 1px solid var(--border-color, #e2e8f0);
}
.diff-pane {
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--border-color, #e2e8f0);
}
.diff-pane:last-child {
  border-right: none;
}
.diff-pane-title {
  padding: 6px 12px;
  background: rgba(0, 0, 0, 0.02);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--text-secondary, #64748b);
  border-bottom: 1px solid var(--border-color, #e2e8f0);
}
.diff-code {
  margin: 0;
  padding: 12px;
  font-family: inherit;
  font-size: 12px;
  line-height: 1.6;
  white-space: pre-wrap;
  overflow-y: auto;
  flex: 1;
}
.original-pane .diff-code {
  background: rgba(239, 68, 68, 0.02);
  color: #991b1b;
}
.proposed-pane .diff-code {
  background: rgba(16, 185, 129, 0.02);
}
.diff-highlight {
  background: rgba(16, 185, 129, 0.15);
  color: #065f46;
  border-radius: 2px;
  padding: 1px 2px;
  font-weight: 600;
}

/* Suggestions Navigator */
.suggestions-navigator {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-left: 12px;
  padding-left: 12px;
  border-left: 1px solid var(--border-color, #cbd5e1);
}
.nav-arrow {
  background: none;
  border: none;
  color: var(--primary-color, #4f46e5);
  cursor: pointer;
  font-size: 10px;
  padding: 2px 4px;
  border-radius: 4px;
  transition: background 0.2s;
}
.nav-arrow:hover {
  background: rgba(79, 70, 229, 0.1);
}
.nav-count {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-primary, #0f172a);
}

/* Dark Mode Diff Styling */
.code-editor-wrapper.dark .toolbar-toggle-btn {
  border-color: #374151;
  color: #94a3b8;
}
.code-editor-wrapper.dark .toolbar-toggle-btn:hover {
  background: rgba(255, 255, 255, 0.05);
  color: #f8fafc;
}
.code-editor-wrapper.dark .toolbar-toggle-btn.active {
  background: var(--primary-color, #6366f1);
  border-color: var(--primary-color, #6366f1);
  color: #ffffff;
}
.code-editor-wrapper.dark .diff-canvas {
  background: #0f172a;
  border-bottom-color: #1f2937;
}
.code-editor-wrapper.dark .diff-pane {
  border-right-color: #1f2937;
}
.code-editor-wrapper.dark .diff-pane-title {
  background: rgba(255, 255, 255, 0.02);
  color: #94a3b8;
  border-bottom-color: #1f2937;
}
.code-editor-wrapper.dark .original-pane .diff-code {
  background: rgba(239, 68, 68, 0.05);
  color: #fca5a5;
}
.code-editor-wrapper.dark .proposed-pane .diff-code {
  background: rgba(16, 185, 129, 0.05);
  color: #e2e8f0;
}
.code-editor-wrapper.dark .diff-highlight {
  background: rgba(16, 185, 129, 0.25);
  color: #34d399;
}
.code-editor-wrapper.dark .suggestions-navigator {
  border-left-color: #374151;
}
.code-editor-wrapper.dark .nav-count {
  color: #cbd5e1;
}
.code-editor-wrapper.dark .nav-arrow {
  color: #818cf8;
}
.code-editor-wrapper.dark .nav-arrow:hover {
  background: rgba(99, 102, 241, 0.15);
}

/* Syntax Highlighting */
.hl-keyword { color: #2563eb; font-weight: 600; }
.hl-builtin { color: #7c3aed; }
.hl-number { color: #ea580c; }
.hl-string { color: #16a34a; }
