  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--text-secondary, #475569);
}

.sparkle {
  font-size: 14px;
}

.editor-kbd {
  background: var(--bg-secondary, #ffffff);
  border: 1px solid var(--border-color, #e2e8f0);
  border-radius: 3px;
  box-shadow: 0 1px 0 rgba(0, 0, 0, 0.1);
  padding: 1px 4px;
  font-size: 11px;
  font-family: sans-serif;
  font-weight: 600;
  color: var(--text-primary, #0f172a);
}

.action-buttons {
  display: flex;
  gap: 8px;
}

.footer-btn {
  padding: 6px 12px;
  font-size: 12px;
  font-weight: 600;
  border-radius: 6px;
  cursor: pointer;
  font-family: var(--ngx-font-family, sans-serif);
  transition: all 0.2s;
}

.accept-btn {
  background: var(--primary-color, #4f46e5);
  border: 1px solid var(--primary-color, #4f46e5);
  color: #ffffff;
}
.accept-btn:hover {
  background: var(--primary-hover, #4338ca);
}

.reject-btn {
  background: transparent;
  border: 1px solid var(--border-color, #e2e8f0);
  color: var(--text-secondary, #475569);
}
.reject-btn:hover {
  background: rgba(0, 0, 0, 0.04);
  border-color: var(--text-secondary, #475569);
}

.primary-btn {
  background: var(--primary-color, #4f46e5);
  border: 1px solid var(--primary-color, #4f46e5);
  color: #ffffff;
}
.primary-btn:hover {
  background: var(--primary-hover, #4338ca);
}

.secondary-btn {
  background: transparent;
  border: 1px solid var(--border-color, #e2e8f0);
  color: var(--text-secondary, #475569);
}
.secondary-btn:hover {
  background: rgba(0, 0, 0, 0.04);
}

/* Explanation Panel */
.explanation-panel {
  background: linear-gradient(to right, rgba(79, 70, 229, 0.03), rgba(124, 58, 237, 0.03));
  border-top: 1px solid var(--border-color, #e2e8f0);
  padding: 16px;
}

.explanation-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
  font-weight: 700;
  font-size: 13px;
  color: var(--primary-color, #4f46e5);
  font-family: var(--ngx-font-family, sans-serif);
}

.close-explanation-btn {
  background: transparent;
  border: none;
  color: var(--text-muted, #94a3b8);
  font-size: 14px;
  cursor: pointer;
}
.close-explanation-btn:hover {
  color: var(--text-primary, #0f172a);
}

.explanation-body {
  font-size: 12px;
  line-height: 1.6;
  color: var(--text-secondary, #475569);
  font-family: var(--ngx-font-family, sans-serif);
}

/* Toolbar Toggle Button */
.toolbar-toggle-btn {
  background: transparent;
  border: 1px solid var(--border-color, #cbd5e1);
  border-radius: 6px;
  color: var(--text-secondary, #475569);
  cursor: pointer;
  font-size: 11px;
  font-weight: 600;
  padding: 4px 8px;
  font-family: inherit;
  transition: all 0.2s;
}
.toolbar-toggle-btn:hover {
  background: rgba(0, 0, 0, 0.05);
  border-color: var(--text-primary, #0f172a);
  color: var(--text-primary, #0f172a);
}
.toolbar-toggle-btn.active {
  background: var(--primary-color, #4f46e5);
  border-color: var(--primary-color, #4f46e5);
  color: #ffffff;
}

/* Diff Canvas */
.diff-canvas {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 180px;
  background: var(--bg-secondary, #ffffff);
  border-bottom: 1px solid var(--border-color, #e2e8f0);
}
.diff-pane {
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--border-color, #e2e8f0);
}
.diff-pane:last-child {
  border-right: none;
}
.diff-pane-title {
  padding: 6px 12px;
  background: rgba(0, 0, 0, 0.02);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--text-secondary, #64748b);
  border-bottom: 1px solid var(--border-color, #e2e8f0);
}
.diff-code {
