  color: #991b1b;
}
.proposed-pane .diff-code {
  background: rgba(16, 185, 129, 0.02);
}
.diff-highlight {
  background: rgba(16, 185, 129, 0.15);
  color: #065f46;
  border-radius: 2px;
  padding: 1px 2px;
