:host {
  display: block;
}
.ngx-area-spline-range-chart {
  position: relative;
  background: var(--bg-secondary, #ffffff);
  border: 1px solid var(--border-color, #e2e8f0);
  border-radius: 12px;
  padding: 20px;
}
.chart-legend {
  display: flex;
  gap: 16px;
  padding: 0 0 12px;
  flex-wrap: wrap;
}
.legend-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--text-secondary, #64748b);
  font-weight: 500;
}
.legend-dot {
  width: 12px;
  height: 6px;
  border-radius: 2px;
  display: inline-block;
  opacity: 0.7;
}
.chart-svg-wrap {
  position: relative;
  width: 100%;
}
.chart-svg {
  display: block;
  overflow: visible;
  cursor: crosshair;
}
.axis-label {
  font-size: 10px;
  font-weight: 600;
  fill: var(--text-secondary, #94a3b8);
}
.label-text {
  font-size: 9px;
  fill: var(--text-primary, #1e293b);
  font-weight: bold;
  pointer-events: none;
}

@keyframes lineDraw {
  from { stroke-dashoffset: 1200; }
  to { stroke-dashoffset: 0; }
}
.line-path {
  stroke-dasharray: 1200;
  stroke-dashoffset: 1200;
  animation: lineDraw 1.2s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

@keyframes areaFadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
.area-path {
  animation: areaFadeIn 1s cubic-bezier(0.16, 1, 0.3, 1) 0.3s both;
}

.marker-dot {
  animation: areaFadeIn 0.5s ease 0.8s both;
  transition: r 0.15s cubic-bezier(0.16, 1, 0.3, 1), stroke-width 0.15s;
}

