  gap: 4px;
}
.tooltip-val {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  color: rgba(248, 250, 252, 0.85);
}
.tooltip-val strong {
  color: #f8fafc;
  font-family: monospace;
  font-weight: 700;
}

/* Export styles */
.chart-export-menu {
  position: absolute;
  top: 0;
  right: 0;
  z-index: 50;
}
.export-trigger {
  padding: 4px 10px;
  font-size: 11px;
  font-weight: 600;
  color: var(--ngx-chart-axis-text, #6c757d);
