import {
  Component,
  ChangeDetectionStrategy,
  input,
  output,
  signal,
  computed,
  OnInit,
  OnDestroy,
  TemplateRef,
  HostListener,
  effect,
  untracked,
} from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'ngx-carousel',
  standalone: true,
  imports: [CommonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div
      class="ngx-carousel"
      [class.dark]="theme() === 'dark'"
      [attr.id]="id()"
      (keydown)="onKeyDown($event)"
      tabindex="0"
      (mouseenter)="onMouseEnter()"
      (mouseleave)="onMouseLeave()"
    >
      <div
        class="ngx-carousel__stage"
        (touchstart)="onTouchStart($event)"
        (touchend)="onTouchEnd($event)"
      >
        @for (item of items(); track $index) {
          <div
            class="ngx-carousel__slide"
            [class]="getSlideClass($index)"
          >
            @if (itemTemplate()) {
              <ng-container *ngTemplateOutlet="itemTemplate()!; context: { $implicit: item, index: $index }"></ng-container>
            } @else {
              <!-- Default Image layout -->
              <img [src]="item.url" [alt]="item.title || 'Slide ' + ($index + 1)" class="ngx-carousel__img" />
              @if (item.title || item.caption) {
                <div class="ngx-carousel__caption-card">
                  @if (item.title) {
                    <h3 class="ngx-carousel__caption-title">{{ item.title }}</h3>
                  }
                  @if (item.caption) {
                    <p class="ngx-carousel__caption-desc">{{ item.caption }}</p>
                  }
                </div>
              }
            }
          </div>
        }
      </div>

      <!-- Controls -->
      @if (showControls() && items().length > 1) {
        <button
          class="ngx-carousel__control prev"
          (click)="prevSlide()"
          aria-label="Previous slide"
        >
          <svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2.5">
            <polyline points="15 18 9 12 15 6" />
          </svg>
        </button>
        <button
          class="ngx-carousel__control next"
          (click)="nextSlide()"
          aria-label="Next slide"
        >
          <svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2.5">
            <polyline points="9 18 15 12 9 6" />
          </svg>
        </button>
      }

      <!-- Indicators -->
      @if (showIndicators() && items().length > 1) {
        <div class="ngx-carousel__indicators">
          @for (item of items(); track $index) {
            <button
              class="ngx-carousel__indicator"
              [class.active]="$index === activeIndex()"
              (click)="goToSlide($index)"
              [attr.aria-label]="'Go to slide ' + ($index + 1)"
            ></button>
          }
        </div>
      }
    </div>
  `,
  styles: [`
    :host {
      display: block;
      width: 100%;
    }

    .ngx-carousel {
      position: relative;
      width: 100%;
      border-radius: 16px;
      overflow: hidden;
      outline: none;
      background: #f1f5f9;
      box-shadow: 
        0 10px 25px -5px rgba(0, 0, 0, 0.05),
        0 8px 10px -6px rgba(0, 0, 0, 0.05);
      font-family: var(--ngx-font-family, system-ui, sans-serif);
      transition: box-shadow 0.3s ease;
    }

    .ngx-carousel.dark {
      background: #0f172a;
    }

    .ngx-carousel:focus-visible {
      box-shadow: 0 0 0 3px var(--primary-color, #3b82f6);
    }

    .ngx-carousel__stage {
      position: relative;
      width: 100%;
      height: 400px;
      overflow: hidden;
    }

    /* ── Slide styles ── */
    .ngx-carousel__slide {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      visibility: hidden;
      opacity: 0;
      overflow: hidden;
      display: flex;
      align-items: center;
