styles:
:host {
  display: block;
}
.ngx-column-pyramid-chart {
  background: var(--bg-secondary, #ffffff);
  border: 1px solid var(--border-color, #e2e8f0);
  border-radius: 12px;
  padding: 20px;
  position: relative;
  width: 100%;
}
.chart-svg-wrap {
  position: relative;
  width: 100%;
}
.chart-svg {
  display: block;
  overflow: visible;
}
.grid-line {
  stroke: var(--ngx-chart-grid, #f1f5f9);
  stroke-width: 1;
}
.axis-line {
  stroke: var(--ngx-chart-axis, #cbd5e1);
  stroke-width: 1.5;
}
.axis-label {
  font-size: 10px;
  font-weight: 600;
  fill: var(--text-secondary, #94a3b8);
  user-select: none;
}
.label-text {
  font-size: 9.5px;
  fill: var(--text-primary, #1e293b);
  font-weight: bold;
  pointer-events: none;
}
.pyramid-poly {
  cursor: pointer;
  transition: opacity 0.2s ease, fill-opacity 0.2s ease, stroke-width 0.2s ease;
}
.pyramid-poly.dimmed {
  opacity: 0.35;
}
.pyramid-poly.highlighted {
  opacity: 1;
  stroke: #ffffff;
  stroke-width: 1.5;
  filter: drop-shadow(0 4px 8px rgba(0,0,0,0.12));
}

/* Legend */
.chart-legend {
  display: flex;
  gap: 16px;
  margin-bottom: 12px;
  flex-wrap: wrap;
}
.legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
}
.legend-rect {
  width: 0;
  height: 0;
  border-left: 6px solid transparent;
  border-right: 6px solid transparent;
  display: inline-block;
}
.legend-label {
  font-size: 12px;
  color: var(--text-secondary, #64748b);
  font-weight: 500;
}

/* Glassmorphic Tooltip */
