  flex-shrink: 0;
}
.tt-name {
  color: rgba(248, 250, 252, 0.85);
  flex: 1;
}
.tt-val {
  font-weight: 700;
  font-family: monospace;
}
.tt-val.highlight {
  color: #38bdf8;
}

