:host {
  display: block;
  width: 100%;
  height: 100%;
}

.ngx-dashboard-wrapper {
  position: relative;
  width: 100%;
  height: 100%;
  background: var(--bg-primary, #f8fafc);
  padding: 16px;
  box-sizing: border-box;
  overflow-y: auto;
  transition: background 0.3s ease;
}

.ngx-dashboard-wrapper.dark {
  background: #0f172a;
}

.ngx-dashboard-grid {
  position: relative;
  display: grid;
  gap: 16px;
  width: 100%;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Grid Background Overlay for Snapping Hints */
.grid-background-overlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  display: grid;
  grid-template-columns: inherit;
  grid-auto-rows: inherit;
  gap: inherit;
  pointer-events: none;
  z-index: 1;
}

.bg-cell-target {
  border: 1px dashed var(--border-color, #cbd5e1);
  border-radius: 8px;
  background: rgba(148, 163, 184, 0.02);
  pointer-events: auto;
  box-sizing: border-box;
}
.ngx-dashboard-wrapper.dark .bg-cell-target {
  border-color: #334155;
  background: rgba(30, 41, 59, 0.1);
}

/* Drag Placeholder Box */
.drag-placeholder-indicator {
  border-radius: 12px;
  border: 2px dashed var(--primary-color, #4f46e5);
  background: var(--primary-glow, rgba(79, 70, 229, 0.05));
  z-index: 2;
  box-sizing: border-box;
  animation: pulsePlaceholder 1.5s infinite ease-in-out;
}

@keyframes pulsePlaceholder {
  0%, 100% { opacity: 0.6; }
  50% { opacity: 0.9; }
}

.placeholder-inner {
  width: 100%;
  height: 100%;
}

/* Panel Card Styling */
.dashboard-panel-card {
  position: relative;
  display: flex;
  flex-direction: column;
  background: var(--bg-secondary, #ffffff);
  border: 1px solid var(--border-color, #e2e8f0);
  border-radius: 12px;
  box-shadow: var(--shadow-sm, 0 1px 3px rgba(0, 0, 0, 0.05));
  overflow: hidden;
  z-index: 3;
  transition: box-shadow 0.25s, transform 0.25s;
  box-sizing: border-box;
}
.ngx-dashboard-wrapper.dark .dashboard-panel-card {
  background: #1e293b;
  border-color: #334155;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.2);
}

.dashboard-panel-card:hover {
  box-shadow: var(--shadow-md, 0 4px 6px -1px rgba(0,0,0,0.08));
}

.dashboard-panel-card.dragging-active {
  opacity: 0.4;
  border-style: dashed;
  border-color: var(--primary-color, #4f46e5);
}

/* Maximized override state */
.dashboard-panel-card.maximized {
  grid-column: 1 / -1 !important;
  grid-row: auto !important;
  min-height: 500px;
  z-index: 50;
  box-shadow: var(--shadow-xl, 0 20px 25px -5px rgba(0, 0, 0, 0.15));
}
.ngx-dashboard-wrapper.has-maximized .dashboard-panel-card:not(.maximized) {
  display: none !important;
}

/* Collapsed state */
.dashboard-panel-card.collapsed {
  grid-row-end: span 1 !important;
  height: fit-content !important;
  min-height: 0 !important;
}
.dashboard-panel-card.collapsed .panel-content-body {
  display: none !important;
}
.dashboard-panel-card.collapsed .resize-handle {
  display: none !important;
}

/* Header styling */
.panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-color, #e2e8f0);
  background: var(--border-light, #f8fafc);
  user-select: none;
  gap: 12px;
}
.ngx-dashboard-wrapper.dark .panel-header {
  background: #1e293b;
  border-bottom-color: #334155;
}

.panel-header.draggable-handle {
  cursor: grab;
}
.panel-header.draggable-handle:active {
  cursor: grabbing;
}

.panel-title-group {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.panel-icon-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.panel-title {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary, #1e293b);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ngx-dashboard-wrapper.dark .panel-title {
  color: #f8fafc;
}

.panel-actions {
  display: flex;
  align-items: center;
  gap: 4px;
}

.action-btn {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 11px;
  padding: 4px;
  border-radius: 4px;
  color: var(--text-secondary, #64748b);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s;
}
.action-btn:hover {
  background: var(--border-color, #cbd5e1);
  color: var(--text-primary, #0f172a);
}
.ngx-dashboard-wrapper.dark .action-btn:hover {
  background: #334155;
  color: #ffffff;
}

.action-btn.close-btn:hover {
  background: #fca5a5;
  color: #991b1b;
}

/* Content Body styling */
.panel-content-body {
  flex: 1;
  position: relative;
  overflow: auto;
  box-sizing: border-box;
}

/* Projected content wrapper fallback style */
.fallback-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  padding: 24px;
  text-align: center;
  color: var(--text-secondary, #64748b);
  font-family: var(--ngx-font-family, sans-serif);
  box-sizing: border-box;
}
.ngx-dashboard-wrapper.dark .fallback-placeholder {
  color: #94a3b8;
}

.fallback-icon {
  font-size: 28px;
  margin-bottom: 8px;
  opacity: 0.5;
}

.fallback-placeholder h4 {
  margin: 0 0 4px;
  font-size: 13px;
  font-weight: 600;
}

.fallback-placeholder p {
  margin: 0;
  font-size: 11px;
  line-height: 1.4;
  max-width: 250px;
}

/* Custom layout content is projected so we hide default placeholder when projected content is active */
.panel-content-body:has([panel-id]) .fallback-placeholder {
  display: none !important;
}

/* Resize Grip Handle */
.resize-handle {
  position: absolute;
  right: 2px;
  bottom: 2px;
  width: 14px;
  height: 14px;
  cursor: nwse-resize;
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  color: var(--text-secondary, #94a3b8);
  z-index: 5;
}
.resize-handle:hover {
  color: var(--primary-color, #4f46e5);
}

