:host {
  display: block;
}
.ngx-dependency-wheel {
  background: var(--ngx-chart-bg, #ffffff);
  border-radius: 16px;
  padding: 16px;
  box-sizing: border-box;
  font-family: var(--ngx-font-family, system-ui, sans-serif);
  position: relative;
  width: 100%;
}
.wheel-svg {
  display: block;
  overflow: visible;
}
.node-arc {
  cursor: pointer;
  transition: fill-opacity 0.2s ease, stroke-width 0.2s ease;
  transform-origin: center;
  animation: wheelScaleIn 0.8s cubic-bezier(0.34, 1.3, 0.64, 1) forwards;
}
.node-label {
  font-size: 11px;
  fill: var(--ngx-chart-axis-text, #334155);
  font-weight: 600;
  user-select: none;
  pointer-events: none;
}
.dependency-ribbon {
  cursor: pointer;
  transition: fill-opacity 0.2s ease, stroke-width 0.2s ease, opacity 0.2s ease;
  transform-origin: center;
  animation: wheelScaleIn 1s cubic-bezier(0.34, 1.3, 0.64, 1) forwards;
}
@keyframes wheelScaleIn {
  from { transform: scale(0); opacity: 0; }
  to { transform: scale(1); opacity: 1; }
}
.dependency-ribbon.dimmed, .wheel-node-group.dimmed {
  opacity: 0.15;
}
.dependency-ribbon.highlighted {
  fill-opacity: 0.7;
  stroke-width: 1.5;
  stroke-opacity: 0.9;
}
.wheel-node-group.highlighted .node-arc {
  stroke-width: 2.5;
}

/* Glassmorphic Tooltip */
.chart-tooltip {
  position: absolute;
  pointer-events: none;
  transform: translate(-50%, -100%) translateY(-10px);
  background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.92));
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  color: var(--ngx-chart-tooltip-color, #f8fafc);
  padding: 10px 14px;
  border-radius: 10px;
  font-size: 12px;
  min-width: 160px;
  box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3), 0 8px 10px -6px rgba(0,0,0,0.3);
  border: 1px solid rgba(255, 255, 255, 0.1);
  z-index: 100;
  transition: left 0.1s cubic-bezier(0.16, 1, 0.3, 1), top 0.1s cubic-bezier(0.16, 1, 0.3, 1);
}
.tt-cat {
  font-weight: 700;
  margin-bottom: 6px;
  font-size: 12.5px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  padding-bottom: 4px;
  color: #38bdf8;
}
.tt-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
}
.tt-name {
  color: rgba(248, 250, 252, 0.8);
  flex: 1;
}
.tt-val {
  font-weight: 700;
  font-family: monospace;
}

/* Export styles */
.chart-export-menu {
  position: relative;
  z-index: 50;
  margin-bottom: 12px;
}
.export-trigger {
  float: right;
  padding: 4px 10px;
  font-size: 11px;
  font-weight: 600;
  color: var(--ngx-chart-axis-text, #64748b);
  background: rgba(241, 245, 249, 0.8);
  backdrop-filter: blur(8px);
  border: 1px solid var(--ngx-chart-grid, #e2e8f0);
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.15s;
}
.export-trigger:hover {
  background: #ffffff;
  color: #4f46e5;
  border-color: #4f46e5;
}
.export-dropdown {
  position: absolute;
  right: 0;
  top: calc(100% + 4px);
  background: #ffffff;
  border: 1px solid var(--ngx-chart-grid, #e2e8f0);
  border-radius: 8px;
  box-shadow: 0 10px 15px -3px rgba(0,0,0,0.1);
  padding: 4px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 120px;
  z-index: 60;
}
.export-dropdown button {
  background: none;
  border: none;
  padding: 6px 10px;
  font-size: 11px;
  text-align: left;
  cursor: pointer;
  color: #1e293b;
  border-radius: 4px;
  width: 100%;
  transition: all 0.12s;
}
.export-dropdown button:hover {
  background: rgba(79, 70, 229, 0.06);
  color: #4f46e5;
}
.chart-header { display: flex; justify-content: space-between; align-items: center; min-height: 24px; position: relative; }

