.dumbbell-row {
  transition: opacity 0.2s ease;
}
.dumbbell-row.dimmed {
  opacity: 0.3;
}
.dumbbell-row.highlighted .connecting-bar {
  stroke-width: 6;
  opacity: 1;
}

