.chart-legend {
  display: flex;
  gap: 16px;
  margin-bottom: 16px;
  justify-content: flex-end;
}
.legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
}
.legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}
.legend-label {
  font-size: 12px;
  color: #475569;
  font-weight: 600;
}

/* Glassmorphic Tooltip */
.chart-tooltip {
  position: absolute;
  pointer-events: none;
  transform: translate(-50%, -100%) translateY(-10px);
  background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.92));
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  color: var(--ngx-chart-tooltip-color, #f8fafc);
  padding: 10px 14px;
  border-radius: 10px;
  font-size: 12px;
  min-width: 160px;
  box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3), 0 8px 10px -6px rgba(0,0,0,0.3);
  border: 1px solid rgba(255, 255, 255, 0.1);
  z-index: 100;
  transition: left 0.1s cubic-bezier(0.16, 1, 0.3, 1), top 0.1s cubic-bezier(0.16, 1, 0.3, 1);
}
.tt-cat {
  font-weight: 700;
  margin-bottom: 6px;
  font-size: 12.5px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  padding-bottom: 4px;
  color: #38bdf8;
}
.tt-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
}
.delta-row {
  border-top: 1px dashed rgba(255, 255, 255, 0.15);
  margin-top: 6px;
  padding-top: 6px;
}
.tt-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
.tt-name {
  color: rgba(248, 250, 252, 0.8);
  flex: 1;
}
.tt-val {
  font-weight: 700;
  font-family: monospace;
}

/* Header and Export dropdown styles */
.chart-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
  min-height: 24px;
  position: relative;
}
.chart-export-menu {
  position: relative;
  z-index: 50;
}
.export-trigger {
  padding: 4px 10px;
  font-size: 11px;
  font-weight: 600;
  color: var(--ngx-chart-axis-text, #64748b);
  background: rgba(241, 245, 249, 0.8);
  backdrop-filter: blur(8px);
  border: 1px solid var(--ngx-chart-grid, #e2e8f0);
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.15s;
}
.export-trigger:hover {
  background: #ffffff;
  color: #4f46e5;
  border-color: #4f46e5;
}
.export-dropdown {
  position: absolute;
  right: 0;
  top: calc(100% + 4px);
  background: #ffffff;
