  background: var(--ngx-chart-bg, #ffffff);
  border: 1px solid var(--border-color, #e2e8f0);
  border-radius: 16px;
  padding: 16px;
  box-sizing: border-box;
  font-family: var(--ngx-font-family, system-ui, sans-serif);
  position: relative;
  width: 100%;
}
.chart-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
  min-height: 24px;
  position: relative;
}
.header-info {
  display: flex;
  flex-direction: column;
}
.header-title {
  font-size: 14px;
  font-weight: 700;
  color: var(--ngx-chart-axis-text, #334155);
}
.header-subtitle {
  font-size: 11px;
  font-weight: 500;
  color: var(--ngx-chart-axis-text, #64748b);
}
.error-bar-svg {
  display: block;
  overflow: visible;
}
.grid-line {
  stroke: var(--ngx-chart-grid, #f1f5f9);
  stroke-width: 1;
  stroke-dasharray: 3,3;
}
.axis-line {
  stroke: var(--ngx-chart-axis, #cbd5e1);
  stroke-width: 1.5;
}
.tick-line {
  stroke: var(--ngx-chart-axis, #cbd5e1);
  stroke-width: 1.5;
}
.tick-label {
  font-size: 10px;
  fill: var(--ngx-chart-axis-text, #64748b);
  font-weight: 550;
  user-select: none;
}
.x-tick-label {
  font-size: 10px;
}
.bar-rect {
  cursor: pointer;
  transition: all 0.2s ease;
}
.bar-rect.dimmed {
  opacity: 0.25 !important;
}
.error-whisker-group {
  cursor: pointer;
}
.error-whisker-group.dimmed {
  opacity: 0.3;
}
.error-whisker-group.highlighted .whisker-line,
.error-whisker-group.highlighted .whisker-cap {
  stroke: #0f172a !important;
  stroke-width: 2.2px !important;
}
.center-dot {
  transition: r 0.15s ease;
}
.trend-line {
  stroke-dasharray: 1000;
  stroke-dashoffset: 1000;
  animation: drawLine 1.2s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}
@keyframes drawLine {
  from { stroke-dashoffset: 1000; }
  to { stroke-dashoffset: 0; }
}

/* Glassmorphic Tooltip */
.chart-tooltip {
  position: absolute;
  pointer-events: none;
  transform: translate(-50%, -100%) translateY(-10px);
  background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.92));
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  color: var(--ngx-chart-tooltip-color, #f8fafc);
  padding: 10px 14px;
  border-radius: 10px;
  font-size: 12px;
  min-width: 160px;
  box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3), 0 8px 10px -6px rgba(0,0,0,0.3);
  border: 1px solid rgba(255, 255, 255, 0.1);
  z-index: 100;
  transition: left 0.1s cubic-bezier(0.16, 1, 0.3, 1), top 0.1s cubic-bezier(0.16, 1, 0.3, 1);
}
.tt-cat {
  font-weight: 700;
  margin-bottom: 6px;
  font-size: 12.5px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  padding-bottom: 4px;
  color: #38bdf8;
}
.tt-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
}
.tt-name {
  color: rgba(248, 250, 252, 0.8);
  flex: 1;
}
.tt-val {
  font-weight: 700;
  font-family: monospace;
}

/* Export dropdown styles */
.chart-export-menu {
  position: relative;
  z-index: 50;
}
.export-trigger {
  padding: 4px 10px;
  font-size: 11px;
  font-weight: 600;
  color: var(--ngx-chart-axis-text, #64748b);
  background: rgba(241, 245, 249, 0.8);
  backdrop-filter: blur(8px);
  border: 1px solid var(--ngx-chart-grid, #e2e8f0);
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.15s;
}
.export-trigger:hover {
  background: #ffffff;
  color: #4f46e5;
  border-color: #4f46e5;
}
.export-dropdown {
  position: absolute;
  right: 0;
  top: calc(100% + 4px);
  background: #ffffff;
  border: 1px solid var(--ngx-chart-grid, #e2e8f0);
  border-radius: 8px;
  box-shadow: 0 10px 15px -3px rgba(0,0,0,0.1);
  padding: 4px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 120px;
}
.export-dropdown button {
  background: none;
  border: none;
  padding: 6px 10px;
  font-size: 11px;
  text-align: left;
  cursor: pointer;
  color: #1e293b;
  border-radius: 4px;
  width: 100%;
  transition: all 0.12s;
}
.export-dropdown button:hover {
  background: rgba(79, 70, 229, 0.06);
  color: #4f46e5;
}

