:host {
  display: block;
  width: 100%;
}

.ngx-file-preview {
  width: 100%;
  font-family: var(--ngx-font-family, system-ui, sans-serif);
}

/* ── Empty State ── */
.ngx-file-preview__empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 40px;
  border: 2px dashed rgba(0, 0, 0, 0.1);
  border-radius: 12px;
  color: #64748b;
  background: rgba(255, 255, 255, 0.2);
}

.dark .ngx-file-preview__empty {
  border-color: rgba(255, 255, 255, 0.08);
  color: #94a3b8;
  background: rgba(15, 23, 42, 0.15);
}

.ngx-file-preview__empty svg {
  margin-bottom: 8px;
  stroke: #94a3b8;
}

.ngx-file-preview__empty-text {
  font-size: 13px;
  font-weight: 500;
}

/* ── Grid Container ── */
.ngx-file-preview__grid-container {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 16px;
}

/* ── Card Styling ── */
.ngx-file-preview__card {
  display: flex;
  flex-direction: column;
  border-radius: 12px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.7);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(0, 0, 0, 0.06);
  box-shadow: 
    0 4px 6px -1px rgba(0, 0, 0, 0.03),
    0 2px 4px -1px rgba(0, 0, 0, 0.02);
  transition: all 0.2s ease;
}

.ngx-file-preview__card:hover {
  transform: translateY(-2px);
  box-shadow: 
    0 10px 15px -3px rgba(0, 0, 0, 0.05),
    0 4px 6px -4px rgba(0, 0, 0, 0.05);
  border-color: rgba(0, 0, 0, 0.12);
}

.dark .ngx-file-preview__card {
  background: rgba(30, 32, 48, 0.85);
  border-color: rgba(255, 255, 255, 0.06);
}

.dark .ngx-file-preview__card:hover {
  border-color: rgba(255, 255, 255, 0.12);
}

/* ── Media wrapper & Thumbnail ── */
.ngx-file-preview__media-wrapper {
  position: relative;
  width: 100%;
  height: 120px;
  background: #f8fafc;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}

.dark .ngx-file-preview__media-wrapper {
  background: #1e293b;
}

.ngx-file-preview__thumbnail {
  width: 100%;
  height: 100%;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

.ngx-file-preview__icon-fallback {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  font-weight: 700;
}

.file-icon-symbol {
  font-size: 36px;
  line-height: 1;
  margin-bottom: 4px;
}

.file-icon-badge {
  font-size: 10px;
  padding: 2px 6px;
  border-radius: 4px;
  background: rgba(0, 0, 0, 0.05);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.dark .file-icon-badge {
  background: rgba(255, 255, 255, 0.1);
}

/* ── Overlays actions ── */
.ngx-file-preview__overlay-actions {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(15, 23, 42, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  opacity: 0;
  transition: opacity 0.2s ease;
  z-index: 5;
}

.ngx-file-preview__media-wrapper:hover .ngx-file-preview__overlay-actions {
  opacity: 1;
}

.ngx-file-preview__action-btn {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: none;
  background: rgba(255, 255, 255, 0.9);
  color: #0f172a;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
}

.ngx-file-preview__action-btn:hover {
  transform: scale(1.1);
  background: #ffffff;
}

.ngx-file-preview__action-btn.btn-delete:hover {
  background: #ef4444;
  color: #ffffff;
}

.ngx-file-preview__action-btn.btn-download:hover {
  background: var(--primary-color, #3b82f6);
  color: #ffffff;
}

/* ── Details content ── */
.ngx-file-preview__details {
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex-grow: 1;
}

.ngx-file-preview__meta {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
}

.ngx-file-preview__name {
  font-size: 13px;
  font-weight: 600;
  color: #0f172a;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  flex-grow: 1;
}

.dark .ngx-file-preview__name {
  color: #f8fafc;
}

.ngx-file-preview__size {
  font-size: 11px;
  font-weight: 500;
  color: #64748b;
  white-space: nowrap;
}

.dark .ngx-file-preview__size {
  color: #94a3b8;
}

/* ── Progress display ── */
.ngx-file-preview__progress-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
}

.ngx-file-preview__progress-bar {
  flex-grow: 1;
  height: 4px;
  border-radius: 2px;
  background: rgba(0, 0, 0, 0.05);
  overflow: hidden;
}

.dark .ngx-file-preview__progress-bar {
  background: rgba(255, 255, 255, 0.08);
}

.ngx-file-preview__progress-fill {
  height: 100%;
  background: var(--primary-color, #3b82f6);
  transition: width 0.2s ease;
}

.ngx-file-preview__progress-text {
  font-size: 10px;
  font-weight: 600;
  color: #64748b;
  width: 28px;
  text-align: right;
}

.ngx-file-preview__error-msg {
  font-size: 11px;
  color: #ef4444;
  font-weight: 500;
}

.ngx-file-preview__status-row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 600;
  text-transform: capitalize;
  color: #64748b;
}

.dark .ngx-file-preview__status-row {
  color: #94a3b8;
}

.status-indicator {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #64748b;
}

.status-indicator.success {
  background: #10b981;
}

.status-indicator.pending {
  background: #f59e0b;
}

/* ── List Layout ── */
.ngx-file-preview.list .ngx-file-preview__grid-container {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.ngx-file-preview.list .ngx-file-preview__card {
  flex-direction: row;
  align-items: center;
  padding: 8px 12px;
  gap: 12px;
}

.ngx-file-preview.list .ngx-file-preview__card:hover {
  transform: translateX(2px) translateY(0);
}

.ngx-file-preview.list .ngx-file-preview__media-wrapper {
  width: 42px;
  height: 42px;
  border-radius: 6px;
  flex-shrink: 0;
}

.ngx-file-preview.list .file-icon-symbol {
  font-size: 20px;
  margin: 0;
}

.ngx-file-preview.list .file-icon-badge {
  display: none;
}

.ngx-file-preview.list .ngx-file-preview__details {
  padding: 0;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  gap: 16px;
}

.ngx-file-preview.list .ngx-file-preview__meta {
  flex-grow: 1;
  width: 30%;
  flex-direction: column;
  gap: 2px;
}

.ngx-file-preview.list .ngx-file-preview__progress-wrap {
  width: 120px;
  flex-shrink: 0;
}

/* List Hover action menu */
.ngx-file-preview.list .ngx-file-preview__overlay-actions {
  position: static;
  opacity: 1;
  background: transparent;
  box-shadow: none;
  width: auto;
  height: auto;
  gap: 6px;
  margin-left: auto;
}

.ngx-file-preview.list .ngx-file-preview__action-btn {
  width: 30px;
  height: 30px;
  box-shadow: none;
  border: 1px solid rgba(0, 0, 0, 0.05);
  background: rgba(0, 0, 0, 0.02);
}

.dark .ngx-file-preview.list .ngx-file-preview__action-btn {
  border-color: rgba(255, 255, 255, 0.06);
  background: rgba(255, 255, 255, 0.02);
  color: #cbd5e1;
}

.ngx-file-preview.list .ngx-file-preview__action-btn:hover {
  transform: scale(1.05);
}

