:host {
  display: block;
  width: 100%;
}

.ngx-file-preview {
  width: 100%;
  font-family: var(--ngx-font-family, system-ui, sans-serif);
}

/* ── Empty State ── */
.ngx-file-preview__empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 40px;
  border: 2px dashed rgba(0, 0, 0, 0.1);
