:host {
  display: block;
  width: 100%;
}

.file-upload-wrapper {
  background: var(--bg-secondary, #ffffff);
  border: 1px solid var(--border-color, #e2e8f0);
  border-radius: var(--radius-md, 10px);
  padding: 16px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 16px;
  transition: all 0.25s;
}

.file-upload-wrapper.drag-over {
  border-color: var(--primary-color, #4f46e5);
  background: rgba(79, 70, 229, 0.01);
}

.file-upload-wrapper.disabled {
  opacity: 0.65;
  pointer-events: none;
}

/* Dropzone area */
.dropzone-area {
  border: 2px dashed var(--border-color, #cbd5e1);
  border-radius: var(--radius-md, 10px);
  padding: 32px 20px;
  text-align: center;
  cursor: pointer;
  background: rgba(0, 0, 0, 0.005);
  transition: all 0.2s ease-in-out;
  position: relative;
}

.dropzone-area:hover {
  border-color: var(--primary-color, #4f46e5);
  background: rgba(79, 70, 229, 0.02);
}

.dropzone-area:focus-visible {
  outline: 2px dashed var(--primary-color, #4f46e5);
  outline-offset: 2px;
  border-color: var(--primary-color, #4f46e5);
  background: rgba(79, 70, 229, 0.02);
}

.drag-over .dropzone-area {
  border-color: var(--primary-color, #4f46e5);
  background: rgba(79, 70, 229, 0.05);
}

.hidden-file-input {
  display: none;
}

.dropzone-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  user-select: none;
}

.upload-icon-circle {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--border-light, #f1f5f9);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary, #475569);
  transition: all 0.2s;
}

.dropzone-area:hover .upload-icon-circle {
  background: var(--primary-color, #4f46e5);
  color: #ffffff;
  transform: scale(1.05);
}

.upload-arrow-svg {
  width: 20px;
  height: 20px;
}

.upload-headline {
  font-family: var(--ngx-font-family, sans-serif);
  font-size: 14px;
  font-weight: 550;
  color: var(--text-primary, #0f172a);
}

.upload-headline .highlight {
  color: var(--primary-color, #4f46e5);
  font-weight: 700;
}

.upload-subtext {
  font-family: var(--ngx-font-family, sans-serif);
  font-size: 11px;
  color: var(--text-secondary, #64748b);
}

/* Queue list */
.file-queue-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  border-top: 1px solid var(--border-color, #e2e8f0);
  padding-top: 16px;
}

.queue-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--ngx-font-family, sans-serif);
}

.queue-header h4 {
  margin: 0;
  font-size: 13px;
  font-weight: 750;
  color: var(--text-primary, #0f172a);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.clear-all-btn {
  background: transparent;
  border: none;
  color: #ef4444;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  padding: 2px 6px;
  border-radius: 4px;
  transition: background 0.2s;
}
.clear-all-btn:hover {
  background: rgba(239, 68, 68, 0.05);
}

.queue-items {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 280px;
  overflow-y: auto;
  padding-right: 4px;
}

.queue-item-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  border: 1px solid var(--border-color, #e2e8f0);
  border-radius: 8px;
  background: var(--bg-secondary, #ffffff);
  transition: all 0.2s;
}

.queue-item-card:hover {
  border-color: var(--text-secondary, #94a3b8);
  box-shadow: var(--shadow-sm);
}

.queue-item-card.success { border-color: rgba(16, 185, 129, 0.3); background: rgba(16, 185, 129, 0.005); }
.queue-item-card.error { border-color: rgba(239, 68, 68, 0.3); background: rgba(239, 68, 68, 0.005); }

.item-icon {
  color: var(--text-secondary, #64748b);
  display: flex;
  align-items: center;
  justify-content: center;
}

.file-icon-svg {
  width: 20px;
  height: 20px;
}

.item-details {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
  overflow: hidden;
  font-family: var(--ngx-font-family, sans-serif);
}

.item-meta {
  display: flex;
  justify-content: space-between;
  gap: 8px;
}

.item-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary, #0f172a);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.item-size {
  font-size: 11px;
  color: var(--text-secondary, #64748b);
  white-space: nowrap;
}

/* Progress and error layouts */
.item-progress-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
}

.progress-track {
  flex: 1;
  height: 4px;
  background: var(--border-light, #f1f5f9);
  border-radius: 2px;
  overflow: hidden;
}

.progress-bar-fill {
  height: 100%;
  background: var(--primary-color, #4f46e5);
  border-radius: 2px;
  transition: width 0.15s;
}

.progress-text {
  font-size: 10px;
  font-weight: 700;
  color: var(--text-secondary, #475569);
  min-width: 28px;
  text-align: right;
}

.item-error-msg {
  font-size: 11px;
  color: #ef4444;
  font-weight: 600;
}

.item-status-badge {
  font-size: 10px;
  font-weight: 700;
  border-radius: 4px;
  padding: 1px 6px;
  width: fit-content;
}

.item-status-badge.success {
  background: rgba(16, 185, 129, 0.1);
  color: #10b981;
}

/* Actions buttons */
.item-actions {
  display: flex;
  gap: 6px;
}

.action-btn {
  background: transparent;
  border: none;
  font-size: 12px;
  cursor: pointer;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary, #64748b);
  transition: background 0.2s, color 0.2s;
}

.action-btn:hover {
  background: var(--border-light, #f1f5f9);
  color: var(--text-primary, #0f172a);
}

.action-btn.remove-btn:hover {
  color: #ef4444;
  background: rgba(239, 68, 68, 0.05);
}

/* Dark Mode */
.file-upload-wrapper.dark {
  background: #0f172a;
  border-color: #1f2937;
}
.file-upload-wrapper.dark .dropzone-area {
  border-color: #374151;
}
.file-upload-wrapper.dark .dropzone-area:hover {
  border-color: var(--primary-color, #6366f1);
  background: rgba(99, 102, 241, 0.02);
}
.file-upload-wrapper.dark .upload-icon-circle {
  background: #1e293b;
  color: #94a3b8;
}
.file-upload-wrapper.dark .dropzone-area:hover .upload-icon-circle {
  background: var(--primary-color, #6366f1);
  color: #ffffff;
}
.file-upload-wrapper.dark .upload-headline {
  color: #e2e8f0;
}
.file-upload-wrapper.dark .upload-headline .highlight {
  color: var(--primary-color, #6366f1);
}
.file-upload-wrapper.dark .upload-subtext {
  color: #94a3b8;
}
.file-upload-wrapper.dark .file-queue-list {
  border-top-color: #1f2937;
}
.file-upload-wrapper.dark .queue-header h4 {
  color: #e2e8f0;
}
.file-upload-wrapper.dark .queue-item-card {
  border-color: #1f2937;
  background: #111827;
}
.file-upload-wrapper.dark .queue-item-card:hover {
  border-color: #4b5563;
}
.file-upload-wrapper.dark .queue-item-card.success {
  border-color: rgba(16, 185, 129, 0.2);
}
.file-upload-wrapper.dark .queue-item-card.error {
  border-color: rgba(239, 68, 68, 0.2);
}
.file-upload-wrapper.dark .item-name {
  color: #e2e8f0;
}
.file-upload-wrapper.dark .item-size {
  color: #94a3b8;
}
.file-upload-wrapper.dark .progress-track {
  background: #1e293b;
}
.file-upload-wrapper.dark .progress-bar-fill {
  background: var(--primary-color, #6366f1);
}
.file-upload-wrapper.dark .progress-text {
  color: #94a3b8;
}
.file-upload-wrapper.dark .action-btn:hover {
  background: #1e293b;
  color: #f8fafc;
}
.file-upload-wrapper.dark .action-btn.remove-btn:hover {
  background: rgba(239, 68, 68, 0.1);
}

