  background: var(--ngx-chart-bg, #ffffff);
  border-radius: 16px;
  padding: 16px;
  box-sizing: border-box;
  font-family: var(--ngx-font-family, system-ui, sans-serif);
  position: relative;
  width: 100%;
  transition: background-color 0.3s;
}
.ngx-flowmap.dark {
  background: #0f172a;
  border: 1px solid rgba(255, 255, 255, 0.05);
  --ngx-chart-bg: #0f172a;
  --ngx-chart-tooltip-bg: rgba(15, 23, 42, 0.95);
  --ngx-chart-tooltip-color: #f8fafc;
}
.chart-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
  position: relative;
}
.chart-title h4 {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--ngx-chart-title-color, #1e293b);
}
.dark .chart-title h4 {
  color: #f8fafc;
}

.map-svg {
  display: block;
  overflow: visible;
}

@keyframes flowMoving {
  to {
    stroke-dashoffset: -20;
  }
}

.flow-path {
  stroke-dasharray: 6, 4;
  animation: flowMoving linear infinite;
  cursor: pointer;
}
.flow-node {
  cursor: pointer;
  transition: r 0.2s cubic-bezier(0.16, 1, 0.3, 1), stroke-width 0.15s;
}
.flow-node.hovered {
  filter: drop-shadow(0 4px 10px rgba(0, 0, 0, 0.3));
}

/* Glassmorphic Tooltip */
.chart-tooltip {
  position: absolute;
  pointer-events: none;
  transform: translate(-50%, -100%) translateY(-10px);
  background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.92));
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  color: var(--ngx-chart-tooltip-color, #f8fafc);
  padding: 10px 14px;
  border-radius: 10px;
  font-size: 12px;
  min-width: 170px;
  box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3), 0 8px 10px -6px rgba(0,0,0,0.3);
  border: 1px solid rgba(255, 255, 255, 0.1);
  z-index: 100;
  transition: left 0.1s cubic-bezier(0.16, 1, 0.3, 1), top 0.1s cubic-bezier(0.16, 1, 0.3, 1);
}
.tt-cat {
  font-weight: 700;
  margin-bottom: 6px;
  font-size: 12.5px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  padding-bottom: 4px;
  color: #38bdf8;
}
.tt-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
}
.label-row {
  margin-top: 6px;
  border-top: 1px dashed rgba(255, 255, 255, 0.15);
  padding-top: 4px;
  font-style: italic;
  color: rgba(255, 255, 255, 0.7);
}
.tt-name {
  color: rgba(248, 250, 252, 0.8);
  flex: 1;
}
.tt-val {
  font-weight: 700;
  font-family: monospace;
}

/* Header and Export dropdown styles */
.chart-export-menu {
  position: relative;
  z-index: 50;
}
.export-trigger {
  padding: 4px 10px;
  font-size: 11px;
  font-weight: 600;
  color: var(--ngx-chart-axis-text, #64748b);
  background: rgba(241, 245, 249, 0.8);
  backdrop-filter: blur(8px);
  border: 1px solid var(--ngx-chart-grid, #e2e8f0);
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.15s;
}
.export-trigger:hover {
  background: #ffffff;
  color: #4f46e5;
  border-color: #4f46e5;
}
.export-dropdown {
  position: absolute;
  right: 0;
  top: calc(100% + 4px);
  background: #ffffff;
  border: 1px solid var(--ngx-chart-grid, #e2e8f0);
  border-radius: 8px;
  box-shadow: 0 10px 15px -3px rgba(0,0,0,0.1);
  padding: 4px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 120px;
}
.export-dropdown button {
  background: none;
  border: none;
  padding: 6px 10px;
  font-size: 11px;
  text-align: left;
  cursor: pointer;
  color: #1e293b;
  border-radius: 4px;
  width: 100%;
  transition: all 0.12s;
}
.export-dropdown button:hover {
  background: rgba(79, 70, 229, 0.06);
  color: #4f46e5;
}
.chart-svg-container {
  position: relative;
  width: 100%;
}

