computed(() => {
    const items = this.data();
    const count = items.length;
    if (count === 0) return [];
    const width = this.tickWidth();
    const cellWidth = this.innerW() / count;

    return items.map((item, idx) => {
      const x = this.xPos(idx);
      const centerX = x + cellWidth / 2;

      const yHigh = this.yPos(item.high);
      const yLow = this.yPos(item.low);
      const yClose = this.yPos(item.close);

      let isBullish = true;
      if (idx > 0) {
        isBullish = item.close >= items[idx - 1].close;
      }
      const color = isBullish ? this.bullishColor() : this.bearishColor();

      return {
        x,
        centerX,
        cellWidth,
        width,
        yHigh,
        yLow,
        yClose,
        color,
        isBullish,
        raw: item
      };
    });
  })

signal<{
    x: number;
    y: number;
    date: string | Date;
    high: number;
    low: number;
    close: number;
    direction: 'Bullish' | 'Bearish';
    changePct: string;
  } | null>(null)

computed(() => {
    const items = this.data();
    if (items.length === 0) return 100;
    const highs = items.map(d => d.high);
    const maxVal = Math.max(...highs);
    return maxVal * 1.01; // 1% safety margin
  })

computed(() => {
    const items = this.data();
    if (items.length === 0) return 0;
    const lows = items.map(d => d.low);
    const minVal = Math.min(...lows);
    return minVal * 0.99; // 1% safety margin
  })

