:host {
  display: block;
  width: 100%;
}
.ngx-hollow-candlestick-chart {
  position: relative;
  background: var(--ngx-chart-bg, #ffffff);
  border: 1px solid var(--border-color, #e2e8f0);
  border-radius: 16px;
  padding: 16px;
  box-sizing: border-box;
  font-family: var(--ngx-font-family, system-ui, sans-serif);
}
.chart-svg-container {
  position: relative;
  width: 100%;
}
.chart-svg {
  display: block;
  overflow: visible;
}
.axis-label {
  font-size: 10px;
  fill: #64748b;
  font-weight: 500;
}

@keyframes candleGrow {
  from { transform: scaleY(0); opacity: 0; }
  to { transform: scaleY(1); opacity: 1; }
}

.candle-rect {
  cursor: pointer;
  transition: fill 0.15s, stroke-width 0.15s, filter 0.15s;
  animation: candleGrow 0.5s cubic-bezier(0.16, 1, 0.3, 1) both;
}
.candle-rect.hovered {
  filter: brightness(1.05) drop-shadow(0 4px 8px rgba(0,0,0,0.15));
  stroke-width: 2.5px !important;
}
.crosshair-line {
  pointer-events: none;
}

/* Glassmorphic Tooltip */
.chart-tooltip {
  position: absolute;
  pointer-events: none;
  transform: translate(-50%, -100%) translateY(-10px);
  background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.92));
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  color: var(--ngx-chart-tooltip-color, #f8fafc);
  padding: 10px 14px;
  border-radius: 10px;
  font-size: 11px;
  z-index: 100;
  min-width: 165px;
  box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3), 0 8px 10px -6px rgba(0,0,0,0.3);
  border: 1px solid rgba(255, 255, 255, 0.1);
  transition: left 0.08s ease-out, top 0.08s ease-out;
}
.tooltip-header {
  font-weight: 700;
  margin-bottom: 6px;
  font-size: 12.5px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  padding-bottom: 4px;
  color: #38bdf8;
}
.tooltip-direction {
  font-size: 10px;
  font-weight: 700;
  margin-bottom: 6px;
  text-transform: uppercase;
  letter-spacing: 0.3px;
}
.tooltip-body {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.tooltip-val {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  color: rgba(248, 250, 252, 0.85);
}
.tooltip-val strong {
  color: #f8fafc;
  font-family: monospace;
  font-weight: 700;
}

/* Export styles */
.chart-export-menu {
  position: absolute;
  top: 0;
  right: 0;
  z-index: 50;
}
.export-trigger {
  padding: 4px 10px;
  font-size: 11px;
  font-weight: 600;
  color: var(--ngx-chart-axis-text, #6c757d);
  background: rgba(255, 255, 255, 0.7);
  backdrop-filter: blur(8px);
  border: 1px solid var(--ngx-chart-grid, #ebedf0);
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.15s;
}
.export-trigger:hover {
  background: #fff;
  color: var(--primary-color, #4f46e5);
  border-color: var(--primary-color, #4f46e5);
}
.export-dropdown {
  position: absolute;
  right: 0;
  top: calc(100% + 4px);
