              </div>
            } @else {
              <div class="tt-row">
                <span class="tt-name">Reversal level</span>
                <span class="tt-val">{{ labelFormatter() ? labelFormatter()!(t.val1) : formatNumber(t.val1) }}</span>
              </div>
            }
          }
