  color: #475569;
}

.dark .group-title {
  color: #94a3b8;
}

.group-count {
  font-size: 11px;
  color: #94a3b8;
}

.chevron-icon {
  margin-left: auto;
  color: #94a3b8;
  transition: transform 0.2s ease;
}

.collapsed .chevron-icon {
  transform: rotate(-90deg);
}

.collapsed .ngx-key-value-list__group-header {
  border-bottom-color: transparent;
}

/* ── Rows layout ── */
.ngx-key-value-list__rows {
  display: flex;
  flex-direction: column;
}

.ngx-key-value-list__row {
  display: flex;
  align-items: center;
  padding: 10px 18px;
  border-bottom: 1px solid rgba(0, 0, 0, 0.03);
  font-size: 13px;
  min-height: 42px;
  box-sizing: border-box;
}

.ngx-key-value-list__row:last-child {
  border-bottom: none;
}

.dark .ngx-key-value-list__row {
  border-bottom-color: rgba(255, 255, 255, 0.03);
}

/* Column labels */
.ngx-key-value-list__label {
  width: 35%;
  font-weight: 600;
  color: #64748b;
  padding-right: 16px;
  box-sizing: border-box;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.dark .ngx-key-value-list__label {
  color: #94a3b8;
}

/* Column values */
.ngx-key-value-list__value-container {
  width: 65%;
  display: flex;
  align-items: center;
}

.ngx-key-value-list__value-wrapper {
  display: flex;
  align-items: center;
  gap: 8px;
  max-width: 100%;
}

.ngx-key-value-list__text {
  color: #0f172a;
  font-weight: 500;
}

.dark .ngx-key-value-list__text {
  color: #f1f5f9;
}

/* striped row shading */
.striped .ngx-key-value-list__row:nth-child(even) {
  background: rgba(0, 0, 0, 0.015);
}

.dark.striped .ngx-key-value-list__row:nth-child(even) {
  background: rgba(255, 255, 255, 0.01);
}

/* ── Render types ── */

/* Badges */
.ngx-key-value-list__badge {
  display: inline-flex;
  font-size: 10px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 4px;
  text-transform: capitalize;
}

.ngx-key-value-list__badge.default {
  background: #f1f5f9;
  color: #475569;
}
.ngx-key-value-list__badge.success {
  background: rgba(16, 185, 129, 0.1);
  color: #10b981;
}
.ngx-key-value-list__badge.danger {
  background: rgba(239, 68, 68, 0.1);
  color: #ef4444;
}
.ngx-key-value-list__badge.warning {
  background: rgba(245, 158, 11, 0.1);
  color: #f59e0b;
}
.ngx-key-value-list__badge.info {
  background: rgba(59, 130, 246, 0.1);
  color: #3b82f6;
}

.dark .ngx-key-value-list__badge.default {
  background: rgba(255, 255, 255, 0.08);
  color: #cbd5e1;
}

/* Code blocks */
.ngx-key-value-list__code {
  font-family: monospace;
  font-size: 12px;
  background: #f1f5f9;
  padding: 2px 6px;
  border-radius: 4px;
  color: #e11d48;
  border: 1px solid rgba(0, 0, 0, 0.04);
}

.dark .ngx-key-value-list__code {
  background: rgba(15, 23, 42, 0.5);
  border-color: rgba(255, 255, 255, 0.04);
  color: #f43f5e;
}

/* Copy Button */
.ngx-key-value-list__copy-btn {
  position: relative;
  border: none;
  background: transparent;
  color: #94a3b8;
  padding: 4px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  transition: all 0.2s ease;
}

.ngx-key-value-list__copy-btn:hover {
  background: rgba(0, 0, 0, 0.04);
  color: #475569;
}

.ngx-key-value-list__copy-btn.copied {
  color: #10b981 !important;
}

.dark .ngx-key-value-list__copy-btn:hover {
  background: rgba(255, 255, 255, 0.05);
  color: #e2e8f0;
}

/* Tooltip */
.copied-tooltip {
  position: absolute;
  bottom: 22px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 10px;
  background: #0f172a;
  color: #ffffff;
  padding: 2px 6px;
  border-radius: 4px;
  font-family: var(--ngx-font-family, system-ui, sans-serif);
  white-space: nowrap;
  pointer-events: none;
  animation: tooltipPop 0.15s ease-out forwards;
}

@keyframes tooltipPop {
  from { opacity: 0; transform: translateX(-50%) translateY(4px); }
  to { opacity: 1; transform: translateX(-50%) translateY(0); }
}

/* ── Vertical Layout ── */
.layout-vertical .ngx-key-value-list__row {
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  padding: 12px 18px;
}

.layout-vertical .ngx-key-value-list__label {
  width: 100%;
  padding-right: 0;
}

.layout-vertical .ngx-key-value-list__value-container {
  width: 100%;
}

