:host {
  display: block;
  position: relative;
}
.ngx-network-graph {
  position: relative;
  background: var(--ngx-chart-bg, #fff);
  font-family: inherit;
  overflow: hidden;
  padding: 16px;
  border-radius: 16px;
}
.chart-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 24px;
  position: relative;
  margin-bottom: 8px;
}
.chart-body {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
}
.chart-svg {
  display: block;
  max-width: 100%;
  height: auto;
  min-width: 0;
}
.link-line {
  cursor: pointer;
  transition: stroke 0.2s, stroke-width 0.2s, stroke-opacity 0.2s;
}
.node-group {
  cursor: pointer;
  transition: opacity 0.25s ease;
}
.node-circle {
  transition: r 0.2s, stroke 0.2s, stroke-width 0.2s;
}
.node-group:hover .node-circle {
  filter: drop-shadow(0 4px 8px rgba(0,0,0,0.15));
}
.node-group.dimmed {
  opacity: 0.3;
}
.node-label {
  fill: var(--ngx-chart-text, #1e293b);
  font-size: 11px;
  font-weight: 600;
  pointer-events: none;
  user-select: none;
}
.chart-legend {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex-shrink: 0;
  min-width: 130px;
}
.legend-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
}
.legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 3px;
  flex-shrink: 0;
}
.legend-label {
  color: var(--ngx-chart-text, #1e293b);
  font-weight: 600;
}

/* Premium Glassmorphic Tooltip */
.chart-tooltip {
  position: absolute; pointer-events: none; transform: translate(-50%, -100%) translateY(-8px);
  background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.92));
  backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px);
  color: var(--ngx-chart-tooltip-color, #f8fafc); padding: 10px 14px;
  border-radius: 10px; font-size: 12px; min-width: 150px;
  box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3), 0 8px 10px -6px rgba(0,0,0,0.3);
  border: 1px solid rgba(255, 255, 255, 0.1);
  z-index: 100;
  display: flex; align-items: flex-start; gap: 8px;
  transition: left 0.12s cubic-bezier(0.16, 1, 0.3, 1), top 0.12s cubic-bezier(0.16, 1, 0.3, 1);
  font-family: inherit;
}
.tt-dot { width: 8px; height: 8px; border-radius: 50%; margin-top: 4px; }
.tt-content { display: flex; flex-direction: column; gap: 2px; }
.tt-group { font-size: 10px; color: rgba(248, 250, 252, 0.7); }
.tt-val { font-weight: 700; }

/* Export styles */
.chart-export-menu {
  position: absolute;
  top: 0;
  right: 0;
  z-index: 50;
}
.export-trigger {
  padding: 4px 10px;
  font-size: 11px;
  font-weight: 600;
  color: var(--ngx-chart-axis-text, #6c757d);
  background: rgba(255, 255, 255, 0.7);
  backdrop-filter: blur(8px);
  border: 1px solid var(--ngx-chart-grid, #ebedf0);
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.15s;
}
.export-trigger:hover {
  background: #fff;
  color: var(--primary-color, #4f46e5);
  border-color: var(--primary-color, #4f46e5);
}
.export-dropdown {
  position: absolute;
  right: 0;
  top: calc(100% + 4px);
  background: #fff;
  border: 1px solid var(--ngx-chart-grid, #ebedf0);
  border-radius: 8px;
  box-shadow: 0 10px 15px -3px rgba(0,0,0,0.08);
  padding: 4px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 120px;
}
.export-dropdown button {
  background: none;
  border: none;
  padding: 6px 10px;
  font-size: 11px;
  text-align: left;
  cursor: pointer;
  color: #343a40;
  border-radius: 4px;
  font-family: inherit;
  width: 100%;
  transition: all 0.12s;
}
.export-dropdown button:hover {
  background: rgba(79, 70, 229, 0.06);
  color: var(--primary-color, #4f46e5);
}

