import {
  Component, ChangeDetectionStrategy, input, computed, signal,
  ElementRef, inject, DestroyRef, HostListener, viewChild
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { niceTicks, scale, fmtNum, CHART_COLORS } from '../shared/chart-utils';

export interface OHLCItem {
  date: string | Date;
  open: number;
  high: number;
  low: number;
  close: number;
}

@Component({
  selector: 'ngx-ohlc-chart',
  standalone: true,
  imports: [CommonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="ngx-ohlc-chart" (mouseleave)="hoveredIndex.set(null); tooltip.set(null)">
      <!-- Toolbar with Export option -->
      <div class="chart-header" (mousemove)="$event.stopPropagation()" (mouseleave)="hoveredIndex.set(null); tooltip.set(null)">
        <div class="chart-title-space"></div>
        @if (showExport()) {
          <div class="chart-export-menu">
            <button class="export-trigger" (click)="toggleExportMenu($event)" aria-label="Export Menu">📤 Export</button>
            @if (exportMenuOpen()) {
              <div class="export-dropdown">
                <button (click)="onExport('json')">📊 Export JSON</button>
                <button (click)="onExport('csv')">📄 Export CSV</button>
                <button (click)="onExport('svg')">🖼️ Export SVG</button>
                <button (click)="onExport('pdf')">📕 Export PDF</button>
              </div>
            }
          </div>
        }
      </div>

      <div class="chart-svg-container" #container>
        <svg
          #svgEl
          [attr.width]="'100%'"
          [attr.height]="height()"
          class="chart-svg"
        >
          <g [attr.transform]="'translate(' + PAD_LEFT + ',' + PAD_TOP + ')'">
            <!-- Grid Lines (Horizontal) -->
            @if (showGrid()) {
              @for (tick of yTicks(); track tick) {
                <line
                  [attr.x1]="0"
                  [attr.x2]="innerW()"
                  [attr.y1]="yPos(tick)"
                  [attr.y2]="yPos(tick)"
                  stroke="var(--ngx-chart-grid, #ebedf0)"
                  stroke-dasharray="3,3"
                />
              }
            }

            <!-- Y-Axis Labels -->
            @if (showLabels()) {
              @for (tick of yTicks(); track tick) {
                <text
                  x="-10"
                  [attr.y]="yPos(tick) + 4"
                  class="axis-label y"
                  text-anchor="end"
                >{{ fmtNum(tick) }}</text>
              }
            }

            <!-- X-Axis Labels -->
            @if (showLabels()) {
              @for (item of data(); track $index; let i = $index) {
                @if (shouldShowXLabel(i)) {
                  <text
                    [attr.x]="xPos(i) + tickWidth() / 2"
                    [attr.y]="innerH() + 20"
                    class="axis-label x"
                    text-anchor="middle"
                  >{{ formatDate(item.date) }}</text>
                }
              }
            }

            <!-- Active Crosshair -->
            @if (hoveredIndex() !== null) {
              @if (computedTicks()[hoveredIndex()!]; as tick) {
                <line
                  [attr.x1]="0"
                  [attr.x2]="innerW()"
                  [attr.y1]="tick.yClose"
                  [attr.y2]="tick.yClose"
                  stroke="rgba(100, 116, 139, 0.25)"
                  stroke-width="1.2"
                  stroke-dasharray="3,3"
                  class="crosshair-line"
                />
                <line
                  [attr.x1]="tick.centerX"
                  [attr.x2]="tick.centerX"
                  [attr.y1]="0"
                  [attr.y2]="innerH()"
                  stroke="rgba(100, 116, 139, 0.25)"
                  stroke-width="1.2"
                  stroke-dasharray="3,3"
                  class="crosshair-line"
                />
              }
            }

            <!-- OHLC Ticks -->
            @for (tick of computedTicks(); track $index; let i = $index) {
              <!-- Vertical Line (High to Low) -->
              <line
                [attr.x1]="tick.centerX"
                [attr.y1]="tick.yHigh"
                [attr.x2]="tick.centerX"
                [attr.y2]="tick.yLow"
                [attr.stroke]="tick.color"
                [attr.stroke-width]="hoveredIndex() === i ? 3 : 2"
                class="ohlc-line"
              />

              <!-- Left Tick (Open) -->
              <line
                [attr.x1]="tick.centerX - tick.width / 2"
                [attr.y1]="tick.yOpen"
                [attr.x2]="tick.centerX"
                [attr.y2]="tick.yOpen"
                [attr.stroke]="tick.color"
                [attr.stroke-width]="hoveredIndex() === i ? 3 : 2"
                class="ohlc-line"
              />

              <!-- Right Tick (Close) -->
              <line
                [attr.x1]="tick.centerX"
                [attr.y1]="tick.yClose"
                [attr.x2]="tick.centerX + tick.width / 2"
                [attr.y2]="tick.yClose"
                [attr.stroke]="tick.color"
                [attr.stroke-width]="hoveredIndex() === i ? 3 : 2"
                class="ohlc-line"
              />

              <!-- Transparent Hover Area (UX optimization) -->
              <rect
                [attr.x]="tick.x"
                [attr.y]="0"
                [attr.width]="tick.cellWidth"
                [attr.height]="innerH()"
                fill="transparent"
                style="cursor: pointer;"
                (mouseenter)="onTickHover($event, tick.raw, i)"
                (mousemove)="onTickHover($event, tick.raw, i)"
              />
            }

            <!-- Base axes borders -->
            <line x1="0" [attr.x2]="innerW()" [attr.y1]="innerH()" [attr.y2]="innerH()" stroke="var(--ngx-chart-axis, #ced4da)"/>
            <line x1="0" x2="0" y1="0" [attr.y2]="innerH()" stroke="var(--ngx-chart-axis, #ced4da)"/>
          </g>
        </svg>

        <!-- Tooltip -->
        @if (tooltip(); as t) {
          <div class="chart-tooltip" [style.left.px]="t.x" [style.top.px]="t.y">
            <div class="tooltip-header">{{ formatDate(t.date) }}</div>
            <div class="tooltip-body">
              <div class="tooltip-direction" [style.color]="t.direction === 'Bullish' ? '#10b981' : '#ef4444'">
                <strong>{{ t.direction }}</strong> ({{ t.changePct }})
              </div>
              <div class="tooltip-val">
                <span>High:</span>
                <strong>{{ fmtNum(t.high) }}</strong>
              </div>
              <div class="tooltip-val" style="color: #60a5fa;">
                <span>Open:</span>
                <strong>{{ fmtNum(t.open) }}</strong>
              </div>
              <div class="tooltip-val" style="color: #38bdf8;">
                <span>Close:</span>
                <strong>{{ fmtNum(t.close) }}</strong>
              </div>
              <div class="tooltip-val">
                <span>Low:</span>
                <strong>{{ fmtNum(t.low) }}</strong>
              </div>
            </div>
          </div>
        }
      </div>
    </div>
  `,
  styles: [`
