:host {
  display: block;
  width: 100%;
  height: 100%;
}

.ngx-radar-wrapper {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  padding: 24px;
  background: var(--bg-secondary, #ffffff);
  border: 1px solid var(--border-color, #e2e8f0);
  border-radius: 12px;
  box-shadow: var(--shadow-sm, 0 1px 2px rgba(0,0,0,0.05));
  position: relative;
}

.ngx-radar-container {
  position: relative;
  width: 100%;
  max-width: 280px;
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.ngx-radar-svg {
  width: 100%;
  height: 100%;
  overflow: visible;
}

@keyframes radarScaleIn {
  from { transform: scale(0.1); opacity: 0; }
  to { transform: scale(1); opacity: 1; }
}

/* Radar Polygons styling */
.radar-polygon {
  transition: stroke-width 0.25s cubic-bezier(0.16, 1, 0.3, 1), fill-opacity 0.25s;
  cursor: pointer;
  transform-origin: 110px 110px;
  animation: radarScaleIn 0.8s cubic-bezier(0.16, 1, 0.3, 1) both;
}
.radar-polygon:hover, .radar-polygon.active {
  stroke-width: 3.5px;
}

.radar-dot {
  cursor: pointer;
  transition: r 0.2s cubic-bezier(0.16, 1, 0.3, 1), stroke-width 0.2s;
  transform-origin: 110px 110px;
  animation: radarScaleIn 0.8s cubic-bezier(0.16, 1, 0.3, 1) both;
}
.radar-dot.hovered {
  filter: drop-shadow(0 0 4px rgba(0,0,0,0.25));
  stroke-width: 2px;
}

/* Labels styling */
.axis-label {
  font-size: 8px;
  font-weight: 700;
  fill: var(--text-secondary, #64748b);
  letter-spacing: -0.1px;
}

/* Glassmorphic Tooltip styling */
.radar-tooltip {
  position: absolute;
  z-index: 100;
  pointer-events: none;
  background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.92));
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  color: var(--ngx-chart-tooltip-color, #f8fafc);
  padding: 10px 14px;
  border-radius: 10px;
  font-size: 11px;
