  position: relative;
  width: 100%;
}
.chart-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 24px;
  position: relative;
  margin-bottom: 12px;
}
.ridgeline-svg {
  display: block;
  overflow: visible;
}
.grid-line {
  stroke: var(--ngx-chart-grid, #f1f5f9);
  stroke-width: 1;
}
.axis-line {
  stroke: var(--ngx-chart-axis, #cbd5e1);
  stroke-width: 1.5;
}
.tick-line {
  stroke: var(--ngx-chart-axis, #cbd5e1);
  stroke-width: 1.5;
}
.tick-label {
  font-size: 11px;
  fill: var(--ngx-chart-axis-text, #64748b);
  font-weight: 550;
  user-select: none;
}
.y-axis-label {
  font-size: 12px;
  fill: var(--ngx-chart-axis-text, #334155);
  font-weight: 600;
  user-select: none;
}
.row-baseline {
  stroke: var(--ngx-chart-grid, #e2e8f0);
  stroke-width: 1;
  stroke-dasharray: 2,2;
}
.density-area, .density-line {
  animation: ridgelineWipeIn 1s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  clip-path: inset(0 100% 0 0);
}
@keyframes ridgelineWipeIn {
  to { clip-path: inset(0 0 0 0); }
}
.density-area {
  transition: fill-opacity 0.2s ease;
  cursor: pointer;
}
.density-line {
  transition: stroke-width 0.2s ease;
  cursor: pointer;
}
.ridgeline-row {
  transition: opacity 0.2s ease;
}
.ridgeline-row.dimmed {
  opacity: 0.2;
}
.ridgeline-row.highlighted .density-area {
  fill-opacity: 0.65;
}
.ridgeline-row.highlighted .density-line {
  stroke-width: 3.5;
}

/* Glassmorphic Tooltip */
.chart-tooltip {
  position: absolute;
  pointer-events: none;
  transform: translate(-50%, -100%) translateY(-10px);
  background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.92));
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  color: var(--ngx-chart-tooltip-color, #f8fafc);
  padding: 10px 14px;
  border-radius: 10px;
  font-size: 12px;
  min-width: 160px;
  box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3), 0 8px 10px -6px rgba(0,0,0,0.3);
  border: 1px solid rgba(255, 255, 255, 0.1);
  z-index: 100;
  transition: left 0.1s cubic-bezier(0.16, 1, 0.3, 1), top 0.1s cubic-bezier(0.16, 1, 0.3, 1);
}
.tt-cat {
  font-weight: 700;
  margin-bottom: 6px;
  font-size: 12.5px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  padding-bottom: 4px;
  color: #38bdf8;
}
.tt-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
}
.tt-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
.tt-name {
  color: rgba(248, 250, 252, 0.8);
  flex: 1;
}
.tt-val {
  font-weight: 700;
  font-family: monospace;
}

/* Export Trigger & Dropdown */
.chart-export-menu {
  position: absolute;
  top: 0;
  right: 0;
  z-index: 50;
}
.export-trigger {
  padding: 4px 10px;
  font-size: 11px;
  font-weight: 600;
  color: var(--ngx-chart-axis-text, #6c757d);
  background: rgba(255, 255, 255, 0.7);
  backdrop-filter: blur(8px);
  border: 1px solid var(--ngx-chart-grid, #ebedf0);
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.15s;
}
.export-trigger:hover {
  background: #fff;
  color: #4f46e5;
  border-color: #4f46e5;
}
.export-dropdown {
  position: absolute;
  right: 0;
  top: calc(100% + 4px);
  background: #fff;
  border: 1px solid var(--ngx-chart-grid, #ebedf0);
  border-radius: 8px;
  box-shadow: 0 10px 15px -3px rgba(0,0,0,0.08);
  padding: 4px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 120px;
}
.export-dropdown button {
  background: none;
  border: none;
  padding: 6px 10px;
  font-size: 11px;
  text-align: left;
  cursor: pointer;
  color: #343a40;
  border-radius: 4px;
  font-family: inherit;
  width: 100%;
  transition: all 0.12s;
}
.export-dropdown button:hover {
  background: rgba(79, 70, 229, 0.06);
  color: #4f46e5;
}

