    .ngx-scheduler-wrapper.dark .export-item { color: #cbd5e1; }
    .ngx-scheduler-wrapper.dark .export-item:hover { background: #1e293b; color: #6366f1; }
    .ngx-scheduler-wrapper.dark .resource-name { color: #f8fafc; }
