import {
  Component, ChangeDetectionStrategy, input, computed, signal,
  ElementRef, inject, DestroyRef, viewChild, HostListener
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { CHART_COLORS, fmtNum, scale } from '../shared/chart-utils';

export interface SlopeDataPoint {
  label: string;
  startValue: number;
  endValue: number;
  color?: string;
}

@Component({
  selector: 'ngx-slope-chart',
  standalone: true,
  imports: [CommonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="ngx-slope-chart" (mouseleave)="onMouseLeave()">
      <div class="chart-header" (mousemove)="$event.stopPropagation()" (mouseleave)="onMouseLeave()">
        <div class="chart-title-space"></div>
        @if (showExport()) {
          <div class="chart-export-menu">
            <button class="export-trigger" (click)="toggleExportMenu($event)" aria-label="Export Menu">📤 Export</button>
            @if (exportMenuOpen()) {
              <div class="export-dropdown">
                <button (click)="onExport('json')">📊 Export JSON</button>
                <button (click)="onExport('csv')">📄 Export CSV</button>
                <button (click)="onExport('svg')">🖼️ Export SVG</button>
                <button (click)="onExport('pdf')">📕 Export PDF</button>
              </div>
            }
          </div>
        }
      </div>

      <svg
        #svgEl
        class="slope-svg"
        [attr.width]="'100%'"
        [attr.height]="svgHeight()"
      >
        <g [attr.transform]="'translate(' + margin().left + ',' + margin().top + ')'">
          <!-- Left Axis Line -->
          <line
            [attr.x1]="leftAxisX()"
            [attr.x2]="leftAxisX()"
            [attr.y1]="0"
            [attr.y2]="innerH()"
            class="axis-line"
          />

          <!-- Right Axis Line -->
          <line
            [attr.x1]="rightAxisX()"
            [attr.x2]="rightAxisX()"
            [attr.y1]="0"
            [attr.y2]="innerH()"
            class="axis-line"
          />

          <!-- Axis Labels at Top -->
          <text
            [attr.x]="leftAxisX()"
            [attr.y]="-10"
            text-anchor="middle"
            class="axis-title"
          >
            {{ startLabel() }}
          </text>
          <text
            [attr.x]="rightAxisX()"
            [attr.y]="-10"
            text-anchor="middle"
            class="axis-title"
          >
            {{ endLabel() }}
          </text>

          <!-- Slope Lines & Dots -->
          @for (item of computedItems(); track item.label; let i = $index) {
            <g
              class="slope-group"
              [class.dimmed]="hoveredIndex() !== null && hoveredIndex() !== i"
              [class.highlighted]="hoveredIndex() === i"
              (mouseenter)="onSlopeHover(i, $event)"
              (mousemove)="onSlopeMouseMove($event)"
            >
              <!-- Connecting Slope Line -->
              <line
                [attr.x1]="leftAxisX()"
                [attr.x2]="rightAxisX()"
                [attr.y1]="item.leftY"
                [attr.y2]="item.rightY"
                [attr.stroke]="item.lineColor"
                stroke-width="2.5"
                class="slope-line"
              />

              <!-- Left Endpoint Dot -->
              <circle
                [attr.cx]="leftAxisX()"
                [attr.cy]="item.leftY"
                [attr.r]="hoveredIndex() === i ? 6 : 4"
                [attr.fill]="item.lineColor"
                class="endpoint-dot"
              />

              <!-- Right Endpoint Dot -->
              <circle
                [attr.cx]="rightAxisX()"
                [attr.cy]="item.rightY"
                [attr.r]="hoveredIndex() === i ? 6 : 4"
                [attr.fill]="item.lineColor"
                class="endpoint-dot"
              />

              <!-- Label and Value on Left Axis (Outer Left side) -->
              @if (showLabels()) {
                <text
                  [attr.x]="leftAxisX() - 12"
                  [attr.y]="item.leftY"
                  text-anchor="end"
                  dominant-baseline="middle"
                  class="slope-label left-label"
                >
                  {{ item.label }}
                </text>
              }

              <!-- Value on Left Axis (Inner Left side) -->
              @if (showValues()) {
                <text
                  [attr.x]="leftAxisX() + 10"
                  [attr.y]="item.leftY"
                  text-anchor="start"
                  dominant-baseline="middle"
                  class="slope-value"
                >
                  {{ formatNumber(item.startValue) }}
                </text>
              }

              <!-- Value on Right Axis (Inner Right side) -->
              @if (showValues()) {
                <text
                  [attr.x]="rightAxisX() - 10"
                  [attr.y]="item.rightY"
                  text-anchor="end"
                  dominant-baseline="middle"
                  class="slope-value"
                >
                  {{ formatNumber(item.endValue) }}
                </text>
              }
            </g>
          }
        </g>
      </svg>

      <!-- Glassmorphic Tooltip -->
      @if (tooltip(); as t) {
        <div class="chart-tooltip" [style.left.px]="tooltipX()" [style.top.px]="tooltipY()">
          <div class="tt-cat">{{ t.label }}</div>
          <div class="tt-row">
            <span class="tt-dot" style="background: var(--ngx-chart-axis, #94a3b8);"></span>
            <span class="tt-name">{{ startLabel() }}</span>
            <span class="tt-val">{{ formatNumber(t.startValue) }}</span>
          </div>
          <div class="tt-row">
            <span class="tt-dot" [style.background]="t.lineColor"></span>
            <span class="tt-name">{{ endLabel() }}</span>
            <span class="tt-val">{{ formatNumber(t.endValue) }}</span>
          </div>
          <div class="tt-row delta-row">
            <span class="tt-dot" style="background: transparent;"></span>
            <span class="tt-name">Change</span>
            <span class="tt-val" [style.color]="t.delta >= 0 ? '#10b981' : '#ef4444'">
              {{ t.delta >= 0 ? '+' : '' }}{{ formatNumber(t.delta) }} ({{ t.deltaPct >= 0 ? '+' : '' }}{{ t.deltaPct.toFixed(1) }}%)
            </span>
          </div>
        </div>
      }
    </div>
  `,
  styles: [`
    :host {
      display: block;
    }
    .ngx-slope-chart {
      background: var(--ngx-chart-bg, #ffffff);
      border-radius: 16px;
      padding: 16px;
      box-sizing: border-box;
      font-family: var(--ngx-font-family, system-ui, sans-serif);
      position: relative;
      width: 100%;
    }
    .chart-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      min-height: 24px;
      position: relative;
      margin-bottom: 12px;
    }
    .slope-svg {
      display: block;
      overflow: visible;
    }
    .axis-line {
      stroke: var(--ngx-chart-axis, #cbd5e1);
      stroke-width: 2;
    }
    .axis-title {
      font-size: 13px;
      font-weight: 700;
      fill: var(--ngx-chart-axis-text, #334155);
      letter-spacing: 0.5px;
      user-select: none;
    }
    .slope-line {
      transition: stroke-width 0.2s ease, stroke-dashoffset 0.8s ease, opacity 0.2s ease;
