import { Component, ChangeDetectionStrategy, input, computed, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { CHART_COLORS, scale, smoothPath } from '../shared/chart-utils';

@Component({
  selector: 'ngx-sparkline',
  standalone: true,
  imports: [CommonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <svg
      [attr.width]="width()"
      [attr.height]="height()"
      class="ngx-sparkline"
      [attr.aria-label]="'Sparkline'"
      (mousemove)="onMouseMove($event)"
      (mouseleave)="hoveredIndex.set(null)"
    >
      <defs>
        <linearGradient id="sparkline-grad" x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" [attr.stop-color]="color()" stop-opacity="0.32" />
          <stop offset="100%" [attr.stop-color]="color()" stop-opacity="0" />
        </linearGradient>
      </defs>

      @if (type() === 'line' || type() === 'area') {
        @if (type() === 'area') {
          <path [attr.d]="areaPath()" fill="url(#sparkline-grad)" stroke="none" class="sparkline-area"/>
        }
        <path
          [attr.d]="linePath()"
          [attr.stroke]="color()"
          fill="none"
          stroke-width="2"
          stroke-linejoin="round"
          stroke-linecap="round"
          class="sparkline-path"
        />
        <!-- End dot (if not hovered) -->
        @if (endPoint(); as ep) {
          @if (hoveredIndex() === null) {
            <circle [attr.cx]="ep[0]" [attr.cy]="ep[1]" r="3" [attr.fill]="color()" class="end-dot"/>
          }
        }
      }
      @if (type() === 'bar') {
        @for (item of barItems(); track $index; let idx = $index) {
          <rect
            [attr.x]="item.x"
            [attr.y]="item.y"
            [attr.width]="item.w"
            [attr.height]="item.h"
            [attr.fill]="color()"
            [attr.rx]="1"
            [class.hovered]="hoveredIndex() === idx"
            [style.animation-delay]="(idx * 0.02) + 's'"
            class="sparkline-bar"
          />
        }
      }

      <!-- Interactive Tracker overlay -->
      @if (activePoint(); as ap) {
        <!-- Vertical guide line -->
        <line
          [attr.x1]="ap[0]"
          [attr.x2]="ap[0]"
          [attr.y1]="PAD"
          [attr.y2]="PAD + h()"
          stroke="rgba(100, 116, 139, 0.25)"
          stroke-width="1.2"
          stroke-dasharray="2,2"
          class="tracker-line"
        />
        <!-- Outer glowing ring -->
        <circle
          [attr.cx]="ap[0]"
          [attr.cy]="ap[1]"
          r="5"
          [attr.fill]="color()"
          fill-opacity="0.25"
          class="tracker-ring"
        />
        <!-- Inner solid dot -->
        <circle
          [attr.cx]="ap[0]"
          [attr.cy]="ap[1]"
          r="2.5"
          [attr.fill]="color()"
          stroke="#ffffff"
          stroke-width="1"
          class="tracker-dot"
        />
      }
    </svg>
  `,
  styles: [`
    :host {
      display: inline-block;
    }
    .ngx-sparkline {
      display: block;
      overflow: visible;
      cursor: crosshair;
    }

    @keyframes lineDraw {
      from { stroke-dashoffset: 400; }
      to { stroke-dashoffset: 0; }
    }
    .sparkline-path {
