      font-size: 28px;
      line-height: 1;
      margin-bottom: 2px;
      user-select: none;
    }

    /* ── Label ── */
    .ngx-stat-card__label {
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      color: var(--ngx-stat-label-color, hsl(220, 15%, 55%));
    }
    .dark .ngx-stat-card__label {
      color: var(--ngx-stat-label-dark-color, hsl(220, 15%, 60%));
