      color: var(--ngx-stat-value-color, hsl(220, 25%, 14%));
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }
    .dark .ngx-stat-card__value {
      color: var(--ngx-stat-value-dark-color, hsl(220, 20%, 94%));
    }

