:host {
  display: block;
  position: relative;
}
.ngx-sunburst-chart {
  position: relative;
  background: var(--ngx-chart-bg, #ffffff);
  border-radius: 16px;
  padding: 16px;
  box-sizing: border-box;
  font-family: var(--ngx-font-family, system-ui, sans-serif);
  transition: background-color 0.3s;
}
.ngx-sunburst-chart.dark {
  background: rgba(30, 32, 48, 0.45);
  border: 1px solid rgba(255, 255, 255, 0.05);
  --ngx-chart-bg: transparent;
}
.chart-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 20px;
  position: relative;
}
.chart-body {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 32px;
  flex-wrap: wrap;
}
.chart-svg {
  display: block;
  max-width: 100%;
  height: auto;
  min-width: 0;
  animation: sunburstGrow 0.8s cubic-bezier(0.16, 1, 0.3, 1) both;
  transform-origin: center;
}

@keyframes sunburstGrow {
  from { transform: scale(0.3) rotate(-120deg); opacity: 0; }
  to { transform: scale(1) rotate(0); opacity: 1; }
}

.sunburst-slice {
  cursor: pointer;
  transition: fill-opacity 0.2s, stroke 0.2s, filter 0.25s;
}
.sunburst-slice:hover {
  fill-opacity: 0.9;
  filter: drop-shadow(0 4px 8px rgba(0, 0, 0, 0.2));
}
.slice-label {
  font-size: 9px;
  fill: #ffffff;
  font-weight: 700;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.6);
  user-select: none;
}

.chart-legend {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex-shrink: 0;
  min-width: 160px;
}
.legend-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  padding: 4px 8px;
  border-radius: 6px;
  transition: background-color 0.15s;
}
.legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 3px;
  flex-shrink: 0;
}
.legend-label {
  flex: 1;
  color: #64748b;
  font-weight: 500;
}
.dark .legend-label {
  color: #94a3b8;
}
.legend-val {
  font-weight: 700;
  color: #334155;
}
.dark .legend-val {
  color: #cbd5e1;
}

/* Premium Glassmorphic Tooltip */
.chart-tooltip {
  position: absolute;
  pointer-events: none;
  transform: translate(-50%, -100%) translateY(-10px);
  background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.92));
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  color: var(--ngx-chart-tooltip-color, #f8fafc);
  padding: 10px 14px;
  border-radius: 10px;
  font-size: 11px;
  z-index: 100;
  min-width: 160px;
  box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3), 0 8px 10px -6px rgba(0,0,0,0.3);
  border: 1px solid rgba(255, 255, 255, 0.1);
  transition: left 0.1s cubic-bezier(0.16, 1, 0.3, 1), top 0.1s cubic-bezier(0.16, 1, 0.3, 1);
}
.tt-path {
  font-weight: 700;
  margin-bottom: 6px;
  font-size: 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  padding-bottom: 4px;
  color: #38bdf8;
}
.tt-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
}
.tt-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
.tt-name {
  color: rgba(248, 250, 252, 0.8);
  flex: 1;
}
.tt-val {
  font-weight: 700;
  font-family: monospace;
}

/* Export styles */
.chart-export-menu {
  position: absolute;
  top: 0;
  right: 0;
  z-index: 50;
}
.export-trigger {
  padding: 4px 10px;
  font-size: 11px;
  font-weight: 600;
  color: var(--ngx-chart-axis-text, #6c757d);
  background: rgba(255, 255, 255, 0.7);
  backdrop-filter: blur(8px);
  border: 1px solid var(--ngx-chart-grid, #ebedf0);
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.15s;
}
.export-trigger:hover {
  background: #fff;
  color: #4f46e5;
  border-color: #4f46e5;
}
.export-dropdown {
  position: absolute;
  right: 0;
  top: calc(100% + 4px);
  background: #fff;
  border: 1px solid var(--ngx-chart-grid, #ebedf0);
  border-radius: 8px;
  box-shadow: 0 10px 15px -3px rgba(0,0,0,0.08);
  padding: 4px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 120px;
}
.export-dropdown button {
  background: none;
  border: none;
  padding: 6px 10px;
  font-size: 11px;
  text-align: left;
  cursor: pointer;
  color: #343a40;
  border-radius: 4px;
  font-family: inherit;
  width: 100%;
  transition: all 0.12s;
}
.export-dropdown button:hover {
  background: rgba(79, 70, 229, 0.06);
  color: #4f46e5;
}

