          @if (!disabled()) {
            <button
              type="button"
              class="ngx-tag-chip__remove"
              (click)="removeTag(tag, $event)"
              [attr.aria-label]="'Remove ' + tag"
            >✕</button>
          }
        </span>
      }

      <!-- Text input -->
      @if (!isAtMax()) {
        <input
          #tagInput
