import {
  Component, input, output, signal, computed, ChangeDetectionStrategy,
  ElementRef, viewChild, HostListener
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { CHART_COLORS } from '../shared/chart-utils';

@Component({
  selector: 'ngx-token-streaming-chart',
  standalone: true,
  imports: [CommonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="ngx-token-stream-wrapper">
      <div class="chart-header" (mousemove)="$event.stopPropagation()">
        <div class="chart-title-space">
          <div class="stream-title">
            <span class="pulse-indicator"></span>
            {{ title() }}
          </div>
          <div class="stream-subtitle">
            TPS: <span class="highlight-val">{{ currentTps() }}</span> | Total Tokens: <span class="highlight-val">{{ points().length }}</span>
          </div>
        </div>
        @if (showExport()) {
          <div class="chart-export-menu">
            <button class="export-trigger" (click)="toggleExportMenu($event)" aria-label="Export Menu">📤 Export</button>
            @if (exportMenuOpen()) {
              <div class="export-dropdown">
                <button (click)="onExport('json')">📊 Export JSON</button>
                <button (click)="onExport('csv')">📄 Export CSV</button>
                <button (click)="onExport('svg')">🖼️ Export SVG</button>
                <button (click)="onExport('pdf')">📕 Export PDF</button>
              </div>
            }
          </div>
        }
      </div>

      <div class="ngx-token-stream-container">
        <svg
          #svgEl
          class="ngx-token-stream-svg"
          [attr.viewBox]="viewBoxString()"
          preserveAspectRatio="none"
          (mousemove)="onMouseMove($event)"
          (mouseleave)="hoveredIndex.set(null)"
        >
          <!-- Grid Lines (Horizontal) -->
          @for (yVal of gridYLines(); track yVal) {
            <line
              [attr.x1]="viewBoxX()"
              [attr.x2]="viewBoxX() + chartWidth"
              [attr.y1]="yVal"
              [attr.y2]="yVal"
              class="grid-line"
            />
          }

          <!-- Area under path (linear gradient) -->
          <defs>
            <linearGradient id="stream-area-grad" x1="0%" y1="0%" x2="0%" y2="100%">
              <stop offset="0%" [attr.stop-color]="colors()[0]" stop-opacity="0.25" />
              <stop offset="100%" [attr.stop-color]="colors()[0]" stop-opacity="0" />
            </linearGradient>
          </defs>

          @if (points().length > 1) {
            <!-- Shaded Area -->
            <path
              [attr.d]="areaPath()"
              fill="url(#stream-area-grad)"
              stroke="none"
            />

            <!-- Stroke Path -->
            <path
              [attr.d]="linePath()"
              [attr.stroke]="colors()[0]"
              stroke-width="2.5"
              fill="none"
              stroke-linejoin="round"
              stroke-linecap="round"
            />
          }

          <!-- Guide / Tracker elements -->
          @if (activePoint(); as ap) {
            <line
              [attr.x1]="ap.x"
              [attr.x2]="ap.x"
              [attr.y1]="0"
              [attr.y2]="height()"
              class="tracker-guide-line"
            />
            <circle
              [attr.cx]="ap.x"
              [attr.cy]="ap.y"
              r="6"
              [attr.fill]="colors()[0]"
              fill-opacity="0.3"
              class="tracker-glowing-ring"
            />
            <circle
              [attr.cx]="ap.x"
              [attr.cy]="ap.y"
              r="3"
              [attr.fill]="colors()[0]"
              stroke="#ffffff"
              stroke-width="1"
            />
          }
        </svg>

        <!-- Glassmorphic Tooltip -->
        @if (activePoint(); as ap) {
          <div
            class="stream-tooltip"
            [style.left.px]="ap.screenX"
            [style.top.px]="ap.screenY"
          >
            <div class="tt-cat">Token #{{ ap.index + 1 }}</div>
            <div class="tt-row">
              <span class="tt-dot" [style.background]="colors()[0]"></span>
              <span class="tt-name">Speed / Value</span>
              <span class="tt-val">{{ ap.val.toFixed(1) }} ms/tok</span>
            </div>
            <div class="tt-row action-row">
              <button class="tt-action-btn" (click)="onTooltipAction(ap.index, ap.val)">
                Ask Agent to Analyze
              </button>
            </div>
          </div>
        }
      </div>
    </div>
  `,
  styles: [`
    :host {
      display: block;
      width: 100%;
      height: 100%;
    }
    .ngx-token-stream-wrapper {
      width: 100%;
      height: 100%;
      padding: 16px 20px;
      background: var(--bg-secondary, #ffffff);
      border: 1px solid var(--border-color, #e2e8f0);
      border-radius: 12px;
      box-shadow: var(--shadow-sm, 0 1px 2px rgba(0,0,0,0.05));
      position: relative;
    }
    .ngx-token-stream-container {
      position: relative;
      width: 100%;
      overflow: hidden;
    }
    .ngx-token-stream-svg {
      width: 100%;
      height: 100%;
      display: block;
      overflow: visible;
      cursor: crosshair;
    }
    .grid-line {
      stroke: var(--ngx-chart-grid, #e2e8f0);
      stroke-width: 1px;
      stroke-dasharray: 4,4;
    }
    .tracker-guide-line {
      stroke: rgba(99, 102, 241, 0.4);
      stroke-width: 1px;
      stroke-dasharray: 2,2;
      pointer-events: none;
    }
    .tracker-glowing-ring {
      pointer-events: none;
      animation: ringPulse 1.2s infinite alternate;
    }
    @keyframes ringPulse {
      from { r: 5px; fill-opacity: 0.2; }
      to { r: 8px; fill-opacity: 0.5; }
    }

    /* Header and Subtitles */
    .chart-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 16px;
    }
    .stream-title {
      font-size: 14px;
      font-weight: 700;
      color: var(--text-primary, #1e293b);
      display: flex;
      align-items: center;
      gap: 6px;
    }
    .stream-subtitle {
      font-size: 11px;
      color: var(--text-secondary, #64748b);
      margin-top: 2px;
    }
    .highlight-val {
      font-weight: 700;
      color: #6366f1;
      font-family: monospace;
    }
    .pulse-indicator {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: #22c55e;
      box-shadow: 0 0 0 0 rgba(34, 197, 94, 0.7);
      animation: pulse 1.5s infinite;
    }
    @keyframes pulse {
      0% {
        transform: scale(0.95);
        box-shadow: 0 0 0 0 rgba(34, 197, 94, 0.7);
      }
      70% {
        transform: scale(1);
        box-shadow: 0 0 0 6px rgba(34, 197, 94, 0);
      }
      100% {
        transform: scale(0.95);
        box-shadow: 0 0 0 0 rgba(34, 197, 94, 0);
      }
    }

    /* Glassmorphic Tooltip styling */
    .stream-tooltip {
      position: absolute;
      z-index: 100;
      background: var(--ngx-chart-tooltip-bg, rgba(15, 23, 42, 0.92));
      backdrop-filter: blur(12px);
