    nodeMap.forEach(node => {
      if (node.parentId && nodeMap.has(node.parentId)) {
        nodeMap.get(node.parentId)!.children.push(node);
      } else {
        // Assume first node with no valid parent is root
        if (!root) root = node;
      }
    });

    if (!root && nodeMap.size > 0) {
