computed(() => {
    const is3 = this.isThreeSets();
    const w = this.innerW();
    const h = this.innerH();
    const cols = this.colors();

    if (!is3) {
      // 2 circles
      const r = Math.min(w, h) * 0.32;
      const cxA = w / 2 - r * 0.45;
      const cxB = w / 2 + r * 0.45;
      const cy = h / 2;

      return [
        { id: 'A', cx: cxA, cy, r, color: cols[0] || '#4a90d9' },
        { id: 'B', cx: cxB, cy, r, color: cols[1] || '#ff6358' }
      ];
    } else {
      // 3 circles
      const r = Math.min(w, h) * 0.28;
      const cxA = w / 2;
      const cyA = h / 2 - r * 0.38;
      const cxB = w / 2 - r * 0.45;
      const cyB = h / 2 + r * 0.4;
      const cxC = w / 2 + r * 0.45;
      const cyC = h / 2 + r * 0.4;

      return [
        { id: 'A', cx: cxA, cy: cyA, r, color: cols[0] || '#4a90d9' },
        { id: 'B', cx: cxB, cy: cyB, r, color: cols[1] || '#ff6358' },
        { id: 'C', cx: cxC, cy: cyC, r, color: cols[2] || '#27ae60' }
      ];
    }
  })

computed<VennRegion[]>(() => {
    const is3 = this.isThreeSets();
    const sizeMap = this.sizes();
    const circs = this.circles();
    const labels = this.sets();
    const cols = this.colors();

    const labelA = labels[0] || 'A';
    const labelB = labels[1] || 'B';

    if (!is3) {
      const cA = circs[0];
      const cB = circs[1];

      return [
        {
          key: 'A',
          label: `${labelA} only`,
          value: sizeMap['A'] ?? 100,
          color: cA.color,
          textX: cA.cx - cA.r * 0.4,
          textY: cA.cy - 5
        },
        {
          key: 'B',
          label: `${labelB} only`,
          value: sizeMap['B'] ?? 80,
          color: cB.color,
          textX: cB.cx + cB.r * 0.4,
          textY: cB.cy - 5
        },
        {
          key: 'A&B',
          label: 'Overlap',
          value: sizeMap['A&B'] ?? 30,
          color: cols[2] || '#f39c12',
          textX: (cA.cx + cB.cx) / 2,
          textY: cA.cy - 5
        }
      ];
    } else {
      const labelC = labels[2] || 'C';
      const cA = circs[0];
      const cB = circs[1];
      const cC = circs[2];

      return [
        {
          key: 'A',
          label: `${labelA} only`,
          value: sizeMap['A'] ?? 120,
          color: cA.color,
          textX: cA.cx,
          textY: cA.cy - cA.r * 0.45
        },
        {
          key: 'B',
          label: `${labelB} only`,
          value: sizeMap['B'] ?? 100,
          color: cB.color,
          textX: cB.cx - cB.r * 0.4,
          textY: cB.cy + cB.r * 0.25
        },
        {
          key: 'C',
          label: `${labelC} only`,
          value: sizeMap['C'] ?? 90,
          color: cC.color,
          textX: cC.cx + cC.r * 0.4,
          textY: cC.cy + cC.r * 0.25
        },
        {
          key: 'A&B',
          label: `${labelA} ∩ ${labelB}`,
          value: sizeMap['A&B'] ?? 40,
          color: cols[3] || '#f39c12',
          textX: (cA.cx + cB.cx) / 2 - 10,
          textY: (cA.cy + cB.cy) / 2 - 10
        },
        {
          key: 'B&C',
          label: `${labelB} ∩ ${labelC}`,
          value: sizeMap['B&C'] ?? 30,
          color: cols[4] || '#8e44ad',
          textX: (cB.cx + cC.cx) / 2,
          textY: (cB.cy + cC.cy) / 2 + 15
        },
        {
          key: 'A&C',
          label: `${labelA} ∩ ${labelC}`,
          value: sizeMap['A&C'] ?? 25,
          color: cols[5] || '#1abc9c',
          textX: (cA.cx + cC.cx) / 2 + 10,
          textY: (cA.cy + cC.cy) / 2 - 10
        },
        {
          key: 'A&B&C',
          label: 'Intersection',
          value: sizeMap['A&B&C'] ?? 15,
          color: '#34495e',
          textX: cA.cx,
          textY: (cA.cy + cB.cy) / 2 + 5
        }
      ];
    }
  })

