:host {
  display: block;
}
.ngx-violin-plot {
  background: var(--ngx-chart-bg, #ffffff);
  border-radius: 16px;
  padding: 16px;
  box-sizing: border-box;
  font-family: var(--ngx-font-family, system-ui, sans-serif);
  position: relative;
  width: 100%;
}
.chart-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 24px;
  position: relative;
  margin-bottom: 12px;
}
.violin-svg {
  display: block;
  overflow: visible;
}
.grid-line {
  stroke: var(--ngx-chart-grid, #f1f5f9);
  stroke-width: 1;
}
.axis-line {
  stroke: var(--ngx-chart-axis, #cbd5e1);
  stroke-width: 1.5;
}
.tick-line {
  stroke: var(--ngx-chart-axis, #cbd5e1);
  stroke-width: 1.5;
}
.tick-label, .x-axis-label {
  font-size: 11px;
  fill: var(--ngx-chart-axis-text, #64748b);
  font-weight: 550;
  user-select: none;
}
.violin-path {
  transition: fill-opacity 0.2s ease, stroke-width 0.2s ease;
  cursor: pointer;
  transform-origin: bottom;
  animation: violinScaleIn 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
}
@keyframes violinScaleIn {
  from { transform: scaleX(0); opacity: 0; }
  to { transform: scaleX(1); opacity: 1; }
}
.jitter-point {
  animation: pointFadeIn 0.5s ease forwards;
  opacity: 0;
}
@keyframes pointFadeIn {
  from { opacity: 0; transform: scale(0); }
  to { opacity: 1; transform: scale(1); }
}
.violin-group {
  transition: opacity 0.2s ease;
}
.violin-group.dimmed {
  opacity: 0.3;
}
.violin-group.highlighted .violin-path {
  fill-opacity: 0.5;
  stroke-width: 2.5;
}

