  padding-bottom: 4px;
  color: #38bdf8;
}
.tt-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
}
.tt-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
