:host {
  display: block;
  position: relative;
}
.ngx-wind-rose {
  background: var(--ngx-chart-bg, #ffffff);
  border-radius: 16px;
  padding: 16px;
  box-sizing: border-box;
  font-family: var(--ngx-font-family, system-ui, sans-serif);
  position: relative;
  width: 100%;
}
.chart-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
  min-height: 24px;
  position: relative;
}
.header-info {
  display: flex;
  flex-direction: column;
}
.header-title {
  font-size: 14px;
  font-weight: 700;
  color: var(--ngx-chart-axis-text, #334155);
  display: block;
}
.header-subtitle {
  font-size: 11px;
  color: var(--ngx-chart-axis-text, #64748b);
  font-weight: 550;
}
.rose-svg {
  display: block;
  overflow: visible;
}
.grid-circle {
  stroke: var(--ngx-chart-grid, #f1f5f9);
  stroke-width: 1;
  fill: none;
}
.grid-label {
  font-size: 9px;
  fill: var(--ngx-chart-axis-text, #94a3b8);
  font-weight: 600;
}
.spoke-line {
  stroke: var(--ngx-chart-grid, #e2e8f0);
  stroke-width: 1;
  stroke-dasharray: 2,2;
}
.direction-label {
  font-size: 11px;
  fill: var(--ngx-chart-axis-text, #475569);
  font-weight: 700;
  user-select: none;
}
.rose-wedge {
  cursor: pointer;
  transform-origin: center;
  animation: wedgeScaleIn 0.8s cubic-bezier(0.34, 1.3, 0.64, 1) forwards;
  opacity: 0;
}
@keyframes wedgeScaleIn {
  from { transform: scale(0); opacity: 0; }
  to { transform: scale(1); opacity: 1; }
}
.rose-wedge.dimmed {
  opacity: 0.25 !important;
}
.rose-wedge.highlighted {
  stroke: var(--ngx-chart-axis-strong, #475569) !important;
  stroke-width: 1px !important;
}
.legend-container {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  margin-top: 14px;
  padding-top: 10px;
  border-top: 1px solid var(--ngx-chart-grid, #f1f5f9);
}
.legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
}
.legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 2px;
}
.legend-text {
  font-size: 11px;
  color: var(--ngx-chart-axis-text, #475569);
  font-weight: 600;
}

